// Completion outranks idle on the quiet branches (#4124).
//
// `complete` was derived only from RUNTIME session signals — an `ended` verdict of `done`, or an
// explicit maintenance park. Both describe a session, and sessions end. The issues do not. So a worker
// that finished its lane read `idle` (live but quiet) or `off` (session reclaimed) — the same words a
// node with nothing to do reports, which is how "idle won against completed".
import { describe, it, expect } from "vitest";
import { applyFleetLiveStatus } from "@/features/glance/lib/agentStall";
import type { GRawNode } from "@/features/glance/lib/glanceGraph";

const node = (id: string, progress?: { done: number; total: number }): GRawNode =>
  ({ id, slug: id, role: "service", health: "off", activity: "idle", progress }) as GRawNode;

const sig = (over: Partial<Parameters<typeof applyFleetLiveStatus>[2]> = {}) => ({
  livePaneIds: new Set<string>(), paneStatus: {}, waiting: [], now: 0, ...over,
}) as Parameters<typeof applyFleetLiveStatus>[2];

const only = (nodes: GRawNode[], s = sig()) => applyFleetLiveStatus(nodes, "proj", s)[0];

describe("a finished worker never reads idle (#4124)", () => {
  it("reads COMPLETE when its session is gone, not `off`", () => {
    // `off` means never launched. A worker that finished and was then reclaimed is not that.
    const out = only([node("api", { done: 3, total: 3 })]);
    expect(out.health).toBe("complete");
    expect(out.activity).toBe("complete");
  });

  it("reads COMPLETE when its session is live but quiet, not `idle`", () => {
    const out = only([node("api", { done: 2, total: 2 })], sig({ livePaneIds: new Set(["proj:api"]) }));
    expect(out.health).toBe("complete");
    expect(out.activity).toBe("complete");
  });

  it("still reads OFF when there is no session AND work remains", () => {
    const out = only([node("api", { done: 1, total: 3 })]);
    expect(out.health).toBe("off");
    expect(out.activity).toBe("idle");
  });

  it("still reads IDLE when a live session has work left", () => {
    const out = only([node("api", { done: 1, total: 3 })], sig({ livePaneIds: new Set(["proj:api"]) }));
    expect(out.health).toBe("healthy");
    expect(out.activity).toBe("idle");
  });

  it("a node owning NO issues is unaffected — completion is not vacuously true", () => {
    // 0/0 must not read as finished, or every unplanned node in the graph would claim completion.
    expect(only([node("standing", { done: 0, total: 0 })]).health).toBe("off");
    expect(only([node("standing")]).health).toBe("off");
  });

  it("a session actively BUILDING still reads building", () => {
    // What it is doing right now is the more urgent fact — even with its planned issues closed, which
    // is exactly the maintenance case.
    const out = only(
      [node("api", { done: 2, total: 2 })],
      sig({ livePaneIds: new Set(["proj:api"]), paneStatus: { "proj:api": "run" } }),
    );
    expect(out.activity).toBe("building");
  });

  it("a QUARANTINED worker still reads error — completion never hides something to act on", () => {
    const out = only(
      [node("api", { done: 2, total: 2 })],
      sig({ quarantined: { "proj:api": { summary: "drifted" } } } as never),
    );
    expect(out.health).toBe("error");
  });

  it("a worker parked on a QUESTION still reads waiting", () => {
    // Blocked on a person outranks finished: the park is what needs resolving.
    const out = only(
      [node("api", { done: 2, total: 2 })],
      sig({ livePaneIds: new Set(["proj:api"]), waiting: [{ session: "proj:api", at: 0, reason: "which repo?" }] } as never),
    );
    expect(out.activity).toBe("waiting");
  });

  it("a MAINTAINING worker reads complete even after its session is reclaimed (#4124)", () => {
    // THE ONE THAT WAS ACTUALLY BITING. The maintaining branch sat BELOW the `!livePaneIds` gate, so it
    // was unreachable for exactly the worker it describes: a maintenance park means "finished, standing
    // by", and a standing-by session is the first thing a reaper or a restart takes. Once the pane left
    // `livePaneIds` the node fell to `off`/`idle`. Measured: 34 panes have emitted `maintain`.
    const out = only(
      [node("api")],                                   // no progress data at all — the signal is the park
      sig({ maintaining: new Set(["proj:api"]) } as never),
    );
    expect(out.health).toBe("complete");
    expect(out.activity).toBe("complete");
  });

  it("a maintaining worker whose session IS live still reads complete", () => {
    const out = only(
      [node("api")],
      sig({ livePaneIds: new Set(["proj:api"]), maintaining: new Set(["proj:api"]) } as never),
    );
    expect(out.health).toBe("complete");
  });

  it("maintenance still loses to quarantine — something to act on outranks finished", () => {
    const out = only(
      [node("api")],
      sig({ maintaining: new Set(["proj:api"]), quarantined: { "proj:api": { summary: "drifted" } } } as never),
    );
    expect(out.health).toBe("error");
  });

  it("says WHY, so the state is discoverable from the node's own reason", () => {
    expect(only([node("api", { done: 3, total: 3 })]).reason).toMatch(/every owned issue complete/);
  });
});

// The Algorithms rail's FOLDER TREE (#4107, brought to components parity by #4128). Before #4107 the
// rail had exactly one level — each LANGUAGE was a folder — so all 50 Rust impls sat flat inside it. It
// now nests the way the Components rail does, from the harvested source layout, through the SAME shared
// `buildFolderTree` + `RailFolderRow` the Designs rail renders — including the folder tooltip
// (`folder: <path>`) and the trailing "ungrouped" bucket.
import { describe, it, expect } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { AlgorithmsRail } from "@/features/algorithms/AlgorithmsRail";
import { UNGROUPED_LABEL } from "@/shared/lib/core/folderTree";
import { buildKnowledge, type AlgoImpl } from "@/features/algorithms/lib/knowledge";

const im = (o: Partial<AlgoImpl> & Pick<AlgoImpl, "id" | "tech" | "name">): AlgoImpl =>
  ({ role: "algorithm", composes: [], ...o });

const noop = () => {};

const foldered = buildKnowledge({
  implementations: [
    im({ id: "job.rs", tech: "rust", name: "attachJob", folder: "src-tauri/src/console/pty" }),
    im({ id: "perf.rs", tech: "rust", name: "sample", folder: "src-tauri/src/observability" }),
  ],
});

const renderRail = (graph: ReturnType<typeof buildKnowledge>) =>
  render(<AlgorithmsRail graph={graph} activeTech="rust" selectedImpl={null} onSelectImpl={noop} />);

describe("AlgorithmsRail folder tree (#4107/#4128)", () => {
  it("nests the harvested folders under the language, tooltipped like the components rail", () => {
    // Sections default to OPEN, so the whole tree is visible without a click. The `folder: ` tooltip
    // prefix is the shared `RailFolderRow`'s — the algorithms rail used a bare path before #4128.
    renderRail(foldered);
    expect(screen.getByTitle("folder: src-tauri")).toBeInTheDocument();
    expect(screen.getByTitle("folder: src-tauri/src")).toBeInTheDocument();
    expect(screen.getByTitle("folder: src-tauri/src/console")).toBeInTheDocument();
    expect(screen.getByTitle("folder: src-tauri/src/console/pty")).toBeInTheDocument();
    expect(screen.getByTitle("folder: src-tauri/src/observability")).toBeInTheDocument();
    // The impls sit inside their folders, not flat under the language.
    expect(screen.getByText("attachJob")).toBeInTheDocument();
    expect(screen.getByText("sample")).toBeInTheDocument();
  });

  it("collapsing a folder hides its whole subtree", () => {
    // What keeps a harvested library (hundreds of impls across dozens of folders) cheap to render.
    renderRail(foldered);
    fireEvent.click(screen.getByTitle("folder: src-tauri/src/observability"));
    expect(screen.queryByText("sample")).toBeNull();
    expect(screen.getByText("attachJob")).toBeInTheDocument();   // its sibling branch is untouched
  });

  it("a collapsed folder still reports how much is inside it", () => {
    renderRail(foldered);
    fireEvent.click(screen.getByTitle("folder: src-tauri"));      // collapse the root
    expect(screen.queryByText("attachJob")).toBeNull();
    // The count is the whole SUBTREE (2), not the root folder's own impls (0) — otherwise a deep tree
    // gives no sense of where the work lives.
    expect(screen.getByTitle("folder: src-tauri").textContent).toContain("2");
  });

  it("buckets unfoldered impls into a trailing `ungrouped` folder, not a flat spill (#4128)", () => {
    // The components rail has always done this; the algorithms rail used to render them loose beside the
    // tree. It matters HERE more than there: the seeded classics carry no `src`, so in the live library
    // the unfoldered set is the majority, and loose rows next to folders read as two competing lists.
    const mixed = buildKnowledge({
      implementations: [
        im({ id: "job.rs", tech: "rust", name: "attachJob", folder: "src-tauri/src/console/pty" }),
        im({ id: "merge.rs", tech: "rust", name: "merge" }),
      ],
    });
    renderRail(mixed);
    const bucket = screen.getByTitle("records with no folder");
    expect(bucket).toBeInTheDocument();
    expect(bucket.textContent).toContain(UNGROUPED_LABEL);
    expect(screen.getByText("merge")).toBeInTheDocument();
    // Collapsing the bucket hides its rows, exactly like any other folder.
    fireEvent.click(bucket);
    expect(screen.queryByText("merge")).toBeNull();
    expect(screen.getByText("attachJob")).toBeInTheDocument();
  });

  it("still lists a WHOLLY unfoldered library flat — no bucket, no blank folder", () => {
    // The zero-regression case: a library that has never been foldered renders as the plain list it
    // always did rather than collapsing under one `ungrouped` node.
    const flat = buildKnowledge({ implementations: [im({ id: "merge.rs", tech: "rust", name: "merge" })] });
    renderRail(flat);
    expect(screen.getByText("merge")).toBeInTheDocument();
    expect(screen.queryByTitle("folder: src-tauri")).toBeNull();
    expect(screen.queryByTitle("records with no folder")).toBeNull();
  });
});

/**
 * @vitest-environment jsdom
 *
 * This file lives under `lib/`, which vitest's `node` project covers, but it genuinely needs a DOM.
 * A per-file docblock beats the project's environment, so the requirement is stated where a reader
 * meets it. See the `projects` split in vitest.config.ts for why the default is `node` here.
 */
import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { KitRenderer, type GeneralNode } from "@/shared/ui/spec";
import { makeAnalyticsEmit, componentAnalyticsLookup, collectingSink } from "@/features/designs/lib/analyticsEmit";

// The end-to-end proof: a spec composed from an INSTRUMENTED component auto-emits its declared event when
// the action fires — through the SAME renderer studio pages + generated specs use. Nothing in the spec
// says "record"; emission is derived from the manifest at the render seam (#3816, epic #3809 slice 3).

const buttonSpec: GeneralNode = {
  type: "Button",
  props: { children: "Go" },
  actions: { onClick: "go" },
};

const lookup = componentAnalyticsLookup([
  { name: "Button", analytics: [{ event: "click", props: [{ name: "label", type: "string", req: false, desc: "" }] }] },
]);

describe("KitRenderer analytics emit seam", () => {
  it("records the declared event when the action fires, and still dispatches the handler", () => {
    const go = vi.fn();
    const sink = collectingSink();
    render(<KitRenderer node={buttonSpec} on={{ go }} emit={makeAnalyticsEmit(lookup, sink)} />);

    fireEvent.click(screen.getByText("Go"));

    // Dispatch to the host callback is unaffected.
    expect(go).toHaveBeenCalledTimes(1);
    // And the manifest-driven event was recorded. A click's MouseEvent carries no analytics payload, so
    // props is empty — the runtime records the event name without fabricating a payload it cannot see.
    expect(sink.records).toEqual([{ event: "click", props: {} }]);
  });

  it("is inert with no emit hook — the default render path is unchanged", () => {
    const go = vi.fn();
    render(<KitRenderer node={buttonSpec} on={{ go }} />);
    expect(() => fireEvent.click(screen.getByText("Go"))).not.toThrow();
    expect(go).toHaveBeenCalledTimes(1);
  });

  it("does not record when the component declares no matching event", () => {
    const go = vi.fn();
    const sink = collectingSink();
    // A lookup with no `click` event for Button → the fire resolves to nothing.
    const emptyLookup = componentAnalyticsLookup([{ name: "Button" }]);
    render(<KitRenderer node={buttonSpec} on={{ go }} emit={makeAnalyticsEmit(emptyLookup, sink)} />);

    fireEvent.click(screen.getByText("Go"));

    expect(go).toHaveBeenCalledTimes(1);
    expect(sink.records).toEqual([]);
  });
});

import { describe, it, expect } from "vitest";
import { PROJECT_MODES } from "@/features/planner/list/projectModes";
import { WORKSPACES } from "@/app/registry";

// #548 / #1876: the Projects page modes — formerly the `ProjectsPageModeStrip`, now the data behind
// the shared <Screen> tab bar (`PROJECT_MODES`, rendered in features/planner/index.tsx).
describe("Projects page modes (#548, #1876)", () => {
  it("offers PROJECTS ALONE — every graph left for its own rail Workspace", () => {
    // The Planner had accumulated six tabs. Five of them were graphs folded in on the reasoning that
    // "a single read-only page needs no rail destination of its own" (Design Studio #move-to-planner,
    // Algorithms #2785, Teams #2199/#2700, Sounds #3072, Data). That is reversed by
    // `five-graphs-become-rail-workspaces`: the graphs ARE the app, so each is a rail destination and
    // the Planner keeps only what it is for — planning projects.
    expect(PROJECT_MODES.map((m) => m.label)).toEqual(["Projects"]);
  });

  it("every departed tab is reachable as a live Workspace, so nothing was merely deleted", () => {
    // The half that matters. Removing a tab whose destination does not exist would take the surface
    // away rather than move it — and it would look identical here, because this file only ever
    // asserted what the Planner offers.
    const live = new Set(WORKSPACES.map((w) => w.key as string));
    for (const key of ["components", "teams", "algorithms", "sounds", "data"]) {
      expect(live.has(key), `${key} left the Planner but is not a live Workspace`).toBe(true);
    }
  });

  it("does not include the retired Blueprints / Summary / Data Models / Personas / Fleet modes", () => {
    // Blueprints folded into the Planner tab's blueprint rail; Summary moved to the GitHub screen;
    // Data Models archived with the data-platform panes (5def26b7); Personas folded into Org (#2199);
    // Fleet analytics moved to Glance (#2223/#2228).
    const labels = PROJECT_MODES.map((m) => m.label);
    for (const gone of ["Blueprints", "Summary", "Data Models", "Personas", "Fleet"]) {
      expect(labels).not.toContain(gone);
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  filterBlueprints, makeBlueprints, resolveProjectSeed, refreshBuiltIns, RETIRED_BLUEPRINT_IDS,
  type Blueprint,
} from "@/features/planner/stages/blueprints";
import { blueprintIcon, blueprintHue } from "@/features/planner/list/blueprintLibrary.helpers";

const bp = (id: string, name: string, over: Partial<Blueprint> = {}): Blueprint =>
  ({ id, name, desc: "", sections: [], ...over });

describe("the built-in blueprint library (#645/#3785)", () => {
  it("carries no lifecycle category — that left the blueprint model for discovery (#3785)", () => {
    // A blueprint is a goal/domain ROUTE now; lifecycle is discovered per project
    // (`ClassifyConfig.lifecycle`, #3784). Guard that nothing re-introduces the field.
    for (const b of makeBlueprints()) {
      expect(b, `${b.id} carries no category`).not.toHaveProperty("category");
    }
  });

  it("gives every built-in a DISTINCT tile glyph (#3785)", () => {
    const all = makeBlueprints();
    expect(all.find((b) => b.id === "default")!.mode).toBe("create");
    // Distinct per-domain glyphs are what replaced the one category-derived icon every card shared.
    // `blueprintIcon` is what the card actually renders: the declared `icon`, else the generic
    // grid — so `default` (the blank route, which declares none) reads as generic, by design.
    const icons = all.map(blueprintIcon);
    expect(new Set(icons).size, `distinct glyphs: ${icons.join(", ")}`).toBe(all.length);
  });

  it("drops RETIRED blueprint ids, so a stale config mirror cannot resurrect one (#3840)", () => {
    // Deleting the packaged JSON is not enough: `overlayGlob` APPENDS any config-dir file whose stem
    // it does not recognise, so an orphaned mirror copy re-introduces the blueprint on every install
    // that once shipped it — and `refreshBuiltIns` then treats it as code-owned. The tombstone is
    // what actually retires an id.
    const ids = makeBlueprints().map((b) => b.id);
    for (const dead of RETIRED_BLUEPRINT_IDS) {
      expect(ids, `${dead} is retired`).not.toContain(dead);
    }
    // …and a persisted copy is pruned from the store, not just hidden from the fresh library.
    const persisted = RETIRED_BLUEPRINT_IDS.map((id) =>
      ({ id, name: id, desc: "", origin: "built-in" as const, sections: [] }));
    const kept = refreshBuiltIns(persisted).map((b) => b.id);
    for (const dead of RETIRED_BLUEPRINT_IDS) expect(kept).not.toContain(dead);
  });

  it("gives every built-in a DISTINCT tile COLOUR (#3838)", () => {
    // The glyph alone was doing all the work: no packaged blueprint declared `h`, so every card
    // fell through to `blueprintHue`'s single fallback and all six tiles rendered the same amber.
    // (Older than #3823 — before it the colour came from the equally-degenerate `category`, which
    // was "greenfield" on every built-in.) A new blueprint without a hue must fail here, loudly,
    // rather than silently joining the fallback.
    const all = makeBlueprints();
    for (const b of all) expect(b.h, `${b.id} declares an accent hue`).toBeTypeOf("number");
    const hues = all.map((b) => blueprintHue(b.h));
    expect(new Set(hues).size, `distinct colours: ${hues.join(", ")}`).toBe(all.length);
  });

  it("the default blueprint's deployment stage is enabled so it shows in the plan (#672/#1914)", () => {
    const def = makeBlueprints().find((b) => b.id === "default")!;
    const deployment = def.sections.find((s) => s.key === "deployment")!;
    expect(deployment.enabled).toBe(true);
  });

  it("the default blueprint's skills stage is optional; ui/source/mcps/automations are required (#3785/#3905/#4249)", () => {
    const def = makeBlueprints().find((b) => b.id === "default")!;
    // #4249: `ui` LEFT the optional set. It carried both flags — `optional: true` AND
    // `appliesWhen: requiresUi` — and they mean opposite things: `optional` makes a stage always
    // applicable but skippable, while `appliesWhen` makes it `na` unless its signal fires. Carrying
    // both meant a project that genuinely needs a UI could skip the whole in-app pipeline. Now
    // `requiresUi` (= the stage is on AND the appType has screens) is the only thing deciding, so the
    // stage is absent for a CLI/API/library and REQUIRED for an app — which is the point of migrating
    // the Default blueprint onto the in-app designer.
    expect(def.sections.find((s) => s.key === "ui")!.optional).not.toBe(true);
    // #3905: skills JOINED them. It was non-optional, so its gate blocked triage on any project that
    // had attached no skills — and there is nothing to confirm on an empty stage. It self-enables
    // instead: `needsSkills || projectSkillCount > 0` in usePlanGates, so attaching any skill brings
    // the stage back. Optional here means "not a gate", not "unreachable".
    expect(def.sections.find((s) => s.key === "skills")!.optional).toBe(true);
    // #3785: Default absorbed Complete's advanced stages. These stay non-optional — hidden by default
    // via their `appliesWhen` signals rather than the `optional` flag.
    for (const key of ["ui", "source", "mcps", "automations"]) {
      const sec = def.sections.find((s) => s.key === key);
      expect(sec, `default has ${key}`).toBeTruthy();
      expect(sec!.optional, `${key} is not optional`).not.toBe(true);
    }
  });

  it("refreshBuiltIns updates stale persisted built-ins but keeps user blueprints (#677)", () => {
    // a stale persisted built-in (a bare UI section) + a user blueprint
    const stale: Blueprint = { id: "default", name: "Default", desc: "old", origin: "built-in",
      sections: [{ uid: "x", key: "ui", name: "UI", glyph: "▣", icon: "design_services", hue: 350, gate: "", deps: [], blurb: "", prompt: "", enabled: true, expanded: false }] };
    const mine: Blueprint = { id: "mine", name: "Mine", desc: "", origin: "local", sections: [] };
    const out = refreshBuiltIns([stale, mine]);
    // the built-in is refreshed from code → the UI section picks the packaged def back up, which
    // since #4249 is NOT optional (`requiresUi` alone decides whether it applies).
    expect(out.find((b) => b.id === "default")!.sections.find((s) => s.key === "ui")!.optional).not.toBe(true);
    expect(out.find((b) => b.id === "default")!.sections.find((s) => s.key === "ui")!.appliesWhen?.signal).toBe("requiresUi");
    // the user blueprint's content is preserved (refreshBuiltIns now canonicalizes section keys, #1914,
    // so it's a content-equal copy rather than the same reference)
    expect(out.find((b) => b.id === "mine")).toStrictEqual(mine);
    // #3785 made `default` the greenfield superset; #3783 adds the domain greenfields. refreshBuiltIns
    // refreshes the persisted `default` and APPENDS the new code-owned built-ins (ordered by `order`).
    expect(out.filter((b) => b.origin === "built-in").map((b) => b.id))
      .toEqual(["default", "crm", "erp", "helpdesk", "hr", "project-management"]);
  });

  it("prunes persisted built-ins that no longer exist in code, keeps user blueprints (#923)", () => {
    // a removed built-in (fullstack) lingering in the persisted store + a user blueprint
    const removed: Blueprint = { id: "fullstack", name: "Full-stack", desc: "", origin: "built-in", sections: [] };
    const mine: Blueprint = { id: "mine", name: "Mine", desc: "", origin: "local", sections: [] };
    const out = refreshBuiltIns([removed, mine]);
    expect(out.some((b) => b.id === "fullstack")).toBe(false); // pruned
    expect(out.find((b) => b.id === "mine")).toStrictEqual(mine); // user blueprint content preserved (#1914)
  });

  it("tags every built-in blueprint origin=built-in (#658)", () => {
    const all = makeBlueprints();
    expect(all.every((b) => b.origin === "built-in")).toBe(true);
    // The packaged set after #3785 consolidation + #3783: the greenfield superset Default plus the
    // five domain greenfields. (Complete + the transform/harden/data blueprints were merged in / archived.)
    for (const id of ["default", "crm", "erp", "helpdesk", "hr", "project-management"]) {
      expect(all.find((b) => b.id === id)!.origin, id).toBe("built-in");
    }
  });
});

describe("resolveProjectSeed — blueprint tracking for the reset prompt (#647 fix)", () => {
  it("a brand-new project (no config) seeds + records the active blueprint", () => {
    expect(resolveProjectSeed(false, undefined, "default")).toEqual({ seedConfig: true, setBlueprintId: "default" });
  });
  it("an existing project with NO recorded blueprint backfills to default (ignoring the active id)", () => {
    // A non-default active proves the backfill goes to `default` regardless of what's active.
    expect(resolveProjectSeed(true, undefined, "other")).toEqual({ seedConfig: false, setBlueprintId: "default" });
  });
  it("an existing project that already knows its blueprint changes nothing", () => {
    expect(resolveProjectSeed(true, "other", "default")).toEqual({ seedConfig: false });
  });
});

describe("filterBlueprints (#645, category facet dropped in #3785)", () => {
  const list = [
    bp("a", "Default", { desc: "balanced start" }),
    bp("b", "Refactor & Cleanup", { tags: ["dead-code"] }),
    bp("c", "Harden security"),
  ];

  it("returns everything for an empty query", () => {
    expect(filterBlueprints(list, {})).toHaveLength(3);
    expect(filterBlueprints(list, { query: "  " })).toHaveLength(3);
  });
  it("filters by free-text across name/desc/tags", () => {
    expect(filterBlueprints(list, { query: "refactor" }).map((b) => b.id)).toEqual(["b"]);
    expect(filterBlueprints(list, { query: "dead-code" }).map((b) => b.id)).toEqual(["b"]); // tag
    expect(filterBlueprints(list, { query: "harden" }).map((b) => b.id)).toEqual(["c"]); // name
    expect(filterBlueprints(list, { query: "balanced" }).map((b) => b.id)).toEqual(["a"]); // desc
  });
  it("is case-insensitive", () => {
    expect(filterBlueprints(list, { query: "REFACTOR" }).map((b) => b.id)).toEqual(["b"]);
  });
});

import { describe, it, expect } from "vitest";
import { resolveSkillContent, buildSkillContext, collectBlueprintSkillIds } from "@/features/planner/blueprints/blueprintSkills";
import { mkStageSection } from "@/features/planner/blueprints/blueprintEdit";
import type { SkillDef } from "@/features/skills/lib/skills";
import type { Blueprint } from "@/features/planner/stages/blueprints";

const skill = (id: string, name: string, prompt: string): SkillDef => ({
  id, name, kind: "procedure", source: "local", desc: "", prompt, tools: [], profiles: [],
  projects: [], enabled: true, pinned: false, invocations: 0, success: 0, avgTokensK: 0, lastUsed: "", trend: [],
} as unknown as SkillDef);

const SKILLS = [
  skill("s1", "API design", "Prefer REST; version every endpoint."),
  skill("k1", "House style", "2-space indent; no default exports."),
];

