//! PARITY AGAINST THE REAL TREES, not against inputs somebody thought of.
//!
//! A fixture written by hand proves two implementations agree on the cases its author imagined.
//! This corpus was captured from the repository's ACTUAL build trees — 18 worktrees, ~450 GB of
//! `target/`, 3,396 real artifact filenames, 297 real incremental directories, and 19 real
//! worktrees covering parked, merged, detached-HEAD and main — and every expected value was produced
//! by CALLING the live JavaScript this crate replaces, never by writing down what it ought to say.
//!
//! ## Why the input is FROZEN
//!
//! Other trees on this box compile continuously. Running the JavaScript and then the Rust against
//! the live filesystem would disagree for reasons that have nothing to do with the port, and the
//! disagreement would be unfalsifiable. So the state was snapshotted once and both implementations
//! answered the SAME bytes.
//!
//! ## Why the capture is trustworthy
//!
//! The generator had to re-walk the trees itself, which is a second chance to be wrong. It is
//! checked against the drivers' own output: the JavaScript CLIs printed `would prune 231 of 297`,
//! `would sweep 135 dep unit(s)` and `nothing to remove`, and the frozen snapshot reproduces 231 of
//! 297, 135 and 0 exactly. A capture that gathered something else could not have matched all four.
//!
//! ## What this file is FOR, now that the JavaScript is gone
//!
//! It has changed role, the same way every fixture in this migration does. While both
//! implementations existed it was a parity proof. Now it is a REGRESSION BASELINE — and it is the
//! only place these policies are pinned against inputs nobody invented, which is exactly the
//! evidence the unit tests beside each module cannot supply.

use bsc_disk::pool::{plan_cap, Tree, DEFAULT_MIN_IDLE_MS};
use bsc_disk::prune::{plan_prune, Entry};
use bsc_disk::unit::group_units;

fn corpus() -> serde_json::Value {
    let raw = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/real-trees.parity.json"));
    serde_json::from_str(raw).expect("the parity corpus is valid JSON")
}

fn entries(v: &serde_json::Value) -> Vec<Entry> {
    v.as_array()
        .expect("entries is an array")
        .iter()
        .map(|e| Entry::new(e["n"].as_str().expect("n"), e["m"].as_f64().expect("m")))
        .collect()
}

fn strings(v: &serde_json::Value) -> Vec<String> {
    v.as_array().expect("array").iter().map(|s| s.as_str().expect("string").to_string()).collect()
}

#[test]
fn the_corpus_is_the_real_thing_and_stays_that_way() {
    // A shrunken corpus would let every assertion below pass while measuring almost nothing — the
    // "green gate that sees less" this repo keeps getting caught by. These floors are the sizes
    // actually captured; a future edit that guts the corpus fails here rather than silently.
    let c = corpus();
    assert!(c["prune"]["entries"].as_array().unwrap().len() >= 297, "the incremental corpus shrank");
    assert!(c["sweep"]["entries"].as_array().unwrap().len() >= 3396, "the deps corpus shrank");
    assert_eq!(c["cap"]["trees"].as_array().unwrap().len(), 19, "the worktree corpus changed size");

    // The three shapes that make this corpus worth having, rather than a bag of plausible names.
    let names: Vec<&str> =
        c["sweep"]["entries"].as_array().unwrap().iter().map(|e| e["n"].as_str().unwrap()).collect();
    assert!(
        names.iter().any(|n| n.starts_with("liblibduckdb_sys-")),
        "the libduckdb-sys family is the case that makes `strip a leading lib` wrong"
    );
    assert!(
        names.iter().any(|n| bsc_disk::unit::parse_unit_file(n).is_none()),
        "the corpus must contain un-hashed copies, the names $BSC_BIN resolves BY"
    );
    let trees = c["cap"]["trees"].as_array().unwrap();
    assert!(trees.iter().any(|t| t["branch"].is_null()), "a detached HEAD must be represented");
    assert!(trees.iter().any(|t| t["merged"] == true), "a merged tree must be represented");
    assert!(trees.iter().any(|t| t["isMain"] == true), "the main tree must be represented");
}

#[test]
fn plan_prune_agrees_with_the_javascript_on_297_real_incremental_dirs() {
    let c = corpus();
    let got = plan_prune(
        &entries(&c["prune"]["entries"]),
        c["prune"]["days"].as_f64().unwrap(),
        c["prune"]["keep"].as_u64().unwrap() as usize,
        c["nowMs"].as_f64().unwrap(),
    );
    // WHOLE VALUES IN ORDER, not a set and not a count. `prune` is ordered oldest-first so a
    // truncated log shows the stalest first, and two implementations can agree on "231" while
    // disagreeing about WHICH 231.
    assert_eq!(got.prune, strings(&c["prune"]["expectedPrune"]));
    assert_eq!(got.keep, strings(&c["prune"]["expectedKeep"]));
    assert_eq!(got.prune.len(), 231, "the count the JavaScript CLI printed");
}

#[test]
fn group_units_agrees_with_the_javascript_on_3396_real_deps_files() {
    let c = corpus();
    let units = group_units(&entries(&c["sweep"]["entries"]));
    let keys: Vec<String> = units.iter().map(|u| u.key.clone()).collect();
    assert_eq!(keys, strings(&c["sweep"]["expectedUnitKeys"]), "unit grouping, in order");
}

#[test]
fn the_deps_sweep_agrees_with_the_javascript_on_the_real_units() {
    let c = corpus();
    let units = group_units(&entries(&c["sweep"]["entries"]));
    let keys: Vec<Entry> = units.iter().map(|u| Entry::new(u.key.clone(), u.mtime_ms)).collect();
    let got = plan_prune(
        &keys,
        c["sweep"]["days"].as_f64().unwrap(),
        c["sweep"]["keep"].as_u64().unwrap() as usize,
        c["nowMs"].as_f64().unwrap(),
    );
    assert_eq!(got.prune, strings(&c["sweep"]["expectedPrune"]));
    assert_eq!(got.prune.len(), 135, "the count the JavaScript CLI printed");
}

fn cap_trees(c: &serde_json::Value) -> Vec<Tree> {
    c["cap"]["trees"]
        .as_array()
        .expect("trees")
        .iter()
        .map(|t| Tree {
            name: t["name"].as_str().expect("name").to_string(),
            branch: t["branch"].as_str().map(String::from),
            blocked: t["blocked"].as_str().map(String::from),
            last_built_ms: t["lastBuiltMs"].as_f64().unwrap_or(0.0),
            last_active_ms: t["lastActiveMs"].as_f64().unwrap_or(0.0),
            merged: t["merged"].as_bool().unwrap_or(false),
            is_main: t["isMain"].as_bool().unwrap_or(false),
        })
        .collect()
}

#[test]
fn plan_cap_agrees_with_the_javascript_on_19_real_worktrees() {
    let c = corpus();
    let trees = cap_trees(&c);
    let now = c["nowMs"].as_f64().unwrap();

    // The DEFAULT policy: on this pool it removes nothing, because every tree had been touched
    // inside the six-hour idle window. That is a real answer and worth pinning — "nothing to
    // remove" is the output a broken implementation produces too, so the aggressive arm below is
    // what makes this one meaningful.
    let default = plan_cap(&trees, 2, DEFAULT_MIN_IDLE_MS, now);
    assert_eq!(default.remove, strings(&c["cap"]["expectedDefaultRemove"]));

    // THE ARM THAT ACTUALLY DISCRIMINATES: guards off, so the full collectable set and its ORDER
    // are exercised — 7 trees, oldest-built first, spanning parked and merged branches, while the
    // main tree, `develop`, the detached HEAD and every unlanded ref are excluded.
    let aggressive = plan_cap(&trees, 0, 0.0, now);
    let expected = strings(&c["cap"]["expectedAggressiveRemove"]);
    assert_eq!(aggressive.remove, expected, "the collectable set and its order");
    assert_eq!(aggressive.remove.len(), 7);

    // Never, under the most permissive settings the CLI can express.
    for tree in &trees {
        if tree.is_main || tree.branch.is_none() || tree.branch.as_deref() == Some("develop") {
            assert!(
                !aggressive.remove.contains(&tree.name),
                "{} must never be collectable ({:?})",
                tree.name,
                tree.branch
            );
        }
    }
}

// ── the dedupe arm ───────────────────────────────────────────────────────────────────────────────
//
// Kept separate because it is the one verb a LIVE comparison could not settle. Run side by side
// against the real pool, the two JavaScript runs differed from EACH OTHER by 182 files while 495
// files vanished mid-scan under concurrent builds in other trees — more drift than the gap being
// measured, which makes the comparison unfalsifiable rather than merely noisy. Freezing the input is
// what turns it back into evidence.

use bsc_disk::dedupe::{plan_dedupe, reclaimable_bytes, ArtifactFile};
use std::collections::HashSet;

fn dedupe_files(c: &serde_json::Value) -> Vec<ArtifactFile> {
    let trees: Vec<&str> =
        c["dedupe"]["trees"].as_array().unwrap().iter().map(|t| t.as_str().unwrap()).collect();
    c["dedupe"]["files"]
        .as_array()
        .expect("files")
        .iter()
        .map(|f| {
            let a = f.as_array().expect("[treeIdx, name, size, mtimeMs, ino]");
            let tree = trees[a[0].as_u64().unwrap() as usize];
            let name = a[1].as_str().unwrap().to_string();
            ArtifactFile {
                tree: tree.to_string(),
                path: std::path::PathBuf::from(format!("{tree}/target/debug/deps/{name}")),
                name,
                size: a[2].as_u64().unwrap(),
                mtime_ms: a[3].as_f64().unwrap(),
                // Carried as a STRING: an inode can exceed what a JSON number holds exactly, and a
                // silently-rounded inode would make two distinct files look already-linked.
                ino: a[4].as_str().unwrap().parse().expect("inode"),
            }
        })
        .collect()
}

#[test]
fn plan_dedupe_agrees_with_the_javascript_on_a_real_cross_tree_cross_section() {
    let c = corpus();
    let workspace: HashSet<String> = c["dedupe"]["workspaceCrates"]
        .as_array()
        .expect("workspaceCrates")
        .iter()
        .map(|s| s.as_str().unwrap().to_string())
        .collect();
    assert!(workspace.contains("bsc_util"), "the workspace set must be the real one");

    let files = dedupe_files(&c);
    assert!(files.len() >= 1538, "the dedupe corpus shrank");

    let got = plan_dedupe(
        &files,
        &workspace,
        c["dedupe"]["minAgeMs"].as_f64().unwrap(),
        c["dedupe"]["nowMs"].as_f64().unwrap(),
    );

    let expected = c["dedupe"]["expectedGroups"].as_array().expect("expectedGroups");
    assert_eq!(got.len(), expected.len(), "group count");

    let trees: Vec<&str> =
        c["dedupe"]["trees"].as_array().unwrap().iter().map(|t| t.as_str().unwrap()).collect();
    // WHOLE VALUES IN ORDER — the group order is load-bearing (largest reclaimable first, so an
    // interrupted run has saved the most it could) and so is the order WITHIN a group, because
    // `files[0]` is the canonical copy every other one is linked TO.
    for (i, (g, want)) in got.iter().zip(expected).enumerate() {
        let w = want.as_array().expect("[name, size, treeIdxs]");
        assert_eq!(g.name, w[0].as_str().unwrap(), "group {i} name");
        assert_eq!(g.size, w[1].as_u64().unwrap(), "group {i} size");
        let want_trees: Vec<&str> =
            w[2].as_array().unwrap().iter().map(|t| trees[t.as_u64().unwrap() as usize]).collect();
        let got_trees: Vec<&str> = g.files.iter().map(|f| f.tree.as_str()).collect();
        assert_eq!(got_trees, want_trees, "group {i} ({}) membership and order", g.name);
    }

    // And the number the CLI actually reports.
    assert!(reclaimable_bytes(&got) > 0, "a real cross-section must have something to reclaim");
}

#[test]
fn the_workspace_exclusion_is_load_bearing_on_the_real_cross_section() {
    // Not a tautology: with the real workspace set, our OWN crates must be absent from every group.
    // Cargo folds the absolute manifest path into their `-C metadata`, so they differ per tree and
    // could never match anyway — but they also rebuild constantly, which is when linking is least
    // welcome, so this is correctness rather than caution.
    let c = corpus();
    let workspace: HashSet<String> = c["dedupe"]["workspaceCrates"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| s.as_str().unwrap().to_string())
        .collect();
    let got = plan_dedupe(
        &dedupe_files(&c),
        &workspace,
        c["dedupe"]["minAgeMs"].as_f64().unwrap(),
        c["dedupe"]["nowMs"].as_f64().unwrap(),
    );
    for g in &got {
        let parsed = bsc_disk::unit::parse_unit_file(&g.name).expect("every group name is hashed");
        assert!(
            !bsc_disk::dedupe::is_workspace_crate(&parsed.name_part, &workspace),
            "{} is a workspace crate and must never be a dedupe candidate",
            g.name
        );
    }
}

//! The posture checker against the REAL monitor Pi.
//!
//! The fixtures in `tests/fixtures/monitor-pi/` are verbatim `/proc/net/*`
//! tables captured from the live sensor (Raspberry Pi 5, Debian 13, aarch64)
//! on 2026-09-04, alongside `ss -ltun` output taken from the same host at the
//! same moment. This test asserts the checker's verdict matches what `ss`
//! independently reported.
//!
//! ## Why this is worth its weight
//!
//! Everything else about the posture checker is exercised against fixtures I
//! wrote. Those prove the parser does what I intended; they cannot prove I
//! understood the format the target platform actually emits. This one is
//! captured from the machine the code will run on, on a different
//! architecture and a different distribution from the development box, and
//! checked against a tool that parses those tables independently.
//!
//! `ss` reported exactly six listening sockets on the sensor:
//!
//! ```text
//! tcp 0.0.0.0:22      tcp [::]:22
//! udp 0.0.0.0:42607   udp 0.0.0.0:5353
//! udp *:39727         udp *:5353
//! ```

use bsc_lan_sense::posture::{assess, Posture};
use bsc_lan_sense::procnet::{parse_table, Protocol, Reach, Role};

fn table(name: &str, proto: Protocol) -> bsc_lan_sense::procnet::Table {
    let text = std::fs::read_to_string(
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/monitor-pi")
            .join(name),
    )
    .unwrap_or_else(|e| panic!("fixture {name} is readable: {e}"));
    parse_table(&text, proto).unwrap_or_else(|e| panic!("fixture {name} parses: {e}"))
}

fn all_tables() -> Vec<Result<bsc_lan_sense::procnet::Table, bsc_lan_sense::ProcNetError>> {
    vec![
        Ok(table("tcp", Protocol::Tcp)),
        Ok(table("tcp6", Protocol::Tcp)),
        Ok(table("udp", Protocol::Udp)),
        Ok(table("udp6", Protocol::Udp)),
    ]
}

#[test]
fn every_row_the_real_sensor_emits_is_understood() {
    // The whole point of the row counts: a parser that stopped matching on the
    // target platform would report zero listeners, which reads as a hardened
    // box. Assert nothing was skipped.
    for (name, proto) in [
        ("tcp", Protocol::Tcp),
        ("tcp6", Protocol::Tcp),
        ("udp", Protocol::Udp),
        ("udp6", Protocol::Udp),
    ] {
        let t = table(name, proto);
        assert!(t.rows_seen > 0, "{name} fixture has no data rows");
        assert_eq!(
            t.rows_parsed, t.rows_seen,
            "{name}: understood only {} of {} rows from a real Pi 5 running Debian 13 — \
             the format on the target platform differs from what this parser expects",
            t.rows_parsed, t.rows_seen
        );
    }
}

#[test]
fn the_verdict_matches_what_ss_reported_on_the_same_host() {
    let p = assess(&all_tables());
    match p {
        Posture::Exposed { reachable, rows_examined } => {
            assert!(rows_examined > 0);
            // `ss -ltun` found exactly six listening sockets on the sensor.
            assert_eq!(
                reachable.len(),
                6,
                "expected the six listeners ss reported, got: {:?}",
                reachable.iter().map(|s| (&s.local_addr, s.local_port)).collect::<Vec<_>>()
            );
            let mut ports: Vec<u16> = reachable.iter().map(|s| s.local_port).collect();
            ports.sort_unstable();
            assert_eq!(ports, vec![22, 22, 5353, 5353, 39727, 42607]);

            // Every one is a wildcard bind — a real way in, not loopback.
            for s in &reachable {
                assert_eq!(s.reach, Reach::Wildcard, "{}:{}", s.local_addr, s.local_port);
                assert!(s.is_network_reachable_inbound());
            }
        }
        Posture::Sealed { .. } => panic!(
            "the checker called the sensor SEALED while ss showed six listeners including \
             sshd on 0.0.0.0:22 — this is the silent-pass failure the design exists to prevent"
        ),
        Posture::Unknown { reason } => panic!("could not assess real tables: {reason}"),
    }
}

/// The sensor is NOT currently sealed, and that is the honest starting point
/// for the work: it runs sshd, avahi and a dhcp client, all reachable.
#[test]
fn the_sensor_is_not_yet_sealed_and_the_checker_says_so_plainly() {
    let p = assess(&all_tables());
    assert!(!p.is_sealed());
    assert!(p.needs_attention(), "a box with sshd on a wildcard address wants attention");
}

/// An ESTABLISHED inbound connection is not an additional way in — the LISTEN
/// socket is the surface, and the conversation is its consequence. The capture
/// contains a live SSH session to 10.99.5.10:22, so this is exercised for
/// real rather than hypothetically.
#[test]
fn an_established_connection_is_not_counted_as_another_listening_surface() {
    let t = table("tcp", Protocol::Tcp);
    let established: Vec<_> = t
        .sockets
        .iter()
        .filter(|s| s.role == Role::ConnectedOutbound)
        .collect();
    assert!(
        !established.is_empty(),
        "the capture should contain the live SSH session it was taken over"
    );
    for s in established {
        assert!(
            !s.is_network_reachable_inbound(),
            "an established conversation on {}:{} was counted as a listening surface",
            s.local_addr, s.local_port
        );
    }
    // And exactly one TCP listener, not one per connection.
    let listeners = t.sockets.iter().filter(|s| s.role == Role::Inbound).count();
    assert_eq!(listeners, 1, "sshd is one surface however many sessions are open");
}

//! The emitter and the posture checker have to agree about the emitter.
//!
//! These are the two halves of the sensor, written separately, and the place
//! they could silently disagree is exactly here: the checker reads
//! `/proc/net/udp` and calls a UDP socket with no peer an inbound surface, so
//! an emitter that used `send_to` on an unconnected socket would make the
//! sensor attest itself `Exposed` **for the act of transmitting**. Nothing in
//! either crate's own tests could catch that, because each is individually
//! correct.
//!
//! So this test opens a real socket the way the sensor will, then reads the
//! real `/proc/net/udp` and asks the real checker what it thinks of it.

use bsc_lan_sense::procnet::{parse_table, Protocol, Role};
use bsc_lan_sense::transport::UdpMulticast;
use std::net::{Ipv4Addr, SocketAddrV4};

#[test]
fn the_sensors_own_emitter_socket_is_classified_outbound_not_a_listener() {
    let group = SocketAddrV4::new(Ipv4Addr::new(239, 10, 20, 30), 5140);
    let emitter = UdpMulticast::bind(Ipv4Addr::LOCALHOST, group)
        .expect("binding a multicast emitter on loopback must work; if this fails the sensor cannot emit at all");

    let local = emitter.local_addr().expect("a bound socket has a local address");
    let port = match local {
        std::net::SocketAddr::V4(v4) => v4.port(),
        std::net::SocketAddr::V6(v6) => panic!("expected an IPv4 socket, got {v6}"),
    };

    let text = std::fs::read_to_string("/proc/net/udp").expect("/proc/net/udp is readable");
    let table = parse_table(&text, Protocol::Udp).expect("the live udp table parses");

    // Population check first: if the parser found nothing, the assertion below
    // would pass vacuously and prove nothing at all.
    assert!(
        table.rows_parsed > 0,
        "parsed no rows from the live /proc/net/udp, so this test would pass without checking anything"
    );

    let ours: Vec<_> = table.sockets.iter().filter(|s| s.local_port == port).collect();
    assert!(
        !ours.is_empty(),
        "could not find the emitter's own socket (port {port}) among {} parsed rows -- \
         the test cannot conclude anything about a socket it did not find",
        table.rows_parsed
    );

    for s in ours {
        assert_eq!(
            s.role,
            Role::ConnectedOutbound,
            "the sensor's own emitter socket on port {port} reads as {:?}. If it is Inbound, \
             the sensor will attest itself Exposed for transmitting, and whoever watches the \
             posture will be trained to ignore a real alert. The fix is `connect()` rather \
             than `send_to` in UdpMulticast::bind.",
            s.role
        );
        assert!(!s.is_network_reachable_inbound());
    }
}

/// TTL 1 is what physically confines the telemetry to the local segment, so
/// it is asserted rather than trusted to a default.
#[test]
fn the_stream_cannot_be_routed_off_the_local_segment() {
    let group = SocketAddrV4::new(Ipv4Addr::new(239, 10, 20, 31), 5141);
    let emitter = UdpMulticast::bind(Ipv4Addr::LOCALHOST, group).expect("bind");
    assert_eq!(
        emitter.multicast_ttl().expect("ttl readable"),
        1,
        "a TTL above 1 lets a router carry the sensor's telemetry off the segment"
    );
}

/// A datagram that is too large must be refused by the wire contract before it
/// ever reaches the socket, since a fragmented multicast datagram loses the
/// whole payload if any fragment drops and there is no retransmission.
#[test]
fn the_emitter_refuses_an_oversized_payload_rather_than_letting_the_kernel_fragment_it() {
    use bsc_lan_sense::emit::{Emitter, SnapshotPolicy};
    use bsc_lan_stream::crypto::{GroupKey, Sensor};
    use bsc_lan_stream::frame::{Event, SensorState};
    use ed25519_dalek::SigningKey;

    struct Null;
    impl bsc_lan_sense::transport::Transport for Null {
        fn send(&self, _: &[u8]) -> std::io::Result<()> {
            Ok(())
        }
    }

    let sensor = Sensor::new(
        SigningKey::from_bytes(&[3u8; 32]),
        GroupKey::from_bytes([7u8; 32]),
        [1u8; 16],
    );
    let mut e = Emitter::new(sensor, Null, SnapshotPolicy { interval_ms: 10_000 });

    // A snapshot fat enough to exceed one datagram.
    let mut state = SensorState::default();
    for i in 0..500u64 {
        state.counters.insert(format!("counter.number.{i}"), i);
        state.active_alerts.push(Event::Health {
            uptime_s: i,
            soc_temp_c: 90.0,
            capture_drops: i,
        });
    }
    let posture = bsc_lan_sense::posture::Posture::Sealed {
        loopback_listeners: vec![],
        rows_examined: 10,
    };

    let err = e
        .emit_snapshot(state, &posture, 0)
        .expect_err("an oversized snapshot must be refused, not fragmented");
    assert!(
        err.to_string().contains("budget") || err.to_string().contains("over the"),
        "expected a size refusal, got: {err}"
    );
    assert_eq!(e.next_seq(), 0, "a refused datagram must not burn a sequence number");
}

//! The sensor's self-attestation, driven from verbatim `/proc/net` fixtures.
//!
//! Every fixture below is copied from a real Linux host rather than invented,
//! because the parser's whole value is that it matches what the kernel
//! actually writes -- and the box it will run on is one nobody can log into to
//! check.

use bsc_lan_sense::error::ProcNetError;
use bsc_lan_sense::posture::{assess, Posture};
use bsc_lan_sense::procnet::{parse_table, Protocol, Reach, Role};

const TCP_HEADER: &str = "  sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode";
const UDP_HEADER: &str = "   sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode ref pointer drops";
const TCP6_HEADER: &str = "  sl  local_address                         remote_address                        st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode";

/// A loopback TCP listener: 127.0.0.1:2999, state 0A.
const TCP_LOOPBACK_LISTENER: &str = "   0: 0100007F:0BB7 00000000:0000 0A 00000000:00000000 00:00000000 00000000  1000        0 3553638 1 00000000f39ad427 100 0 0 10 0";
/// A WILDCARD TCP listener: 0.0.0.0:8080 -- a genuine way in.
const TCP_WILDCARD_LISTENER: &str = "   1: 00000000:1F90 00000000:0000 0A 00000000:00000000 00:00000000 00000000  1000        0 3553639 1 00000000f39ad428 100 0 0 10 0";
/// A DHCP client: 10.99.2.118:68 connected to 10.99.2.1:67.
const UDP_CONNECTED: &str = " 9995: 7602A8C0:0044 0102A8C0:0043 01 00000000:00000000 00:00000000 00000000     0        0 2596425 2 000000002829356d 0";
/// A UDP socket bound to every interface with no peer -- inbound capability.
const UDP_WILDCARD_BOUND: &str = "12738: 00000000:CAFB 00000000:0000 07 00000000:00000000 00:00000000 00000000   103        0 13814 2 00000000b148a66b 0";
/// `::1` in the four-little-endian-word form the kernel uses.
const TCP6_LOOPBACK_LISTENER: &str = "   0: 00000000000000000000000001000000:0277 00000000000000000000000000000000:0000 0A 00000000:00000000 00:00000000 00000000     0        0 1926579 1 000000002f8e37da 100 0 0 10 0";

fn table(header: &str, rows: &[&str]) -> String {
    let mut s = String::from(header);
    for r in rows {
        s.push('\n');
        s.push_str(r);
    }
    s
}

#[test]
fn a_loopback_tcp_listener_is_decoded_with_its_real_address() {
    let t = parse_table(&table(TCP_HEADER, &[TCP_LOOPBACK_LISTENER]), Protocol::Tcp).unwrap();
    assert_eq!(t.rows_seen, 1);
    assert_eq!(t.rows_parsed, 1);
    let s = &t.sockets[0];
    // Little-endian per word: 0100007F really is 127.0.0.1, not 1.0.0.127.
    assert_eq!(s.local_addr, "127.0.0.1");
    assert_eq!(s.local_port, 0x0BB7);
    assert_eq!(s.role, Role::Inbound);
    assert_eq!(s.reach, Reach::Loopback);
    assert!(!s.is_network_reachable_inbound());
}

#[test]
fn a_wildcard_tcp_listener_is_a_way_in() {
    let t = parse_table(&table(TCP_HEADER, &[TCP_WILDCARD_LISTENER]), Protocol::Tcp).unwrap();
    let s = &t.sockets[0];
    assert_eq!(s.local_addr, "0.0.0.0");
    assert_eq!(s.local_port, 8080);
    assert_eq!(s.reach, Reach::Wildcard);
    assert!(s.is_network_reachable_inbound());
}

/// The distinction that stops the sensor reporting itself exposed for doing
/// its job: the outbound multicast emitter is a CONNECTED udp socket.
#[test]
fn a_connected_udp_socket_is_outbound_and_never_an_inbound_surface() {
    let t = parse_table(&table(UDP_HEADER, &[UDP_CONNECTED]), Protocol::Udp).unwrap();
    let s = &t.sockets[0];
    assert_eq!(s.local_addr, "10.99.2.118");
    assert_eq!(s.role, Role::ConnectedOutbound);
    assert!(
        !s.is_network_reachable_inbound(),
        "a socket with a peer is the sensor transmitting, not a way in"
    );
}

#[test]
fn a_bound_udp_socket_with_no_peer_is_inbound_capability() {
    let t = parse_table(&table(UDP_HEADER, &[UDP_WILDCARD_BOUND]), Protocol::Udp).unwrap();
    let s = &t.sockets[0];
    assert_eq!(s.role, Role::Inbound);
    assert_eq!(s.reach, Reach::Wildcard);
    assert!(s.is_network_reachable_inbound());
}

#[test]
fn the_ipv6_loopback_word_order_is_decoded_correctly() {
    let t = parse_table(&table(TCP6_HEADER, &[TCP6_LOOPBACK_LISTENER]), Protocol::Tcp).unwrap();
    let s = &t.sockets[0];
    assert_eq!(s.reach, Reach::Loopback, "::1 must not read as routable");
    assert!(!s.is_network_reachable_inbound());
}

#[test]
fn a_sealed_verdict_records_how_many_rows_justified_it() {
    let tcp = parse_table(&table(TCP_HEADER, &[TCP_LOOPBACK_LISTENER]), Protocol::Tcp);
    let udp = parse_table(&table(UDP_HEADER, &[UDP_CONNECTED]), Protocol::Udp);
    match assess(&[tcp, udp]) {
        Posture::Sealed { loopback_listeners, rows_examined } => {
            assert_eq!(rows_examined, 2);
            assert_eq!(loopback_listeners.len(), 1);
        }
        Posture::Exposed { reachable, .. } => panic!("expected Sealed, exposed by {reachable:?}"),
        Posture::Unknown { reason } => panic!("expected Sealed, could not assess: {reason}"),
    }
}

#[test]
fn one_reachable_listener_anywhere_makes_the_whole_box_exposed() {
    let tcp = parse_table(
        &table(TCP_HEADER, &[TCP_LOOPBACK_LISTENER, TCP_WILDCARD_LISTENER]),
        Protocol::Tcp,
    );
    let p = assess(&[tcp]);
    match &p {
        Posture::Exposed { reachable, .. } => {
            assert_eq!(reachable.len(), 1);
            assert_eq!(reachable[0].local_port, 8080);
        }
        Posture::Sealed { .. } => panic!("expected Exposed, got Sealed"),
        Posture::Unknown { reason } => panic!("expected Exposed, could not assess: {reason}"),
    }
    assert!(!p.is_sealed());
    assert!(p.needs_attention());
}

// ---------------------------------------------------------------------------
// The rule that matters most: a check that cannot read reports Unknown.
// Each way of failing gets its own test, because each one has to be handled
// separately in code and a shared test would hide a missing branch.
// ---------------------------------------------------------------------------

#[test]
fn an_empty_table_is_unknown_not_sealed() {
    let r = parse_table("", Protocol::Tcp);
    assert_eq!(r, Err(ProcNetError::Empty));
    assert!(!assess(&[r]).is_sealed());
}

#[test]
fn an_unrecognised_header_is_unknown_not_sealed() {
    let r = parse_table("total garbage that is not a proc table\n1 2 3", Protocol::Tcp);
    assert!(matches!(r, Err(ProcNetError::UnrecognisedHeader(_))));
    let p = assess(&[r]);
    assert!(!p.is_sealed(), "a kernel format change must never read as a hardened box");
    assert!(p.needs_attention());
}

#[test]
fn a_header_only_table_with_no_rows_does_not_by_itself_prove_anything() {
    // A real possibility: the file exists and parses, but every row vanished.
    // That IS legitimately zero sockets, so it is Sealed -- but the row count
    // is what lets a reader tell it from a rich, healthy table.
    let p = assess(&[parse_table(TCP_HEADER, Protocol::Tcp)]);
    match p {
        Posture::Sealed { rows_examined, .. } => assert_eq!(
            rows_examined, 0,
            "a Sealed verdict must carry the evidence count so zero is visible"
        ),
        Posture::Exposed { reachable, .. } => panic!("expected Sealed, exposed by {reachable:?}"),
        Posture::Unknown { reason } => panic!("expected Sealed, could not assess: {reason}"),
    }
}

#[test]
fn rows_the_parser_could_not_understand_make_the_verdict_unknown() {
    // Header is fine, so the file IS a proc table -- but the rows are not
    // shaped as this parser expects. Assessing only the subset that parsed
    // would be a conclusion about the wrong population.
    let text = format!("{TCP_HEADER}\n   0: NOTHEX:ZZZZ 00000000:0000 0A rest\n   1: ALSOBAD 00000000:0000 0A rest");
    let t = parse_table(&text, Protocol::Tcp).unwrap();
    assert_eq!(t.rows_seen, 2);
    assert_eq!(t.rows_parsed, 0);

    let p = assess(&[Ok(t)]);
    assert!(
        matches!(p, Posture::Unknown { reason: ProcNetError::PartiallyUnderstood { rows_seen: 2, rows_parsed: 0 } }),
        "got {p:?}"
    );
    assert!(!p.is_sealed());
}

#[test]
fn an_unreadable_file_is_unknown_not_sealed() {
    let p = assess(&[Err(ProcNetError::Unreadable {
        path: "/proc/net/tcp".into(),
        reason: "Permission denied".into(),
    })]);
    assert!(!p.is_sealed());
    assert!(p.needs_attention());
}

#[test]
fn one_failed_table_poisons_the_whole_verdict() {
    // Three clean tables and one failure must NOT average out to a pass: the
    // unread table is exactly where a listener would be hiding.
    let ok1 = parse_table(&table(TCP_HEADER, &[TCP_LOOPBACK_LISTENER]), Protocol::Tcp);
    let ok2 = parse_table(&table(UDP_HEADER, &[UDP_CONNECTED]), Protocol::Udp);
    let ok3 = parse_table(&table(TCP6_HEADER, &[TCP6_LOOPBACK_LISTENER]), Protocol::Tcp);
    let bad = Err(ProcNetError::Unreadable { path: "/proc/net/udp6".into(), reason: "ENOENT".into() });

    assert!(
        !assess(&[ok1, ok2, ok3, bad]).is_sealed(),
        "a verdict drawn from three of four tables is a verdict about three of four tables"
    );
}

#[test]
fn assessing_nothing_at_all_is_unknown() {
    assert!(!assess(&[]).is_sealed());
}

#[test]
fn unknown_is_alertable_because_not_knowing_is_the_alertable_condition() {
    let p = Posture::Unknown { reason: ProcNetError::Empty };
    assert!(p.needs_attention(), "on a box nobody can inspect, 'I cannot tell' must wake someone");
}

/// Sanity against the live host: the verdict must be well-formed and justified
/// whatever this particular machine happens to be running. Deliberately does
/// NOT assert Sealed -- a dev box has listeners, and a test that demanded
/// otherwise would be asserting something about the machine, not the code.
#[test]
fn the_live_host_yields_a_justified_verdict() {
    match bsc_lan_sense::assess_host() {
        Posture::Sealed { rows_examined, .. } | Posture::Exposed { rows_examined, .. } => {
            assert!(rows_examined > 0, "a verdict on a live host from zero rows is a broken parser");
        }
        Posture::Unknown { reason } => panic!("could not assess this host: {reason}"),
    }
}

//! The two key documents have to describe ONE working stream, and nothing
//! about reading them separately can prove that.
//!
//! Each document parses on its own merits: sixty-four hex characters, a valid
//! address, a mode nobody else can read. All of that passes when an operator
//! pastes the group key from one keygen and the sensor's public key from
//! another, or transposes the signing key and the public half between the two
//! files. What they get is a sensor that transmits happily and a subscriber
//! that hears nothing — reported, correctly and unhelpfully, as `NEVER HEARD`,
//! the same line a dead switch produces.
//!
//! So this test carries a sealed datagram from the sensor document's keys to
//! the subscriber document's keys and asserts it arrives, and then asserts
//! that the near-miss — a subscriber holding the wrong public half — is
//! REJECTED rather than quietly accepted.

use bsc_lan_sense::config::{parse_sensor, parse_subscriber, refuse_if_readable_by_others};
use bsc_lan_stream::crypto::{GroupKey, Sensor, Subscriber};
use bsc_lan_stream::envelope::Kind;
use ed25519_dalek::{SigningKey, VerifyingKey};

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

/// The pair an operator is meant to produce: one signing key, its own public
/// half, and one group key shared by both documents.
fn documents(signing: &SigningKey, public: &VerifyingKey, group: [u8; 32]) -> (String, String) {
    let sensor = format!(
        r#"{{"destination":"239.10.20.30:5140","sensorKey":"{}","groupKey":"{}"}}"#,
        hex(&signing.to_bytes()),
        hex(&group)
    );
    let subscriber = format!(
        r#"{{"group":"239.10.20.30:5140","sensors":[{{"name":"monitor-pi","publicKey":"{}"}}],"groupKey":"{}"}}"#,
        hex(&public.to_bytes()),
        hex(&group)
    );
    (sensor, subscriber)
}

#[test]
fn a_matched_pair_of_documents_carries_a_real_datagram() {
    let signing = SigningKey::from_bytes(&[7u8; 32]);
    let public = signing.verifying_key();
    let (sensor_doc, subscriber_doc) = documents(&signing, &public, [9u8; 32]);

    let sen = parse_sensor(&sensor_doc).expect("the sensor document parses");
    let sub = parse_subscriber(&subscriber_doc).expect("the subscriber document parses");

    // Built the way the CLI and the app build them: from the config's bytes,
    // never from the values this test happens to hold.
    let sensor = Sensor::new(
        SigningKey::from_bytes(&sen.sensor_key_bytes().unwrap()),
        GroupKey::from_bytes(sen.group_key_bytes().unwrap()),
        [1u8; 16],
    );
    let subscriber = Subscriber::new(
        VerifyingKey::from_bytes(&sub.roster().unwrap()[0].1).expect("a valid public key"),
        GroupKey::from_bytes(sub.group_key_bytes().unwrap()),
    );

    let plain = b"a spectrum record".to_vec();
    let datagram = sensor.seal(Kind::Delta, 0, [3u8; 12], &plain).expect("seals");
    let (env, got) = subscriber.open(&datagram).expect("the pair must describe ONE stream");
    assert_eq!(got, plain, "the payload did not survive the round trip");
    assert_eq!(env.seq, 0);
}

#[test]
fn a_subscriber_holding_the_wrong_public_half_is_refused_not_ignored() {
    // The transposition an operator actually makes: two keygens, and the
    // public key pasted from the wrong one. Both documents are individually
    // valid; only carrying a datagram between them can tell.
    let signing = SigningKey::from_bytes(&[7u8; 32]);
    let other = SigningKey::from_bytes(&[8u8; 32]).verifying_key();
    let (sensor_doc, subscriber_doc) = documents(&signing, &other, [9u8; 32]);

    let sen = parse_sensor(&sensor_doc).expect("parses");
    let sub = parse_subscriber(&subscriber_doc).expect("parses — which is the whole problem");

    let sensor = Sensor::new(
        SigningKey::from_bytes(&sen.sensor_key_bytes().unwrap()),
        GroupKey::from_bytes(sen.group_key_bytes().unwrap()),
        [1u8; 16],
    );
    let subscriber = Subscriber::new(
        VerifyingKey::from_bytes(&sub.roster().unwrap()[0].1).unwrap(),
        GroupKey::from_bytes(sub.group_key_bytes().unwrap()),
    );

    let datagram = sensor.seal(Kind::Delta, 0, [3u8; 12], b"x").expect("seals");
    assert!(
        subscriber.open(&datagram).is_err(),
        "a mismatched public key accepted the stream — the signature would then prove nothing"
    );
}

#[test]
fn a_mismatched_group_key_is_refused_too() {
    // The other half of the same mistake, and it fails at a different layer:
    // the signature verifies, and the decryption does not.
    let signing = SigningKey::from_bytes(&[7u8; 32]);
    let public = signing.verifying_key();
    let (sensor_doc, _) = documents(&signing, &public, [9u8; 32]);
    let (_, subscriber_doc) = documents(&signing, &public, [10u8; 32]);

    let sen = parse_sensor(&sensor_doc).unwrap();
    let sub = parse_subscriber(&subscriber_doc).unwrap();
    let sensor = Sensor::new(
        SigningKey::from_bytes(&sen.sensor_key_bytes().unwrap()),
        GroupKey::from_bytes(sen.group_key_bytes().unwrap()),
        [1u8; 16],
    );
    let subscriber = Subscriber::new(
        VerifyingKey::from_bytes(&sub.roster().unwrap()[0].1).unwrap(),
        GroupKey::from_bytes(sub.group_key_bytes().unwrap()),
    );
    let datagram = sensor.seal(Kind::Delta, 0, [3u8; 12], b"x").unwrap();
    assert!(subscriber.open(&datagram).is_err(), "a mismatched group key decrypted the stream");
}

#[cfg(unix)]
#[test]
fn the_documents_are_read_from_real_files_with_a_real_mode() {
    // The parse tests work on strings. This one puts both documents on a disk,
    // because the mode check is the guard that only exists against a file and
    // the loaders are the only path production takes.
    use std::os::unix::fs::PermissionsExt;
    let signing = SigningKey::from_bytes(&[7u8; 32]);
    let public = signing.verifying_key();
    let (sensor_doc, subscriber_doc) = documents(&signing, &public, [9u8; 32]);

    let dir = std::env::temp_dir().join(format!("bsc-lan-pair-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let sp = dir.join("sensor.json");
    let up = dir.join("subscriber.json");
    std::fs::write(&sp, &sensor_doc).unwrap();
    std::fs::write(&up, &subscriber_doc).unwrap();
    std::fs::set_permissions(&sp, std::fs::Permissions::from_mode(0o600)).unwrap();
    std::fs::set_permissions(&up, std::fs::Permissions::from_mode(0o600)).unwrap();

    refuse_if_readable_by_others(&sp).expect("mode 600 is acceptable");
    refuse_if_readable_by_others(&up).expect("mode 600 is acceptable");
    let sen = parse_sensor(&std::fs::read_to_string(&sp).unwrap()).unwrap();
    let sub = parse_subscriber(&std::fs::read_to_string(&up).unwrap()).unwrap();
    assert_eq!(sen.group_key_bytes().unwrap(), sub.group_key_bytes().unwrap());

    // And one of them made world-readable is refused, from the same disk.
    std::fs::set_permissions(&up, std::fs::Permissions::from_mode(0o644)).unwrap();
    let e = refuse_if_readable_by_others(&up).unwrap_err();
    assert!(e.contains("0644"), "the refusal hides the mode: {e}");

    std::fs::remove_dir_all(&dir).ok();
}

//! End-to-end properties of the sensor stream, exercised over real datagrams.
//!
//! Every test here builds a genuine sealed datagram and opens it the way a
//! subscriber would. Keys are fixed rather than random so a failure is
//! reproducible from the test name alone.

use bsc_lan_stream::crypto::{GroupKey, Sensor, Subscriber};
use bsc_lan_stream::envelope::{Kind, MAX_PLAINTEXT_BYTES};
use bsc_lan_stream::frame::{Event, Frame, SensorState};
use bsc_lan_stream::sequence::{Completeness, Reception, Tracker};
use bsc_lan_stream::WireError;
use ed25519_dalek::SigningKey;

const GROUP: [u8; 32] = [7u8; 32];
const BOOT: [u8; 16] = [42u8; 16];

fn sensor_key() -> SigningKey {
    SigningKey::from_bytes(&[3u8; 32])
}

/// A key an attacker might hold instead of the sensor's.
fn other_key() -> SigningKey {
    SigningKey::from_bytes(&[9u8; 32])
}

fn sensor() -> Sensor {
    Sensor::new(sensor_key(), GroupKey::from_bytes(GROUP), BOOT)
}

fn subscriber() -> Subscriber {
    Subscriber::new(sensor_key().verifying_key(), GroupKey::from_bytes(GROUP))
}

fn an_alert() -> Frame {
    Frame::Delta(Event::Alert {
        sid: 2010935,
        msg: "ET SCAN Potential SSH Scan".into(),
        src: "10.99.4.66".into(),
        dst: "10.99.2.1".into(),
        severity: 2,
    })
}

#[test]
fn a_datagram_round_trips_through_seal_and_open() {
    let frame = an_alert();
    let dg = sensor()
        .seal(Kind::Delta, 0, [1u8; 12], &frame.encode().unwrap())
        .unwrap();

    let (env, plaintext) = subscriber().open(&dg).unwrap();
    assert_eq!(env.kind, Kind::Delta);
    assert_eq!(env.seq, 0);
    assert_eq!(env.boot_id, BOOT);
    assert_eq!(Frame::decode(&plaintext).unwrap(), frame);
}

#[test]
fn every_single_byte_of_the_datagram_is_covered_by_the_signature() {
    let dg = sensor()
        .seal(Kind::Delta, 0, [1u8; 12], &an_alert().encode().unwrap())
        .unwrap();
    let sub = subscriber();

    // Not a spot check: flipping ANY byte anywhere must be refused. A partial
    // guard here would leave an editable region on the wire.
    for i in 0..dg.len() {
        let mut tampered = dg.clone();
        tampered[i] ^= 0x01;
        assert!(
            sub.open(&tampered).is_err(),
            "byte {i} of {} could be altered without detection",
            dg.len()
        );
    }
}

/// THE COMPROMISED-SUBSCRIBER PROPERTY -- the reason the group key and the
/// signing key are separate.
///
/// A subscriber necessarily holds the group key, so it can read the stream.
/// It must never be able to WRITE to it. Since the operator intends to add
/// many subscribing devices, a design where any subscriber could fabricate an
/// alert would get less trustworthy with every device added.
#[test]
fn a_subscriber_holding_the_group_key_cannot_forge_a_datagram() {
    // The attacker has the group key (it is a subscriber) and encrypts a
    // perfectly well-formed lie -- but must sign with a key it does not have.
    let attacker = Sensor::new(other_key(), GroupKey::from_bytes(GROUP), BOOT);
    let lie = Frame::Delta(Event::Alert {
        sid: 1,
        msg: "all clear".into(),
        src: "10.0.0.1".into(),
        dst: "10.0.0.2".into(),
        severity: 0,
    });

    let forged = attacker
        .seal(Kind::Delta, 99, [5u8; 12], &lie.encode().unwrap())
        .unwrap();

    assert_eq!(
        subscriber().open(&forged),
        Err(WireError::BadSignature),
        "a group-key holder forged a datagram that a subscriber accepted"
    );
}

#[test]
fn a_datagram_from_the_right_sensor_but_the_wrong_group_key_does_not_decrypt() {
    let wrong_group = Sensor::new(sensor_key(), GroupKey::from_bytes([8u8; 32]), BOOT);
    let dg = wrong_group
        .seal(Kind::Delta, 0, [1u8; 12], &an_alert().encode().unwrap())
        .unwrap();
    // The signature is genuine, so this is specifically a confidentiality
    // failure rather than an authenticity one -- the errors must not blur.
    assert_eq!(subscriber().open(&dg), Err(WireError::Undecryptable));
}

#[test]
fn a_payload_over_the_budget_is_refused_at_build_time_rather_than_fragmented() {
    let too_big = vec![b'x'; MAX_PLAINTEXT_BYTES + 1];
    assert!(matches!(
        sensor().seal(Kind::Delta, 0, [1u8; 12], &too_big),
        Err(WireError::PayloadTooLarge { .. })
    ));

    // And the largest permitted payload really does fit the wire budget.
    let at_limit = vec![b'x'; MAX_PLAINTEXT_BYTES];
    let dg = sensor().seal(Kind::Delta, 0, [1u8; 12], &at_limit).unwrap();
    assert!(dg.len() <= bsc_lan_stream::MAX_DATAGRAM_BYTES);
    assert_eq!(subscriber().open(&dg).unwrap().1, at_limit);
}

#[test]
fn garbage_on_the_multicast_group_is_rejected_by_shape_before_any_crypto() {
    let sub = subscriber();
    assert_eq!(sub.open(&[]), Err(WireError::Truncated { got: 0, need: 122 }));
    assert!(matches!(sub.open(&[0u8; 200]), Err(WireError::BadMagic)));
    assert!(matches!(
        sub.open(&vec![0u8; bsc_lan_stream::MAX_DATAGRAM_BYTES + 1]),
        Err(WireError::TooLarge { .. })
    ));
}

/// The recovery story, driven end to end: a subscriber misses live traffic,
/// notices exactly what it missed, and is made whole by a snapshot alone --
/// having asked the sensor for nothing, because it cannot.
#[test]
fn a_subscriber_that_missed_deltas_recovers_from_the_next_snapshot() {
    let sensor = sensor();
    let sub = subscriber();
    let mut tracker = Tracker::new();

    let emit = |kind: Kind, seq: u64, frame: &Frame| {
        sensor.seal(kind, seq, [seq as u8; 12], &frame.encode().unwrap()).unwrap()
    };

    // seq 0: an opening snapshot. The subscriber is whole.
    let mut state = SensorState { monotonic_us: 1_000, ..Default::default() };
    state.counters.insert("alerts.total".into(), 0);
    let dg = emit(Kind::Snapshot, 0, &Frame::Snapshot(state.clone()));
    let (env, _) = sub.open(&dg).unwrap();
    assert_eq!(tracker.accept(&env).unwrap(), Reception::Started);
    assert_eq!(tracker.completeness(), Some(Completeness::Whole));

    // seq 1..=3 are emitted but LOST in flight -- never opened, never seen.

    // seq 4 arrives. The subscriber must notice precisely what it missed.
    let dg = emit(Kind::Delta, 4, &an_alert());
    let (env, _) = sub.open(&dg).unwrap();
    assert_eq!(tracker.accept(&env).unwrap(), Reception::Gap { missing: 1..=3 });
    assert_eq!(
        tracker.completeness(),
        Some(Completeness::Degraded),
        "a subscriber that lost datagrams must not believe its view is complete"
    );

    // seq 5: the periodic snapshot. No request was made and none was possible.
    state.counters.insert("alerts.total".into(), 4);
    state.monotonic_us = 6_000;
    let dg = emit(Kind::Snapshot, 5, &Frame::Snapshot(state.clone()));
    let (env, plaintext) = sub.open(&dg).unwrap();
    assert_eq!(tracker.accept(&env).unwrap(), Reception::InOrder);
    assert_eq!(
        tracker.completeness(),
        Some(Completeness::Whole),
        "the snapshot is the entire recovery mechanism on a one-way stream"
    );

    // And the recovered state is the sensor's real state, not a patched-up
    // guess assembled from the deltas that did survive.
    match Frame::decode(&plaintext).unwrap() {
        Frame::Snapshot(recovered) => assert_eq!(recovered, state),
        Frame::Delta(d) => panic!("expected a snapshot, got {d:?}"),
    }
}

#[test]
fn a_sensor_reboot_is_visible_to_subscribers_as_a_restart() {
    let sub_key = sensor_key();
    let first = Sensor::new(sub_key.clone(), GroupKey::from_bytes(GROUP), [1u8; 16]);
    let after_reboot = Sensor::new(sub_key, GroupKey::from_bytes(GROUP), [2u8; 16]);
    let sub = subscriber();
    let mut tracker = Tracker::new();

    let dg = first.seal(Kind::Snapshot, 7, [1u8; 12], &an_alert().encode().unwrap()).unwrap();
    let (env, _) = sub.open(&dg).unwrap();
    tracker.accept(&env).unwrap();

    // Sequence restarts at 0 -- which without the boot id would read as a
    // replay and be silently discarded, hiding the reboot entirely.
    let dg = after_reboot.seal(Kind::Delta, 0, [2u8; 12], &an_alert().encode().unwrap()).unwrap();
    let (env, _) = sub.open(&dg).unwrap();
    assert_eq!(
        tracker.accept(&env).unwrap(),
        Reception::SensorRestarted { previous_boot: [1u8; 16], previous_last_seq: 7 }
    );
}

//! The publish path must ADOPT an existing same-title board rather than mint a second one.
//!
//! This is the CALL-SITE test for `the-publish-path-adopts-an-existing-board`. The decision itself is
//! unit-tested in `board_choice`; what these assert is that `ensure_project_board` actually consults it
//! — a decision nobody calls is the shape this epic keeps finding.
//!
//! They are about WHICH CALLS HAPPEN, not about GitHub: the fake records every query and answers from a
//! script, so "no board was created" is observable rather than inferred.

use bsc_publish::{ensure_project_board, GhApi, Report};
use std::cell::RefCell;
use std::collections::HashMap;

/// Records every call; answers the owner query from a script and fails nothing else.
struct FakeGh {
    calls: RefCell<Vec<String>>,
    owner: serde_json::Value,
}

impl FakeGh {
    fn with_boards(boards: serde_json::Value) -> Self {
        FakeGh {
            calls: RefCell::new(Vec::new()),
            owner: serde_json::json!({ "repositoryOwner": { "id": "O_1", "projectsV2": { "nodes": boards } } }),
        }
    }
    fn created_count(&self) -> usize {
        self.calls.borrow().iter().filter(|c| c.contains("createProjectV2")).count()
    }
    fn owner_queries(&self) -> usize {
        self.calls.borrow().iter().filter(|c| c.contains("repositoryOwner")).count()
    }
}

impl GhApi for FakeGh {
    fn gql(&self, query: &str, _v: serde_json::Value) -> Result<serde_json::Value, String> {
        self.calls.borrow_mut().push(query.to_string());
        if query.contains("repositoryOwner") {
            // THE FAKE HONOURS THE QUERY. GitHub returns only the fields asked for, so a query that
            // does not select `projectsV2` gets an owner WITHOUT boards — and adoption becomes
            // impossible, which is exactly the pre-fix behaviour.
            //
            // Measured: without this, reverting the query to `repositoryOwner(login){ id }` did not
            // fail a single test, because the fake handed over the boards regardless. A fake that
            // answers more generously than the real API tests the mechanism and not the fix.
            if !query.contains("projectsV2") {
                let mut bare = self.owner.clone();
                if let Some(o) = bare.get_mut("repositoryOwner").and_then(|o| o.as_object_mut()) {
                    o.remove("projectsV2");
                }
                return Ok(bare);
            }
            return Ok(self.owner.clone());
        }
        if query.contains("createProjectV2") {
            return Ok(serde_json::json!({ "createProjectV2": { "projectV2": { "id": "P_NEW", "number": 99, "url": "u" } } }));
        }
        Ok(serde_json::json!({}))
    }
    fn rest(&self, _path: &str) -> Result<serde_json::Value, String> {
        Ok(serde_json::json!([]))
    }
    fn post(&self, _path: &str, _b: &serde_json::Value) -> Result<serde_json::Value, String> {
        Ok(serde_json::json!({}))
    }
}

fn board(id: &str, number: i64, title: &str) -> serde_json::Value {
    serde_json::json!({ "id": id, "number": number, "url": format!("https://x/{id}"), "title": title })
}

fn run(api: &FakeGh, existing: Option<&str>, title: &str) -> (Option<String>, Report) {
    let mut report = Report::default();
    let repos = vec!["acme/web".to_string()];
    let id = ensure_project_board(api, existing, &repos, "acme", title, &HashMap::new(), &mut report);
    (id, report)
}

/// THE REGRESSION THIS CLOSES. Before the flip this issued `createProjectV2` and returned a NEW id,
/// duplicating a board the app-side publish would have adopted.
#[test]
fn a_same_title_board_is_adopted_and_nothing_is_created() {
    let api = FakeGh::with_boards(serde_json::json!([board("P_OLD", 7, "Studio Code")]));
    let (id, _) = run(&api, None, "Studio Code");
    assert_eq!(id.as_deref(), Some("P_OLD"), "the existing board is adopted");
    assert_eq!(api.created_count(), 0, "NO board may be created when one already carries the title");
}

/// The shared matcher's rules reach the call site, not just its unit test.
#[test]
fn adoption_is_case_insensitive_and_ignores_surrounding_whitespace() {
    let api = FakeGh::with_boards(serde_json::json!([board("P_OLD", 7, "  studio CODE  ")]));
    let (id, _) = run(&api, None, "Studio Code");
    assert_eq!(id.as_deref(), Some("P_OLD"));
    assert_eq!(api.created_count(), 0);
}

/// …and when nothing matches, it still creates. The fix must not have turned publish into a no-op.
#[test]
fn a_board_is_still_created_when_no_title_matches() {
    let api = FakeGh::with_boards(serde_json::json!([board("P_OTHER", 3, "Something Else")]));
    let (id, _) = run(&api, None, "Studio Code");
    assert_eq!(id.as_deref(), Some("P_NEW"));
    assert_eq!(api.created_count(), 1);
}

/// An owner with no boards at all is the ordinary first publish.
#[test]
fn an_owner_with_no_boards_creates_one() {
    let api = FakeGh::with_boards(serde_json::json!([]));
    let (id, _) = run(&api, None, "Studio Code");
    assert_eq!(id.as_deref(), Some("P_NEW"));
    assert_eq!(api.created_count(), 1);
}

/// THE OPTIMISATION THAT MUST SURVIVE. An already-linked board costs no round trip at all — the
/// `existing` short-circuit stays outside the query, so adding adoption did not make every publish
/// pay for the owner's boards.
#[test]
fn an_already_linked_board_queries_nothing() {
    let api = FakeGh::with_boards(serde_json::json!([board("P_OLD", 7, "Studio Code")]));
    let (id, _) = run(&api, Some("P_LINKED"), "Studio Code");
    assert_eq!(id.as_deref(), Some("P_LINKED"));
    assert_eq!(api.owner_queries(), 0, "a linked board must not fetch the owner's boards");
    assert_eq!(api.created_count(), 0);
}

/// A board node missing optional fields is still a board. Dropping it would resurrect the duplicate,
/// which is the failure mode a stricter parse would quietly reintroduce.
#[test]
fn a_board_missing_url_or_number_is_still_adopted() {
    let api = FakeGh::with_boards(serde_json::json!([{ "id": "P_OLD", "title": "Studio Code" }]));
    let (id, _) = run(&api, None, "Studio Code");
    assert_eq!(id.as_deref(), Some("P_OLD"));
    assert_eq!(api.created_count(), 0);
}

//! The publish rules that protect against DUPLICATE GITHUB ISSUES.
//!
//! These are the reason publish is delicate, and none is visible to a test that talks to the real
//! API: they are all about which calls happen, in which order, given what the repo already holds. A
//! fake transport makes them assertable. Each case corresponds to a comment in `publishSteps.ts`
//! recording a bug already paid for once.

use bsc_publish::{
    create_issues_for_repo, decide, labels_for, repo_for, ExistingIssues, GhApi, IssueAction, Report,
    Status,
};
use plandb::PlanIssue;
use std::cell::RefCell;
use std::collections::{HashMap, HashSet};

/// Records every call and answers from a script. `rest_fails` simulates the existing-issue scan
/// failing, which is the fail-closed trigger.
struct FakeGh {
    calls: RefCell<Vec<String>>,
    existing: serde_json::Value,
    rest_fails: bool,
    next_number: RefCell<i64>,
}

impl FakeGh {
    fn new(existing: serde_json::Value) -> Self {
        FakeGh {
            calls: RefCell::new(Vec::new()),
            existing,
            rest_fails: false,
            next_number: RefCell::new(100),
        }
    }
    fn failing() -> Self {
        FakeGh { rest_fails: true, ..FakeGh::new(serde_json::json!([])) }
    }
    fn calls(&self) -> Vec<String> {
        self.calls.borrow().clone()
    }
    fn posts_to(&self, needle: &str) -> usize {
        self.calls().iter().filter(|c| c.starts_with("POST ") && c.contains(needle)).count()
    }
}

impl GhApi for FakeGh {
    fn gql(&self, query: &str, _v: serde_json::Value) -> Result<serde_json::Value, String> {
        let tag = query.split_whitespace().find(|w| w.len() > 3).unwrap_or("gql");
        self.calls.borrow_mut().push(format!("GQL {tag}"));
        Ok(serde_json::json!({}))
    }
    fn rest(&self, path: &str) -> Result<serde_json::Value, String> {
        self.calls.borrow_mut().push(format!("GET {path}"));
        if self.rest_fails {
            return Err("500 boom".to_string());
        }
        Ok(self.existing.clone())
    }
    fn post(&self, path: &str, _body: &serde_json::Value) -> Result<serde_json::Value, String> {
        self.calls.borrow_mut().push(format!("POST {path}"));
        let mut n = self.next_number.borrow_mut();
        *n += 1;
        Ok(serde_json::json!({ "number": *n, "node_id": format!("I_{}", *n) }))
    }
}

fn issue(json: serde_json::Value) -> PlanIssue {
    serde_json::from_value(json).unwrap()
}

fn existing_from(pairs: &[(i64, &str)]) -> ExistingIssues {
    let mut numbers = HashSet::new();
    let mut by_title = HashMap::new();
    for (n, t) in pairs {
        numbers.insert(*n);
        by_title.entry(t.to_string()).or_insert((*n, Some(format!("I_{n}"))));
    }
    ExistingIssues { numbers, by_title }
}

#[test]
fn a_published_row_is_matched_by_identity_even_after_it_is_retitled() {
    // THE BUG THIS PREVENTS: matching by title meant renaming an issue on GitHub made publish
    // believe the row was new and open a duplicate. The row's title here deliberately does NOT
    // match what GitHub holds.
    let iss = issue(serde_json::json!({ "ref": "r1", "title": "A brand new title", "ghNumber": 42 }));
    let existing = existing_from(&[(42, "The original title")]);
    assert_eq!(decide(&iss, &existing), IssueAction::AlreadyPublished(42));
}

#[test]
fn a_legacy_row_is_matched_by_title_once_and_then_carries_its_number() {
    // Rows published before the identity column have no ghNumber. The title match backfills it —
    // matched by title exactly once, by identity forever after.
    let iss = issue(serde_json::json!({ "ref": "r1", "title": "Add login" }));
    let existing = existing_from(&[(7, "Add login")]);
    assert_eq!(decide(&iss, &existing), IssueAction::LinkExisting(7, Some("I_7".into())));

    let linked = issue(serde_json::json!({ "ref": "r1", "title": "Add login", "ghNumber": 7 }));
    assert_eq!(decide(&linked, &existing), IssueAction::AlreadyPublished(7));
}

#[test]
fn a_title_match_without_a_usable_number_records_no_identity() {
    // Writing a 0 number would FABRICATE an identity pointing at nothing — and the next publish
    // would trust it and skip the issue forever. "Exists" is still right (do not re-create it).
    let iss = issue(serde_json::json!({ "ref": "r1", "title": "Add login" }));
    let mut by_title = HashMap::new();
    by_title.insert("Add login".to_string(), (0i64, None));
    let existing = ExistingIssues { numbers: HashSet::new(), by_title };
    assert_eq!(decide(&iss, &existing), IssueAction::ExistsUnlinked);
}

#[test]
fn a_row_whose_recorded_number_is_gone_from_github_is_recreated_not_skipped() {
    // A ghNumber that no longer exists must NOT be trusted blindly — identity only settles the row
    // when GitHub still holds that number. Falls through to title, then to Create.
    let iss = issue(serde_json::json!({ "ref": "r1", "title": "Add login", "ghNumber": 999 }));
    let existing = existing_from(&[(7, "Something else")]);
    assert_eq!(decide(&iss, &existing), IssueAction::Create);
}

#[test]
fn a_failed_existing_issue_scan_skips_the_repo_instead_of_creating_into_it() {
    // FAIL CLOSED. If we cannot see what a repo holds, creating would duplicate every issue in it.
    // A transient 500 must cost a skipped repo, never a duplicated backlog.
    let api = FakeGh::failing();
    let a = issue(serde_json::json!({ "ref": "r1", "title": "One" }));
    let b = issue(serde_json::json!({ "ref": "r2", "title": "Two" }));
    let mut report = Report::default();
    let ids = create_issues_for_repo(&api, "o/r", &[&a, &b], None, "", &mut report);

    assert!(ids.is_empty(), "nothing may be linked when the scan failed");
    assert_eq!(api.posts_to("/issues"), 0, "NOT ONE issue may be created after a failed scan");
    assert_eq!(report.outcomes.len(), 2);
    assert!(report.outcomes.iter().all(|o| o.status == Status::Skipped));
}

#[test]
fn an_issues_identity_is_recorded_before_the_best_effort_calls_that_can_fail() {
    // ORDERING GUARANTEE: board-add and assignee are best-effort and can throw. If identity were
    // written after them, a failure there would leave a real GitHub issue that plan.db has no
    // record of — and the next publish would create it a second time.
    let api = FakeGh::new(serde_json::json!([]));
    let iss = issue(serde_json::json!({ "ref": "r1", "title": "One", "stream": "s1" }));
    let mut report = Report::default();
    let ids = create_issues_for_repo(&api, "o/r", &[&iss], Some("PVT_1"), "octocat", &mut report);

    assert_eq!(ids.len(), 1, "the identity is captured");
    assert_eq!(ids[0].r#ref, "r1");
    assert!(ids[0].gh_number > 0);

    let calls = api.calls();
    let create_at = calls.iter().position(|c| c == "POST repos/o/r/issues").expect("issue created");
    let assign_at = calls.iter().position(|c| c.contains("/assignees")).expect("assignee attempted");
    assert!(create_at < assign_at, "the issue is created before it is assigned: {calls:?}");
}

#[test]
fn issues_are_created_already_carrying_their_stream_and_provenance_labels() {
    // Labelling AT CREATION, where the real number is in hand — the post-hoc "label by predicted
    // number" pass 404s whenever an issue failed to post or the numbering drifted.
    let iss = issue(serde_json::json!({
        "ref": "r1", "title": "One", "stream": "api", "labels": ["ui"]
    }));
    let labels = labels_for(&iss);
    assert!(labels.contains(&"ui".to_string()), "its own labels survive");
    assert!(labels.contains(&"stream:api".to_string()), "the owning stream is tagged at creation");
    assert!(labels.contains(&"bsc-generated".to_string()), "provenance is stamped");

    let no_stream = issue(serde_json::json!({ "ref": "r2", "title": "Two" }));
    assert!(!labels_for(&no_stream).iter().any(|l| l.starts_with("stream:")));
}

#[test]
fn an_issue_routes_to_its_declared_repo_else_the_first() {
