#[test]
fn republishing_an_unchanged_plan_creates_nothing() {
    // The end-to-end idempotency property: publish twice, and the second run is all no-ops. This is
    // what makes publish safe to re-run, which a director doing it unattended depends on.
    let iss = issue(serde_json::json!({ "ref": "r1", "title": "One" }));
    let api = FakeGh::new(serde_json::json!([]));
    let mut first = Report::default();
    let ids = create_issues_for_repo(&api, "o/r", &[&iss], None, "", &mut first);
    assert_eq!(first.outcomes[0].status, Status::Created);

    let published = issue(serde_json::json!({
        "ref": "r1", "title": "One", "ghNumber": ids[0].gh_number
    }));
    let seen = serde_json::json!([{ "number": ids[0].gh_number, "title": "One", "node_id": "I_x" }]);
    let api2 = FakeGh::new(seen);
    let mut second = Report::default();
    create_issues_for_repo(&api2, "o/r", &[&published], None, "", &mut second);

    assert_eq!(second.outcomes[0].status, Status::Exists);
    assert_eq!(api2.posts_to("/issues"), 0, "a republish must create nothing");
}

// ── The GitHub decision (`discovery-decides-whether-github-is-used`) ──────────

/// The refusal is on an EXPLICIT `false` only — absent is undecided, not "no".
///
/// This is the whole non-regression story. Every project planned before the axis existed has no
/// opinion, and refusing those would break publishing for all of them. It is also why the readiness
/// line reports UNDECIDED rather than a default: a director must be able to tell "this project does
/// not use GitHub" from "nobody has been asked".
#[test]
fn the_publish_refusal_reads_only_an_explicit_false() {
    let decided = |v: serde_json::Value| -> Option<bool> {
        v.get("usesGithub").and_then(|x| x.as_bool())
    };
    // Explicit answers.
    assert_eq!(decided(serde_json::json!({ "usesGithub": false })), Some(false));
    assert_eq!(decided(serde_json::json!({ "usesGithub": true })), Some(true));
    // Undecided, in every shape it can arrive as — an empty classification, one that predates the
    // axis, and an explicit null. None of these may be read as a refusal.
    for undecided in [
        serde_json::json!({}),
        serde_json::json!({ "uiMode": "custom", "needsSource": true }),
        serde_json::json!({ "usesGithub": serde_json::Value::Null }),
    ] {
        assert_eq!(decided(undecided.clone()), None, "must be undecided: {undecided}");
    }
}

// The EMITTERS, tested through the real loader (#runtime-attests-what-actually-ran).
//
// `attest.test.ts` proves the sink coalesces and that the hash matches Rust. Neither says anything about
// whether the loader CALLS it — and an emitter that is never reached is the exact failure this feature
// exists to end: every gate green, the store empty, and "no record ever declined" indistinguishable from
// "attestation was never wired up".
//
// So these drive `loadComponentFromSource` and assert on what came out of the sink. The compile step is
// INJECTED (esbuild-wasm is browser-only), and the fixtures are hand-written CommonJS — the same shape
// esbuild emits and the same approach `componentLoader.test.ts` already takes.
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { loadComponentFromSource } from "@/shared/lib/runtime/componentLoader";
import { registerAppModule, __resetRegistry } from "@/shared/lib/runtime/moduleRegistry";
import {
  enableAttestation, __resetAttestationsForTest, __pendingAttestationsForTest, srcHash,
} from "./attest";

/** The injected compile: the fixtures are already CJS, so this is identity. What matters is that
 *  `scanRequires` runs over it exactly as it does over esbuild's real output. */
const identity = async (src: string) => src;

beforeEach(() => {
  __resetRegistry();
  __resetAttestationsForTest();
  enableAttestation();
});
afterEach(() => {
  __resetAttestationsForTest();
  __resetRegistry();
});

/** Rows for one outcome, so each case reads as the fact it asserts. */
const rows = (outcome: string) => __pendingAttestationsForTest().filter((r) => r.outcome === outcome);

const COMPONENT = 'module.exports = { default: function C() { return null; } };\n';

describe("the loader attests what it decided", () => {
  it("attests every module in the closure that SERVED, with the hash of what linked", async () => {
    const sibling = 'module.exports = { helper: function () { return 1; } };\n';
    const entry = `const sib = require("@/components/sib");\n${COMPONENT}`;
    await loadComponentFromSource(entry, (spec) => (spec === "@/components/sib" ? sibling : null), undefined, identity);

    const linked = rows("linked");
    // The sibling is an ORDINARY closure member — the same shape an algorithm implementation takes, and
    // the reason LINKAGE is the honest claim for one rather than an execution count.
    const sib = linked.find((r) => r.specifier === "@/components/sib");
    expect(sib, `expected @/components/sib among [${linked.map((r) => r.specifier).join(", ")}]`).toBeTruthy();
    // The hash is of the SOURCE THAT LINKED, so a later edit cannot inherit this evidence.
    expect(sib!.src_hash).toBe(srcHash(sibling));
  });

  it("attests a DECLINED-CLOSURE override instead of only logging it", async () => {
    // A record whose closure needs a module that is neither registered nor a record: the runtime serves
    // the platform module instead and the record is INERT. That is the case which was invisible — one
    // warn line, and a graph that looked healthy.
    const broken = 'const nope = require("@/definitely/not/registered");\nmodule.exports = { X: nope };\n';
    const entry = `const b = require("@/broken");\n${COMPONENT}`;
    registerAppModule("@/broken", { X: 1 }); // the platform module it shadows, so the page still loads
    await loadComponentFromSource(entry, (spec) => (spec === "@/broken" ? broken : null), undefined, identity);

    const d = rows("declined-closure").find((r) => r.specifier === "@/broken");
    expect(d, `expected @/broken declined, got [${rows("declined-closure").map((r) => r.specifier).join(", ")}]`).toBeTruthy();
    // The REASON names the missing module. Without it the finding says "something was wrong" and the
    // reader is back to the log dive this replaced.
    expect(d!.reason).toContain("@/definitely/not/registered");
    // A declined record has no version to claim ran.
    expect(d!.src_hash).toBe("");
  });

  it("attests a DECLINED-EVAL override — it compiled and linked, then threw at module init", async () => {
    // The commonest real cause is a build-time-only form (`import.meta.glob` survives esbuild verbatim);
    // a bare throw reaches the identical decision point.
    const exploding = 'throw new Error("module init boom");\n';
    const entry = `const b = require("@/boom");\n${COMPONENT}`;
    registerAppModule("@/boom", { ok: true });
    await loadComponentFromSource(entry, (spec) => (spec === "@/boom" ? exploding : null), undefined, identity);

    const d = rows("declined-eval").find((r) => r.specifier === "@/boom");
    expect(d, `expected @/boom declined-eval, got [${rows("declined-eval").map((r) => r.specifier).join(", ")}]`).toBeTruthy();
    expect(d!.reason).toContain("boom");
  });

  it("never attributes the ENTRY's failure to the modules it pulled in", async () => {
    // An entry that exports no component still LINKED its closure. Attesting those as failed would blame
    // every dependency for the entry's problem — and those rows are what `doctor` reads to decide whether
    // an implementation is live.
    const sibling = 'module.exports = { helper: function () { return 1; } };\n';
    const entry = 'const sib = require("@/components/sib");\nmodule.exports = { notAComponent: 1 };\n';
    await expect(
      loadComponentFromSource(entry, (spec) => (spec === "@/components/sib" ? sibling : null), undefined, identity),
    ).rejects.toThrow();
    expect(rows("linked").some((r) => r.specifier === "@/components/sib")).toBe(true);
    expect(rows("declined-compile")).toHaveLength(0);
    expect(rows("declined-closure")).toHaveLength(0);
    expect(rows("declined-eval")).toHaveLength(0);
  });

  it("emits NOTHING when the sink is off — the loader must never REQUIRE attestation", async () => {
    // Every existing loader test runs with it off, and none of them should have to learn about it.
    __resetAttestationsForTest(); // leaves it disabled
    await loadComponentFromSource(COMPONENT, () => null, undefined, identity);
    expect(__pendingAttestationsForTest()).toHaveLength(0);
  });
});

// #the-component-scan-remembers-what-it-already-built — the durable scan cache's frontend half.
//
// The property every test here defends is ASYMMETRIC, and it is the whole reason this cache is safe to
// have: it may only ever SAVE work, never withhold a scan that should run. A withheld scan leaves a stale
// badge (or none) on a component that is actually broken — strictly worse than the 111.8s of rebuilding
// this exists to remove. So every degraded input below is asserted to resolve toward SCANNING.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { loadScanCache, saveScanCache, type CachedScan } from "./componentBridge";
import { pendingScans, type ScannableComponent } from "@/features/designs/lib/componentScan";
import * as bscMod from "@/shared/lib/core/bsc";

const scannable = (id: string, sig: string): ScannableComponent =>
  ({ id, sig } as unknown as ScannableComponent);

beforeEach(() => { vi.restoreAllMocks(); });

describe("loadScanCache", () => {
  const withStdout = (out: string) => vi.spyOn(bscMod, "bsc").mockResolvedValue(out);

  it("parses the stored map into entries the sweep can use", async () => {
    withStdout(JSON.stringify({
      card: { sig: "s1", status: { state: "ok" }, stateBlanks: [] },
      panel: { sig: "s2", status: { state: "error", kind: "build", message: "boom" }, stateBlanks: ["empty"] },
    }));
    const cache = await loadScanCache();
    expect(Object.keys(cache).sort()).toEqual(["card", "panel"]);
    expect(cache.panel.sig).toBe("s2");
    // The status rides verbatim — the cache is a courier for the frontend's own shape.
    expect(cache.panel.status).toEqual({ state: "error", kind: "build", message: "boom" });
    expect(cache.panel.stateBlanks).toEqual(["empty"]);
  });

  it("returns EMPTY on every failure shape — an unreadable cache means scan everything", async () => {
    // Each of these is a real state: no bridge, an old binary that lacks the verb, a half-written file.
    for (const out of ["", "not json", "[1,2,3]", "null", '"a string"']) {
      withStdout(out);
      expect(await loadScanCache()).toEqual({});
    }
    vi.spyOn(bscMod, "bsc").mockRejectedValue(new Error("no bridge"));
    expect(await loadScanCache()).toEqual({});
  });

  it("drops a row with no signature — half the key is missing, so it could never be a hit", async () => {
    // Dropping it here is honest: keeping it would look like a valid entry that mysteriously never
    // matches, which is harder to diagnose than its absence.
    withStdout(JSON.stringify({
      good: { sig: "s1", status: { state: "ok" }, stateBlanks: [] },
      noSig: { status: { state: "ok" }, stateBlanks: [] },
      emptySig: { sig: "", status: { state: "ok" }, stateBlanks: [] },
      noStatus: { sig: "s2" },
    }));
    expect(Object.keys(await loadScanCache())).toEqual(["good"]);
  });

  it("defaults a missing stateBlanks to [] rather than dropping the row", async () => {
    // `[]` is meaningful (it CLEARS a blank badge), and a row from an older writer that omitted it is
    // still a usable signature — the point is to skip a rebuild, and that half is intact.
    withStdout(JSON.stringify({ card: { sig: "s1", status: { state: "ok" } } }));
    expect((await loadScanCache()).card.stateBlanks).toEqual([]);
  });
});

describe("saveScanCache", () => {
  it("sends the entries as one JSON object on stdin", async () => {
    const spy = vi.spyOn(bscMod, "bsc").mockResolvedValue("1");
    const entries: Record<string, CachedScan> = {
      card: { sig: "s1", status: { state: "ok" }, stateBlanks: [] },
    };
    await saveScanCache(entries);
    expect(spy).toHaveBeenCalledWith(null, ["ui", "scan-cache", "put"], JSON.stringify(entries));
  });

  it("writes NOTHING for an empty batch — no spawn for no work", async () => {
    const spy = vi.spyOn(bscMod, "bsc").mockResolvedValue("0");
    await saveScanCache({});
    expect(spy).not.toHaveBeenCalled();
  });

  it("never throws when the bridge is absent — a failed write costs a re-scan, not a crash", async () => {
    vi.spyOn(bscMod, "bsc").mockRejectedValue(new Error("no bridge"));
    await expect(saveScanCache({ a: { sig: "s", status: { state: "ok" }, stateBlanks: [] } })).resolves.toBeUndefined();
  });
});

describe("the cache and the sweep agree on what is pending", () => {
  // The join that makes the whole thing work: `pendingScans` already decides by signature, so a cache
  // seeded into the same map is understood without teaching it anything new.
  it("skips a component whose cached signature still matches", async () => {
    vi.spyOn(bscMod, "bsc").mockResolvedValue(JSON.stringify({
      card: { sig: "s1", status: { state: "ok" }, stateBlanks: [] },
    }));
    const cache = await loadScanCache();
    const seeded = new Map(Object.entries(cache).map(([id, e]) => [id, e.sig]));
    expect(pendingScans([scannable("card", "s1")], seeded)).toEqual([]);
  });

  it("RE-SCANS a component whose source changed, even though its id is cached", async () => {
    // The stale-entry case. The signature is part of the key precisely so an edit cannot be masked.
    vi.spyOn(bscMod, "bsc").mockResolvedValue(JSON.stringify({
      card: { sig: "OLD", status: { state: "ok" }, stateBlanks: [] },
    }));
    const cache = await loadScanCache();
    const seeded = new Map(Object.entries(cache).map(([id, e]) => [id, e.sig]));
    expect(pendingScans([scannable("card", "NEW")], seeded).map((s) => s.id)).toEqual(["card"]);
  });

  it("scans everything when the cache is unreachable — the safe direction, end to end", async () => {
    vi.spyOn(bscMod, "bsc").mockRejectedValue(new Error("no bridge"));
    const cache = await loadScanCache();
    const seeded = new Map(Object.entries(cache).map(([id, e]) => [id, e.sig]));
    const all = [scannable("a", "1"), scannable("b", "2")];
    expect(pendingScans(all, seeded)).toHaveLength(2);
  });
});

// #4072 — the Studio's two-phase hydration. The Design Studio page blocked up to 8040ms on
// `bsc ui list --full` (1.72 MB over 321 components, 77.6% of it `srcText` no node reads). Phase 1
// now paints from `bsc ui list --graph` (33 KB); phase 2 fetches the full records in the background.
//
// A LITE record's empty `srcText` is a DEFAULT, not a value, and these lock the places that
// distinction is load-bearing — each of which silently does the wrong thing without it.
import { describe, it, expect } from "vitest";
import { scannableComponents } from "@/features/designs/lib/componentScan";
import { projectComponent } from "./componentBridge";
import type { KitArtifact } from "./componentPreview";
import type { ComponentRecord } from "@/features/designs/lib/model";

// Same fixture shape as componentScan.test.ts: the artifact supplies the built-in's source by `src`.
const base: ComponentRecord = {
  id: "card", name: "Card", kitId: "react-ui", role: "primitive", version: "1.0.0", used: 0,
  tags: [], variants: ["default"], composes: [], props: [], whenUse: [], whenNot: [],
  src: "shared/ui/data/Card.tsx", srcText: "",
};

const ARTIFACT: KitArtifact = {
  components: [
    { id: "card", src: "shared/ui/data/Card.tsx", source: "export function Card() { return null; }" },
  ],
  runtime: {},
};

describe("lite records are never mistaken for source-less ones (#4072)", () => {
  it("scans a normal record — the baseline proving this fixture is buildable", () => {
    expect(scannableComponents([base], ARTIFACT).map((s) => s.id)).toEqual(["card"]);
  });

  it("SKIPS the same record once it is lite", () => {
    // Identical in every other respect, so `lite` is provably the reason. Without the skip, a lite
    // record's empty `srcText` reads as "not buildable" and the component is either dropped from the
    // scan or badged broken — and that verdict is cached under its signature.
    expect(scannableComponents([{ ...base, lite: true }], ARTIFACT)).toEqual([]);
  });

  it("does not poison the sweep — a lite record's siblings still scan", () => {
    const sibling: ComponentRecord = { ...base, id: "card2", name: "Card2" };
    const artifact: KitArtifact = {
      components: [
        ...ARTIFACT.components,
        { id: "card2", src: "shared/ui/data/Card.tsx", source: "export function Card2() { return null; }" },
      ],
      runtime: {},
    };
    const out = scannableComponents([{ ...base, lite: true }, sibling], artifact);
    expect(out.map((s) => s.id)).toEqual(["card2"]);
  });

  it("projectComponent leaves `lite` unset for a normal record", () => {
    // Only the graph loader stamps it; a full record must never carry it, or the preview would wait
    // forever for a second read that is never coming.
    expect(projectComponent({ id: "x", name: "X", kitId: "k" }).lite).toBeUndefined();
  });
});

// The frame's REGISTRY contract (#3437 + the navigate-ack fix).
//
// The build effect used to return early on a refused build without touching the iframe or the registry,
// so `registerPreviewFrame` kept naming the LAST component that built. Everything downstream then read a
// mount that was no longer on screen: `bsc debug frames` reported it, and `bsc navigate` acked it — the
// designer saw `navigate plan-body-deployment` succeed while the preview still showed `ui-tab-bar`.
//
// These tests drive the REAL component. They deliberately do not need esbuild: the refused-build path is
// synchronous (`componentPreviewFiles` returns null), which is exactly the path that was silent.
import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import { render, waitFor, cleanup } from "@testing-library/react";
// NOTE: the feature barrel is imported FIRST on purpose. `lib/libraryModules` reaches the algorithms
// BARREL, and pulling this component in through a different entry order re-enters that module graph
// mid-initialisation ("algoNodeLookup is not a function") — a known cycle, not a defect in this test.
import "@/features/designs";
import { useAppStore } from "@/store";
import { ComponentPreviewFrame } from "@/features/designs/ComponentPreviewFrame";
import { mountedPreviewFrames, resetPreviewFrames } from "./lib/previewRegistry";
import { recordPreviewError, clearPreviewError } from "./lib/componentBridge";
import type { ComponentRecord } from "@/features/designs/lib/model";

// The bridge shells out to `bsc`; only WHETHER the two error verbs were called matters here. PARTIAL
// mock — the module is the Studio's whole `bsc` surface and the frame's siblings import the rest of it,
// so replacing it wholesale breaks unrelated modules at import time.
vi.mock("./lib/componentBridge", async (importOriginal) => ({
  ...(await importOriginal<typeof import("./lib/componentBridge")>()),
  recordPreviewError: vi.fn(async () => {}),
  clearPreviewError: vi.fn(async () => {}),
}));

/** A record whose `srcText` is a usage SNIPPET, not a runnable module — `componentPreviewFiles` returns
 *  null for it, which is the refused-build path. */
const snippet = (id: string): ComponentRecord => ({
  id, name: id, kitId: "test-kit", role: "primitive", version: "1.0.0", used: 0,
  tags: [], variants: ["default"], composes: [], props: [], whenUse: [], whenNot: [],
  src: `test-kit/${id}.tsx`, srcText: `<${id} label="hi" />`,
});

const frameProps = { theme: "dark" as const, themeId: "default", themeVars: {}, width: 200 };

describe("ComponentPreviewFrame — the registry never names a component that is not on screen", () => {
  beforeEach(() => {
    resetPreviewFrames();
    useAppStore.setState({ kits: [{ id: "test-kit", name: "Test" }], components: [] } as never);
  });
  afterEach(() => cleanup());

  it("registers a REFUSED build under the component it refused, with the reason", async () => {
    render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);

    await waitFor(() => expect(mountedPreviewFrames()).toHaveLength(1));
    const [f] = mountedPreviewFrames();
    expect(f.component).toBe("achievements");
    expect(f.status).toBe("error");
    expect(f.error).toContain("no implementation source yet");
  });

  it("REPRODUCER: switching to a component that cannot build stops reporting the previous one", async () => {
    const { rerender } = render(<ComponentPreviewFrame comp={snippet("ui-tab-bar")} {...frameProps} />);
    await waitFor(() => expect(mountedPreviewFrames()).toHaveLength(1));

    rerender(<ComponentPreviewFrame comp={snippet("plan-body-deployment")} {...frameProps} />);
    await waitFor(() => expect(mountedPreviewFrames()[0]?.component).toBe("plan-body-deployment"));
    // The old entry is REPLACED, not accumulated — one frame, one truth.
    expect(mountedPreviewFrames()).toHaveLength(1);
    expect(mountedPreviewFrames().map((f) => f.component)).not.toContain("ui-tab-bar");
  });

  it("leaves nothing of the previous component rendered underneath the error overlay", async () => {
    const { container, rerender } = render(<ComponentPreviewFrame comp={snippet("a")} {...frameProps} />);
    const iframe = container.querySelector("iframe")!;
    iframe.srcdoc = "<html><body>the PREVIOUS component</body></html>";

    rerender(<ComponentPreviewFrame comp={snippet("b")} {...frameProps} />);
    // A capture that photographs the iframe must not find the component that is no longer selected.
    await waitFor(() => expect(iframe.srcdoc).toBe(""));
  });
});

// #45/#60: the error record is written on a failed render and must be RETIRED on a successful one.
// Without the success half, a component fixed by a change elsewhere — a shared dependency, or a resolver
// bug in the preview itself — kept its `render-error` finding forever, and `bsc ui doctor` reported a
// failure that a live `bsc shot preview` disproved. Measured right after the barrel-resolution fix:
// components that mounted fine still carried 54 findings between them.
describe("ComponentPreviewFrame — a render that succeeds retires the recorded error", () => {
  beforeEach(() => {
    resetPreviewFrames();
    vi.mocked(clearPreviewError).mockClear();
    vi.mocked(recordPreviewError).mockClear();
    useAppStore.setState({ kits: [{ id: "test-kit", name: "Test" }], components: [] } as never);
  });
  afterEach(() => cleanup());

  /** Post a preview signal AS the frame's own iframe, which is the only source it accepts (#2908). */
  const post = (container: HTMLElement, data: unknown) => {
    const iframe = container.querySelector("iframe") as HTMLIFrameElement;
    window.dispatchEvent(new MessageEvent("message", { data, source: iframe.contentWindow }));
  };

  it("REPRODUCER: clears the recorded error when the preview reports ready", async () => {
    const { container } = render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    post(container, { __preview: "ready" });
    await waitFor(() => expect(vi.mocked(clearPreviewError)).toHaveBeenCalledWith("achievements"));
    expect(vi.mocked(recordPreviewError)).not.toHaveBeenCalled();
  });

  it("still RECORDS on a runtime error, and does not clear", async () => {
    const { container } = render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    post(container, { __preview: "error", message: "boom" });
    await waitFor(() => expect(vi.mocked(recordPreviewError)).toHaveBeenCalledWith("achievements", "boom"));
    expect(vi.mocked(clearPreviewError)).not.toHaveBeenCalled();
  });

  it("ignores a ready from ANOTHER window, so a concurrent scan probe cannot clear this component", () => {
    render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    // #2908: the on-visit scan runs its own hidden probe iframes; their messages must not be honoured.
    window.dispatchEvent(new MessageEvent("message", { data: { __preview: "ready" }, source: window }));
    expect(vi.mocked(clearPreviewError)).not.toHaveBeenCalled();
  });

  // #126: `srcdoc` reassignment does not synchronously replace the iframe's document — the outgoing one
  // (a pending timer, a late async throw) keeps running until the new one loads, and the SAME reused
  // `<iframe>`'s `contentWindow` cannot tell that leftover apart from the current build by source alone.
  // Live symptom: a designer navigating rapidly between graph-hosted pages (fleetpage/mcppage) saw an
  // unrelated earlier build's `SecurityError`/`STARTER_KIT is undefined` attributed to whichever page was
  // current when the stale message finally arrived (designer request #126).
  it("STALE-BUILD GUARD: a message tagged with an earlier generation is dropped even from this frame's own iframe window", async () => {
    const { container, rerender } = render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    await waitFor(() => expect(mountedPreviewFrames()[0]?.component).toBe("achievements")); // build #1 settles

    rerender(<ComponentPreviewFrame comp={snippet("plan-body-deployment")} {...frameProps} />);
    await waitFor(() => expect(mountedPreviewFrames()[0]?.component).toBe("plan-body-deployment")); // build #2

    // A message from build #1's still-finishing document, arriving after build #2 has already started —
    // it carries build #1's generation, and must not be attributed to the CURRENTLY selected component.
    post(container, { __preview: "error", message: "stale — from the torn-down previous build", __gen: 1 });
    expect(vi.mocked(recordPreviewError)).not.toHaveBeenCalled();

    // The CURRENT build's own message (generation 2) is still honoured.
    post(container, { __preview: "error", message: "the real error", __gen: 2 });
    await waitFor(() =>
      expect(vi.mocked(recordPreviewError)).toHaveBeenCalledWith("plan-body-deployment", "the real error"),
    );
  });

  it("a message carrying no __gen at all (a caller that never set buildGen) is still honoured", async () => {
    const { container } = render(<ComponentPreviewFrame comp={snippet("achievements")} {...frameProps} />);
    post(container, { __preview: "ready" });
    await waitFor(() => expect(vi.mocked(clearPreviewError)).toHaveBeenCalledWith("achievements"));
  });
});

// Fork visibility (#4106). A director spawned a general-purpose subagent titled "Wake
// mobile-crash-reporting worker" to do a worker's job, and nothing in the system could see it: a fork
// has no pane, no roster row, no worktree and no branch. These cover the event that fixes that.
import { describe, it, expect } from "vitest";
import { parseCoordLine, applyCoordEvent } from "@/shared/lib/fleet/coordinationLog";
import { emptyCoordState } from "@/shared/lib/fleet/coordinationState";
import type { CoordState } from "@/shared/lib/fleet/coordination.types";

const line = (session: string, desc: string, type = "general-purpose") =>
  `2026-07-31T20:15:55Z\t${session}\tfork\t${desc}\t${type}`;

describe("parseCoordLine — fork", () => {
  it("parses the real event that prompted this", () => {
    const e = parseCoordLine(line("studio-code:director", "Wake mobile-crash-reporting worker"));
    expect(e).toEqual({
      type: "fork",
      session: "studio-code:director",
      description: "Wake mobile-crash-reporting worker",
      subagentType: "general-purpose",
      at: Date.parse("2026-07-31T20:15:55Z"),
    });
  });

  it("keeps the event when no subagent type was named", () => {
    // The hook emits an empty column rather than omitting it; an unnamed type must not drop the fork.
    const e = parseCoordLine("2026-07-31T20:15:55Z\tp:director\tfork\tReview six PRs\t");
    expect(e).toMatchObject({ type: "fork", description: "Review six PRs", subagentType: undefined });
  });

  it("rejects a fork with no description rather than recording a blank one", () => {
    expect(parseCoordLine("2026-07-31T20:15:55Z\tp:director\tfork\t\t")).toBeNull();
  });
});

describe("applyCoordEvent — fork", () => {
  const fork = (session: string, description: string, at: number) =>
    ({ type: "fork", session, description, at }) as const;

  it("records the fork so it is no longer an invisible actor", () => {
    const { state } = applyCoordEvent(emptyCoordState(), fork("p:director", "Wake worker", 1));
    expect(state.forks).toEqual([
      { id: "p:director@1", session: "p:director", description: "Wake worker", subagentType: undefined, at: 1 },
    ]);
  });

  it("does not multiply a fork when the log is replayed", () => {
    // ingestCoordLog replays the whole file; a re-read must not turn one fork into many.
    let s: CoordState = emptyCoordState();
    s = applyCoordEvent(s, fork("p:director", "Wake worker", 1)).state;
    s = applyCoordEvent(s, fork("p:director", "Wake worker", 1)).state;
    expect(s.forks.length).toBe(1);
  });

  it("keeps every distinct fork — the designer's harvest fan-out is 13 of them", () => {
    let s: CoordState = emptyCoordState();
    for (let i = 0; i < 13; i++) s = applyCoordEvent(s, fork("design-studio:designer", `Harvest chunk ${i}`, i)).state;
    expect(s.forks.length).toBe(13);
  });

  it("never wakes, readies or stalls anything — it is OBSERVATION, not coordination", () => {
    // A fork must not perturb the latch machinery: recording one is not a fleet transition.
    const out = applyCoordEvent(emptyCoordState(), fork("p:director", "Review PRs", 1));
    expect(out.woken).toEqual([]);
    expect(out.ready).toBe(false);
    expect(out.stalled).toEqual([]);
    expect(out.answered).toEqual([]);
    expect(out.assigned).toEqual([]);
  });
});

// The WHOLE chain, end to end (#4118) — real fleet shape → progress → buildGraph → the node.
//
// Every layer was verified in isolation and the bars still did not appear, twice. That is the signature
// of a JOIN that fails silently: each half is correct and the keys do not meet. This asserts the join.
import { describe, it, expect } from "vitest";
import { fleetPlanProgress } from "@/features/glance/lib/fleetPlanProgress";
import { withStreamProgress } from "@/features/glance/lib/streamProgress";
import { buildRealFleetData } from "@/features/glance/lib/glanceFleet";
import { buildGraph } from "@/features/glance/lib/glanceGraph";
import { fleetToOrg } from "@/features/glance/lib/glanceFleet";

// The live shape: streams carrying GitHub refs, exactly as `bsc plan fleet get` returns them.
const fleet = {
  streams: [
    { id: "cli-platform", name: "CLI", repo: "kev/app", owns: [], issues: ["#3898", "#3979"], dependsOn: [] },
    { id: "console", name: "Console", repo: "kev/app", owns: [], issues: ["#3871"], dependsOn: [] },
    { id: "standing", name: "Standing", repo: "kev/app", owns: [], issues: [], dependsOn: [] },
  ],
  director: { enabled: true },
} as unknown as Parameters<typeof fleetToOrg>[0];

describe("progress reaches the rendered node (#4118)", () => {
  it("a fleet node's id IS its stream id — the join the whole feature rests on", () => {
    // If these ever diverge, every lookup misses and the bars vanish with nothing failing.
    const org = fleetToOrg(fleet);
    const ids = org.positions.map((p) => p.nodeId);
    expect(ids).toContain("cli-platform");
    expect(ids).toContain("console");
  });

  it("carries done/total from the stream refs all the way onto the built graph node", () => {
    const byStream = fleetPlanProgress(fleet.streams, new Set(["3898", "3871"]));
    const raw = withStreamProgress(buildRealFleetData(fleet, []).rawNodes, byStream);
    const graph = buildGraph(raw, []);

    const cli = graph.nodes.find((n) => n.id === "cli-platform");
    expect(cli?.progress).toEqual({ done: 1, total: 2 });
    const console_ = graph.nodes.find((n) => n.id === "console");
    expect(console_?.progress).toEqual({ done: 1, total: 1 });
  });

  it("a stream owning nothing reaches the node with total 0, so it draws no bar", () => {
    const byStream = fleetPlanProgress(fleet.streams, new Set());
    const raw = withStreamProgress(buildRealFleetData(fleet, []).rawNodes, byStream);
    const graph = buildGraph(raw, []);
    expect(graph.nodes.find((n) => n.id === "standing")?.progress).toEqual({ done: 0, total: 0 });
  });

  it("buildGraph does not DROP progress while mapping raw nodes to graph nodes", () => {
    // The spread at the node construction is load-bearing; an explicit field list would silently lose it.
    const raw = withStreamProgress(
      buildRealFleetData(fleet, []).rawNodes,
      fleetPlanProgress(fleet.streams, new Set(["3898"])),
    );
    expect(raw.some((n) => n.progress)).toBe(true);
    expect(buildGraph(raw, []).nodes.some((n) => n.progress)).toBe(true);
  });
});

// glance-progress-ref-namespace-split — a fleet stream's `issues` and plan.db's `ref` column are two
// SEPARATE ownership records, and they need not share a namespace.
//
// WHY NO EXISTING TEST CAUGHT THIS. Every fixture in the suite uses ONE ref shape throughout — refs go
// in, the same refs come out, `done` matches, green. The bug only exists where the two shapes MEET, so
// it is structurally invisible to a single-shape fixture. That is what this file supplies: both shapes
// in one fixture, which is the shape of the real data.
//
// Measured on the two live projects when this was filed:
//   base-studio-code   22 stream refs, ALL plan.db slugs   -> 22/22 resolve, the ref path is right
//   studio-code        56 stream refs, ALL GitHub numbers  -> 0/56 resolve, and every owning node read
//                                                             0/N while plan.db knew the real answer
import { describe, it, expect } from "vitest";
import { fleetPlanProgress, knownRefAliases, mergeStreamProgress, unionDone } from "@/features/glance/lib/fleetPlanProgress";
import { streamProgress, projectProgress } from "@/features/glance/lib/streamProgress";
import type { OwnedIssue } from "@/shared/lib/fleet/workerEnd";

/** plan.db as `studio-code` actually holds it: slug refs, no GitHub identity anywhere. */
const SLUG_ISSUES: OwnedIssue[] = [
  { ref: "glance-planner-node-per-project", status: "verified", stream: "glance" },
  { ref: "glance-project-studio-sessions", status: "verified", stream: "glance" },
  { ref: "glance-open-issue", status: "open", stream: "glance" },
  { ref: "design-studio-a", status: "complete", stream: "design-studio" },
  { ref: "design-studio-b", status: "verified", stream: "design-studio" },
  // Owned by NO stream — counted by the project, never by a worker.
  { ref: "unowned-chore", status: "verified" },
];

/** The same project's fleet, whose streams were authored with GitHub NUMBERS. */
const NUMERIC_STREAMS = [
  { id: "glance", issues: ["#233", "#234"] },
  { id: "design-studio", issues: ["#243", "#245", "#246"] },
];

describe("stream refs in a namespace plan.db has never seen", () => {
  const known = knownRefAliases(SLUG_ISSUES);
  const done = unionDone(SLUG_ISSUES.filter((i) => i.status === "verified" || i.status === "complete").map((i) => i.ref));

  it("resolves none of them — the premise of the bug, stated as a fact", () => {
    const refs = NUMERIC_STREAMS.flatMap((s) => s.issues).map((r) => r.replace(/^#/, ""));
    expect(refs.some((r) => known.has(r))).toBe(false);
  });

  it("emits NO ref-path entry for a stream whose refs all resolve to nothing", () => {
    const out = fleetPlanProgress(NUMERIC_STREAMS, done, undefined, known);
    expect(out.has("glance")).toBe(false);
    expect(out.has("design-studio")).toBe(false);
  });

  it("so plan.db answers, and a stream that IS done stops reading 0/N", () => {
    const merged = mergeStreamProgress(
      fleetPlanProgress(NUMERIC_STREAMS, done, undefined, known),
      streamProgress(SLUG_ISSUES),
    );
    // The reported case: plan.db knows design-studio is 2/2, the ref path claimed 0/3, and the ref path won.
    expect(merged.get("design-studio")).toEqual({ done: 2, total: 2 });
    expect(merged.get("glance")).toEqual({ done: 2, total: 3 });
  });

  it("gives the DIRECTOR no aggregate it cannot substantiate", () => {
    const out = fleetPlanProgress(NUMERIC_STREAMS, done, "director", known);
    // Not `{done: 0, total: 5}` — an unmovable denominator is worse than none, and 0/5 reads as
    // "nothing done" for a board that is mostly finished.
    expect(out.has("director")).toBe(false);
  });

  it("the project number the director falls back to counts UNOWNED issues too", () => {
    // 5 of 6 are complete|verified — including `unowned-chore`, which NO stream counts. Summing the
    // per-stream rows says 4/5, and that gap is exactly why the director cannot just add up its workers.
    expect(projectProgress(SLUG_ISSUES)).toEqual({ done: 5, total: 6 });
    const perStream = [...streamProgress(SLUG_ISSUES).values()].reduce(
      (a, p) => ({ done: a.done + p.done, total: a.total + p.total }), { done: 0, total: 0 },
    );
    expect(perStream).not.toEqual(projectProgress(SLUG_ISSUES));
  });
});

describe("stream refs in plan.db's OWN namespace still work — this must not regress", () => {
  // `base-studio-code`: the streams carry the same slugs plan.db does.
  const SLUG_STREAMS = [
    { id: "glance", issues: ["glance-planner-node-per-project", "glance-open-issue"] },
    { id: "design-studio", issues: ["design-studio-a", "design-studio-b"] },
  ];
  const known = knownRefAliases(SLUG_ISSUES);
  const done = unionDone(["glance-planner-node-per-project", "design-studio-a", "design-studio-b"]);

  it("the ref path answers, with the stream's OWN denominator", () => {
    const out = fleetPlanProgress(SLUG_STREAMS, done, "director", known);
    expect(out.get("glance")).toEqual({ done: 1, total: 2 });
    expect(out.get("design-studio")).toEqual({ done: 2, total: 2 });
    // …and the director aggregates the union, de-duplicated.
    expect(out.get("director")).toEqual({ done: 3, total: 4 });
  });

  it("a slug carrying its origin number also answers to that number", () => {
    const aliases = knownRefAliases([{ ref: "4260-sandbox-by-default" }]);
    expect(aliases.has("4260-sandbox-by-default")).toBe(true);
    expect(aliases.has("4260")).toBe(true);
    // …so a stream written with `#4260` resolves against a plan.db that stores the slug.
    const out = fleetPlanProgress([{ id: "s", issues: ["#4260"] }], unionDone(["4260-sandbox-by-default"]), undefined, aliases);
    expect(out.get("s")).toEqual({ done: 0, total: 1 });
    expect(out.has("s")).toBe(true); // it RESOLVED — done-ness is a separate question from resolvability
  });

  it("omitting `knownRefs` keeps the old behaviour exactly — no caller is forced to change", () => {
    const out = fleetPlanProgress(NUMERIC_STREAMS, done, "director");
    expect(out.get("glance")).toEqual({ done: 0, total: 2 });
    expect(out.get("director")).toEqual({ done: 0, total: 5 });
  });
});

// The algorithms folder tree (#4107, reshaped by #4128) — the SAME nested model the components kit
// renders, down to the trailing "ungrouped" bucket and the caller-preserved ordering.
import { describe, it, expect } from "vitest";
import { UNGROUPED_KEY, UNGROUPED_LABEL } from "@/shared/lib/core/folderTree";
import { folderTree, folderImplCount, type AlgoImpl } from "@/features/algorithms/lib/knowledge";

const im = (id: string, folder?: string, role: "primitive" | "algorithm" = "algorithm"): AlgoImpl =>
  ({ id, name: id.replace(/\..*$/, ""), tech: "rust", role, composes: [], folder }) as AlgoImpl;

describe("folderTree", () => {
  it("nests folders the way the source tree nests", () => {
    // The real shape a repo-root harvest produces (measured: 1982 candidates across 62 folders).
    const t = folderTree([
      im("job.rs", "src-tauri/src/console/pty"),
      im("mod.rs", "src-tauri/src/console"),
      im("perf.rs", "src-tauri/src/observability"),
    ])!;
    expect(t.map((r) => r.label)).toEqual(["src-tauri"]);
    const src = t[0].folders[0];
    expect(src.label).toBe("src");
    expect(src.folders.map((c) => c.label)).toEqual(["console", "observability"]);
    const console_ = src.folders[0];
    expect(console_.items.map((i) => i.id)).toEqual(["mod.rs"]);
    expect(console_.folders[0].key).toBe("src-tauri/src/console/pty");
    expect(console_.folders[0].items.map((i) => i.id)).toEqual(["job.rs"]);
  });

  it("buckets unfoldered impls LAST instead of spilling them flat (#4128 — the components rule)", () => {
    // Before #4128 these came back in a separate `unfoldered` array the rail rendered beside the tree;
    // the components rail has always bucketed them, so a partially-foldered library now reads the same
    // in both. The seeded classics carry no `src`, so this is the COMMON case here, not an edge one.
    const t = folderTree([im("merge.rs"), im("bfs.rs"), im("job.rs", "src-tauri/src/console/pty")])!;
    expect(t.map((f) => f.label)).toEqual(["src-tauri", UNGROUPED_LABEL]);
    const bucket = t[t.length - 1];
    expect(bucket.ungrouped).toBe(true);
    expect(bucket.key).toBe(UNGROUPED_KEY);
    expect(bucket.items.map((i) => i.id)).toEqual(["merge.rs", "bfs.rs"]);
  });

  it("returns null when NOTHING carries a folder — the rail renders its flat list unchanged", () => {
    // Every impl in the live store was unfoldered before #4119; those must come back as a flat list,
    // NOT collapsed under one blank folder. The change stays additive.
    expect(folderTree([im("merge.rs"), im("bfs.rs")])).toBeNull();
    expect(folderTree([])).toBeNull();
  });

  it("treats a blank folder as unfoldered rather than a `\"\"` node", () => {
    expect(folderTree([im("a.rs", "   ")])).toBeNull();
    const t = folderTree([im("a.rs", "   "), im("b.rs", "core")])!;
    expect(t.map((f) => f.label)).toEqual(["core", UNGROUPED_LABEL]);
    expect(t[1].items.map((i) => i.id)).toEqual(["a.rs"]);
  });

  it("preserves the CALLER's order — primitives before algorithms survives into every folder", () => {
    // `groupImplsByLanguage` sorts primitives first; the tree must not re-sort that away (the pre-#4128
    // algorithms builder sorted folders alphabetically and impls by role+name itself, which silently
    // overrode whatever order the rail had chosen).
    const t = folderTree([
      im("rust.vec", "core", "primitive"),
      im("zeta.rs", "core", "algorithm"),
      im("alpha.rs", "core", "algorithm"),
      im("b.rs", "bar"),
    ])!;
    expect(t.map((r) => r.label)).toEqual(["core", "bar"]); // first-appearance, not alphabetical
    expect(t[0].items.map((i) => i.id)).toEqual(["rust.vec", "zeta.rs", "alpha.rs"]);
  });

  it("places two impls sharing a folder side by side, and counts a subtree transitively", () => {
    const t = folderTree([im("a.rs", "crates/x/src"), im("b.rs", "crates/x/src")])!;
    const leaf = t[0].folders[0].folders[0];
    expect(leaf.key).toBe("crates/x/src");
    expect(leaf.items).toHaveLength(2);
    expect(folderImplCount(t[0])).toBe(2);
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { gistIdFromUrl, pickManifestContent, publishGist, updateGist, installFromGist, fetchGistManifestText, MANIFEST_FILENAME } from "@/features/planner/lib/gist/gist";
import { wrapExtension } from "@/features/planner/lib/gist/manifest";

describe("gist transport — pure helpers (#598)", () => {
  it("extracts a gist id from URLs, api URLs, and bare ids", () => {
    expect(gistIdFromUrl("https://gist.github.com/kevin/0123456789abcdef")).toBe("0123456789abcdef");
    expect(gistIdFromUrl("https://gist.github.com/0123456789abcdef")).toBe("0123456789abcdef");
    expect(gistIdFromUrl("https://api.github.com/gists/0123456789abcdef")).toBe("0123456789abcdef");
    expect(gistIdFromUrl("0123456789abcdef")).toBe("0123456789abcdef");
    expect(gistIdFromUrl("not a gist")).toBeNull();
    expect(gistIdFromUrl("")).toBeNull();
  });

  it("picks the manifest file (named first, else first .json)", () => {
    expect(pickManifestContent({ [MANIFEST_FILENAME]: { content: "A", filename: MANIFEST_FILENAME } })).toBe("A");
    expect(pickManifestContent({ "other.json": { content: "B", filename: "other.json" } })).toBe("B");
    expect(pickManifestContent({ "readme.md": { content: "C", filename: "readme.md" } })).toBeNull();
    expect(pickManifestContent(undefined)).toBeNull();
  });
});

describe("gist transport — invoke-backed (#598)", () => {
  beforeEach(() => vi.mocked(invoke).mockReset());

  it("publishGist sends the manifest file and returns id + url", async () => {
    vi.mocked(invoke).mockResolvedValueOnce({ id: "gid", html_url: "https://gist.github.com/u/gid", files: {} });
    const m = wrapExtension("blueprint", "bp", "My BP", "1.0.0", { x: 1 });
    const res = await publishGist("tok", m, { description: "d" });
    expect(res).toEqual({ id: "gid", htmlUrl: "https://gist.github.com/u/gid" });
    const [cmd, args] = vi.mocked(invoke).mock.calls[0];
    expect(cmd).toBe("gist_create");
    expect((args as { files: Record<string, string> }).files[MANIFEST_FILENAME]).toContain("\"id\": \"bp\"");
    expect((args as { public: boolean }).public).toBe(false); // secret by default
  });

  it("updateGist PATCHes an existing gist by id and returns id + url (#970)", async () => {
    vi.mocked(invoke).mockResolvedValueOnce({ id: "gid", html_url: "https://gist.github.com/u/gid", files: {} });
    const m = wrapExtension("blueprint", "bp", "My BP", "1.0.0", { x: 2 });
    const res = await updateGist("tok", "gid", m, { description: "d2" });
    expect(res).toEqual({ id: "gid", htmlUrl: "https://gist.github.com/u/gid" });
    const [cmd, args] = vi.mocked(invoke).mock.calls[0];
    expect(cmd).toBe("gist_update");                                  // updates in place, not gist_create
    expect((args as { id: string }).id).toBe("gid");
    expect((args as { files: Record<string, string> }).files[MANIFEST_FILENAME]).toContain("\"id\": \"bp\"");
    expect((args as Record<string, unknown>).public).toBeUndefined(); // visibility is fixed on update
  });

  it("installFromGist fetches the gist and validates its manifest", async () => {
    const m = wrapExtension("blueprint", "bp", "My BP", "1.0.0", { x: 1 });
    vi.mocked(invoke).mockResolvedValueOnce({
      id: "gid", files: { [MANIFEST_FILENAME]: { content: JSON.stringify(m), filename: MANIFEST_FILENAME } },
    });
    const res = await installFromGist("https://gist.github.com/u/0123456789abcdef");
    expect(res.ok).toBe(true);
    if (res.ok) expect(res.manifest.id).toBe("bp");
  });

  it("installFromGist rejects a bad ref and a gist with no manifest", async () => {
    expect((await installFromGist("nonsense")).ok).toBe(false);
    vi.mocked(invoke).mockResolvedValueOnce({ id: "gid", files: { "readme.md": { content: "hi", filename: "readme.md" } } });
    expect((await installFromGist("0123456789abcdef")).ok).toBe(false);
  });

  it("fetchGistManifestText soft-fails on a null/404 gist response instead of throwing (#2515)", async () => {
    vi.mocked(invoke).mockResolvedValueOnce(null);
    const res = await fetchGistManifestText("0123456789abcdef");
    expect(res).toEqual({ ok: false, error: "no extension manifest found in that gist" });
  });
});

