// buildGlanceData emits the integration band (`the-integration-band-gets-its-data-path`).
//
// The projection itself is tested in glanceIntegrationNodes.test.ts; these are about the WIRING —
// that the band actually reaches the graph, that it contributes nothing when there is nothing, and
// that it is handed the project set so no dangling edge is drawn.
import { describe, it, expect } from "vitest";
import { buildGlanceData } from "@/features/glance/lib/glanceData";
import { integrationNodeId, usesIntegrationEdgeId, isBandNode } from "@/features/glance/lib/glanceGraph";

const projects = [{ id: "storefront", name: "Storefront" }, { id: "billing", name: "Billing" }];
const build = (declared = [] as never[], connectors = [] as never[]) =>
  buildGlanceData(projects, [], [], [], [], [], [], declared, connectors);

describe("buildGlanceData · the integration band", () => {
  /// THE STATE OF EVERY MACHINE TODAY: nothing declared, nothing registered. It must add no marks.
  it("contributes nothing when nothing is declared or registered", () => {
    const d = build();
    expect(d.rawNodes.filter((n) => n.kind === "integration")).toEqual([]);
    expect(d.rawEdges.filter((e) => e.kind === "uses-integration")).toEqual([]);
    // ...and the projects are untouched, so wiring this in changed no existing node.
    expect(d.rawNodes.map((n) => n.id)).toEqual(["storefront", "billing"]);
  });

  it("emits a band node and its project edge once something is declared", () => {
    const d = build(
      [{ project: "storefront", id: "stripe", name: "Stripe" }] as never[],
      [{ id: "stripe", state: "live" }] as never[],
    );
    const node = d.rawNodes.find((n) => n.id === integrationNodeId("stripe"));
    expect(node).toBeDefined();
    expect(node!.health).toBe("healthy");
    expect(isBandNode(node!)).toBe(true);
    expect(d.rawEdges.map((e) => e.id)).toContain(usesIntegrationEdgeId("storefront", "stripe"));
  });

  /// The project set is passed for a reason: a declaration from a project NOT in this graph would
  /// otherwise draw an edge to an id nothing renders.
  it("draws no edge from a project that is not in the graph", () => {
    const d = build(
      [{ project: "ghost", id: "stripe" }, { project: "billing", id: "stripe" }] as never[],
      [] as never[],
    );
    const froms = d.rawEdges.filter((e) => e.kind === "uses-integration").map((e) => e.from);
    expect(froms).toEqual(["billing"]);
    // The NODE still exists — the integration is real even though one declarer is not in view.
    expect(d.rawNodes.some((n) => n.id === integrationNodeId("stripe"))).toBe(true);
  });

  /// A registered connector nobody declared still gets a node, with no edges. The maintainer's rule:
  /// if the integration exists, it is in the graph.
  it("shows a registered connector nobody declared, unconnected", () => {
    const d = build([] as never[], [{ id: "orphan", state: "never-checked" }] as never[]);
    const node = d.rawNodes.find((n) => n.id === integrationNodeId("orphan"));
    expect(node).toBeDefined();
    expect(node!.health).toBe("off");
    expect(d.rawEdges.filter((e) => e.kind === "uses-integration")).toEqual([]);
  });

  /// The wiring must not change what an existing caller gets — every prior positional argument keeps
  /// its meaning and a caller that passes none of the new ones is unaffected.
  it("is backwards compatible with every existing call shape", () => {
    const before = buildGlanceData(projects, [], [], [], [], [], []);
    const after = build();
    expect(after.rawNodes).toEqual(before.rawNodes);
    expect(after.rawEdges).toEqual(before.rawEdges);
  });
});

// #glance-architect-band + #architect-sits-with-the-projects + #architects-own-projects — the funnel's
// tier 1 on the L0 graph.
//
// The architect renders as a node IN the project network, edged to the projects it OWNS — not lifted
// into the fenced band the library and external-contract dimensions use. That band is for shared
// DEPENDENCIES a project consumes; an architect OWNS its projects, which is the opposite relationship,
// so it sits with them.
//
// #architects-own-projects narrowed the edge set: it used to be every architect to EVERY project (the
// first cut, because no ownership field existed), and the edge was called `created-by`. It is now
// `owned-by`, because an edge that can be REASSIGNED cannot claim to record who created the thing.
//
// The property that makes the placement safe is pinned below: the architect is a SINK (every `owned-by`
// edge points AT it), so it cannot close a cycle. Cycle regressions here have blanked the whole graph
// before (glance-planner-edge-isolation), so it is asserted rather than assumed.
import { describe, it, expect } from "vitest";
import { buildGlanceData, type ArchitectLite, type ProjectLite } from "@/features/glance/lib/glanceData";
import {
  buildGraph, isBandNode, isBandEdge, bandNodeMeta, architectNodeId, architectIdOfNode, ownedByEdgeId,
} from "@/features/glance/lib/glanceGraph";

const projects: ProjectLite[] = [
  { id: "app-a", name: "App A" },
  { id: "app-b", name: "App B" },
];
const architect: ArchitectLite[] = [{ id: "persona-architect", name: "Team architect" }];
const build = (p: ProjectLite[] = projects, a: ArchitectLite[] = architect) =>
  buildGlanceData(p, [], [], [], [], [], a);

describe("the architect node", () => {
  it("is emitted once per architect persona, namespaced so it cannot collide with a project key", () => {
    const d = build();
    const node = d.rawNodes.find((n) => n.id === architectNodeId("persona-architect"));
    expect(node).toBeTruthy();
    expect(node!.kind).toBe("architect");
    expect(node!.slug).toBe("Team architect");
    // A project key is a `[a-z0-9-]` slug with no colon, so the prefix is what makes this collision-proof.
    expect(node!.id).toContain(":");
    expect(architectIdOfNode(node!.id)).toBe("persona-architect");
  });

  it("is NOT a band node — it lays out WITH the projects (#architect-sits-with-the-projects)", () => {
    // The fenced band is for shared DEPENDENCIES (kits, algorithms, MCP servers), which is the wrong
    // relationship: an architect OWNS these projects rather than being consumed by them. Its
    // presentation row is kept, so a surface that wants the label/colour still has one.
    const d = build();
    const node = d.rawNodes.find((n) => n.id === architectNodeId("persona-architect"))!;
    expect(isBandNode(node)).toBe(false);
    expect(bandNodeMeta(node).bandLabel).toBe("ARCHITECTS");
  });

  it("adopts every UNASSIGNED project when it is the only architect, project as `from`", () => {
    // The sole-architect rule (#architects-own-projects): with one architect there is no choice to
    // make, so unassigned projects belong to it — which is what keeps a single-architect install
    // looking exactly as it did before ownership existed.
    const d = build();
    const edges = d.rawEdges.filter((e) => e.kind === "owned-by");
    expect(edges).toHaveLength(2);
    expect(edges.map((e) => e.from).sort()).toEqual(["app-a", "app-b"]);
    for (const e of edges) expect(e.to).toBe(architectNodeId("persona-architect"));
    expect(edges[0].id).toBe(ownedByEdgeId("app-a", "persona-architect"));
  });

  it("its edge is NOT a band edge — it routes in the project network like any other", () => {
    expect(isBandEdge("owned-by")).toBe(false);
  });
});

describe("the degenerate cases render rather than break", () => {
  it("no architect persona ⇒ no node and no edge (the graph is exactly as it was)", () => {
    const d = buildGlanceData(projects, [], [], [], [], [], []);
    expect(d.rawNodes.some((n) => n.kind === "architect")).toBe(false);
    expect(d.rawEdges.some((e) => e.kind === "owned-by")).toBe(false);
  });

  it("an architect with NO projects still renders — an orphan band node, not a crash", () => {
    const d = build([], architect);
    expect(d.rawNodes.filter((n) => n.kind === "architect")).toHaveLength(1);
    expect(d.rawEdges.filter((e) => e.kind === "owned-by")).toHaveLength(0);
    expect(() => buildGraph(d.rawNodes, d.rawEdges)).not.toThrow();
  });

  it("TWO architects each draw ONLY the projects assigned to them, ids staying distinct", () => {
    // Multiple architects are a first-class case (funnel-architect-front-door), so this must not
    // assume a singleton — and the band must not collapse them onto one node. This is the case
    // #architects-own-projects exists for: the old first cut drew 4 edges here (every architect to
    // every project), which said nothing about who owns what.
    const two: ArchitectLite[] = [{ id: "persona-architect", name: "A1" }, { id: "persona-architect-2", name: "A2" }];
    const owned: ProjectLite[] = [
      { id: "app-a", name: "App A", architect: "persona-architect" },
      { id: "app-b", name: "App B", architect: "persona-architect-2" },
    ];
    const d = build(owned, two);
    expect(d.rawNodes.filter((n) => n.kind === "architect")).toHaveLength(2);
    const edges = d.rawEdges.filter((e) => e.kind === "owned-by");
    expect(edges).toHaveLength(2);
    expect(edges.find((e) => e.from === "app-a")!.to).toBe(architectNodeId("persona-architect"));
    expect(edges.find((e) => e.from === "app-b")!.to).toBe(architectNodeId("persona-architect-2"));
  });

  it("leaves an UNASSIGNED project with no architect once there are several to choose from", () => {
    // The honest answer is none: adopting it under some architect would put a project under one that
    // never claimed it. The missing edge is the graph asking which.
    const two: ArchitectLite[] = [{ id: "persona-architect", name: "A1" }, { id: "persona-architect-2", name: "A2" }];
    const d = build([{ id: "app-a", name: "App A" }], two);
    expect(d.rawEdges.filter((e) => e.kind === "owned-by")).toHaveLength(0);
    expect(d.rawNodes.filter((n) => n.kind === "architect"), "both still render").toHaveLength(2);
  });

  it("treats an assignment to a VANISHED architect as unassigned, not as an edge to nothing", () => {
    // A persona can be deleted or re-roled out from under an assignment. A stale id is a MISSING
    // owner, so it falls through to the unassigned rules — here, the sole architect adopts it.
    const d = build([{ id: "app-a", name: "App A", architect: "persona-deleted" }], architect);
    const edges = d.rawEdges.filter((e) => e.kind === "owned-by");
    expect(edges).toHaveLength(1);
    expect(edges[0].to).toBe(architectNodeId("persona-architect"));
  });
});

describe("the band lift keeps the graph sound", () => {
  it("introduces no cycle — the architect is a SINK, and a cycle needs a path back out", () => {
    // The load-bearing safety property now that it is inside the project network. Cycle regressions
    // in this graph have blanked it before (glance-planner-edge-isolation), so this is asserted rather
    // than assumed.
    const d = build();
    const m = buildGraph(d.rawNodes, d.rawEdges);
    expect(m.cyclePairs).toHaveLength(0);
    expect(m.cycleNodeIds.size).toBe(0);
    expect(d.rawEdges.every((e) => e.kind !== "owned-by" || e.to === architectNodeId("persona-architect"))).toBe(true);
  });

  it("does not disturb the band for the dimensions that DO belong in it", () => {
    // Removing the architect must leave the kit/library/contract lift exactly as it was.
    const withKit = buildGlanceData(projects, [], [{ projectKey: "app-a", kitId: "react-ui" }], [{ id: "react-ui", name: "React UI" }], [], [], architect);
    const m = buildGraph(withKit.rawNodes, withKit.rawEdges);
    expect(m.bandZone, "the kit band still forms").toBeTruthy();
    const arch = m.nodes.find((n) => n.id === architectNodeId("persona-architect"))!;
    const kit = m.nodes.find((n) => n.kind === "kit")!;
    expect(isBandNode(kit)).toBe(true);
    expect(isBandNode(arch)).toBe(false);
  });
});

// #architect-node-expands-into-system-sessions — where the app-owned system sessions live.
//
// They used to be an L0 ROW to the architect's left, wired `architect → session`
// (#glance-reads-left-to-right-sessions-to-libraries). The maintainer's directive moved them INSIDE:
// the architect's node expands into them. So this file now pins two things at once — that L0 no longer
// draws them, and that the drill-in does — because a half-done move (removed from one place, not
// arriving in the other) is the failure that would leave the sessions unreachable from the graph
// entirely, with every "the node exists" test still green somewhere else.
//
// The left→right reading survives the move, minus one stop: architect → projects → libraries.
import { describe, it, expect } from "vitest";
import { buildGlanceData } from "@/features/glance/lib/glanceData";
import { buildArchitectFleetData } from "@/features/glance/lib/studioProject";
import { studioNetworkForArchitect, STUDIO_NETWORK_ID, ARCHITECT_NODE, BUILTIN_ORGS } from "@/features/teams";
import { buildGraph, architectNodeId, kitNodeId } from "@/features/glance/lib/glanceGraph";

const projects = [
  { id: "app-a", name: "App A" },
  { id: "app-b", name: "App B" },
];
const architect = [{ id: "persona-architect", name: "Team architect" }];
const build = (p = projects, a = architect) => buildGlanceData(p, [], [], [], [], [], a);

const studioTeam = () => BUILTIN_ORGS.find((t) => t.id === STUDIO_NETWORK_ID)!;

describe("L0 no longer carries the system sessions", () => {
  it("emits NO session node beside the architect", () => {
    const d = build();
    expect(d.rawNodes.filter((n) => n.kind === "session")).toHaveLength(0);
    expect(d.rawEdges.filter((e) => e.kind === "served-by")).toHaveLength(0);
  });

  it("still emits the ARCHITECT — it is the node that expands", () => {
    const d = build();
    const arch = d.rawNodes.find((n) => n.id === architectNodeId("persona-architect"));
    expect(arch).toBeTruthy();
    expect(arch!.kind).toBe("architect");
  });

  it("reads left→right end to end: architect → projects → libraries", () => {
    // The axis the L0 layout is FOR, minus the sessions stop. Still worth asserting as one chain: this
    // is what silently regresses if any remaining dimension's edge direction is flipped later.
    const d = buildGlanceData(
      projects, [], [{ projectKey: "app-a", kitId: "react-ui" }], [{ id: "react-ui", name: "React UI" }], [], [], architect,
    );
    const m = buildGraph(d.rawNodes, d.rawEdges);
    const x = (id: string) => m.nodes.find((n) => n.id === id)!.x;

    expect(x(architectNodeId("persona-architect"))).toBeLessThan(x("app-a"));
    expect(x("app-a")).toBeLessThan(x(kitNodeId("react-ui")));
    expect(x(kitNodeId("react-ui"))).toBeGreaterThanOrEqual(m.bandZone!.x0);
  });

  it("keeps the architect a SINK for provenance, with no cycle", () => {
    // `owned-by` points AT the architect. That is what stops a project↔architect cycle blanking the
    // graph (glance-planner-edge-isolation) — a cycle here takes the whole board down, so it is pinned
    // even though this item removed the edges that used to point the other way.
    const d = build();
    const m = buildGraph(d.rawNodes, d.rawEdges);
    const archId = architectNodeId("persona-architect");
    for (const e of m.edges.filter((x) => x.kind === "owned-by")) expect(e.to).toBe(archId);
    expect(m.cycleNodeIds.size).toBe(0);
  });
});

describe("the architect node expands into the sessions it commands", () => {
  it("narrows the Studio Network to the architect plus the sessions its verbs reach", () => {
    const t = studioNetworkForArchitect(studioTeam());
    const ids = t.positions.map((p) => p.nodeId);
    expect(ids[0]).toBe(ARCHITECT_NODE); // the hub comes first
    // #system-sessions-are-per-technology: the singular designer/librarian POSITIONS expand into one
    // node per technology, so the architect commands seven sessions rather than four.
    expect([...ids].sort()).toEqual([
      "architect",
      "designer-react", "designer-react-native",
      "integrator",
      "librarian-rust", "librarian-typescript",
      "sound-designer",
    ]);
  });

  it("excludes what no architect verb can reach — the planner, the libraries, the debugger", () => {
    // The drill-in's whole claim is that it shows what the architect COMMANDS. A node it cannot start,
    // stop or ask would be a promise the verbs do not keep.
    const ids = new Set(studioNetworkForArchitect(studioTeam()).positions.map((p) => p.nodeId));
    // The un-teched role ids are absent too: they are ROLES, not sessions, since the split.
    for (const absent of ["planner", "debugger", "teams", "components", "algorithms", "designer", "librarian"]) {
      expect(ids.has(absent), `${absent} must not be in the architect's drill-in`).toBe(false);
    }
  });

  it("wires the architect to every session it commands — the L0 relationship, moved inside", () => {
    const t = studioNetworkForArchitect(studioTeam());
    // SIX, not seven: `librarianPython` was the seventh and it named a technology with no record
    // anywhere in the repo (`the-studio-session-set-is-derived-not-declared`). The count is derived
    // from the node set asserted above rather than restated, so a technology arriving or leaving moves
    // both in one edit instead of leaving this number to be noticed.
    expect(t.relationships).toHaveLength(t.positions.length - 1);
    expect(t.relationships).toHaveLength(6);
    for (const r of t.relationships) {
      expect(r.from).toBe(ARCHITECT_NODE);
      expect(r.to).not.toBe(ARCHITECT_NODE);
    }
    // Every edge lands on a position that is actually present — a dangling edge is what narrowing a
    // graph gets wrong.
    const ids = new Set(t.positions.map((p) => p.nodeId));
    for (const r of t.relationships) expect(ids.has(r.to)).toBe(true);
  });

  it("builds a real drilled graph through the SAME team adapter", () => {
    const d = buildArchitectFleetData(BUILTIN_ORGS, []);
    expect(d).toBeTruthy();
    const ids = d!.rawNodes.map((n) => n.id).sort();
    expect(ids).toEqual([
      "architect",
      "designer-react", "designer-react-native",
      "integrator",
      "librarian-rust", "librarian-typescript",
      "sound-designer",
    ]);
    // One edge per commanded session — six since `librarianPython` left the set, and asserted against
    // the node count so the two cannot disagree.
    expect(d!.rawEdges).toHaveLength(ids.length - 1);
    expect(d!.rawEdges).toHaveLength(6);
  });

  it("keeps the node ids that make a session OPENABLE — the morph path is unchanged", async () => {
    // `studioPaneIdForNode` maps a Studio Network POSITION id to its fixed app-owned pane id. If the
    // drill-in renamed its nodes, every session in it would stop opening — the graph would draw and do
    // nothing, which is the worst version of this change landing.
    const { studioPaneIdForNode, studioNodeHome } = await import("@/features/glance/lib/studioProject");
    const d = buildArchitectFleetData(BUILTIN_ORGS, [])!;
    for (const n of d.rawNodes) {
      expect(studioPaneIdForNode(n.id), `${n.id} resolves to a pane`).toBeTruthy();
      expect(studioNodeHome(n.id)?.kind, `${n.id} opens as a morph`).toBe("morph");
    }
  });

  it("is a NO-OP on a team that is not the Studio Network", () => {
    // The transform is exported, so a caller could hand it a user's own team. Narrowing that to five
    // positions would silently destroy their graph.
    const other = BUILTIN_ORGS.find((t) => t.id !== STUDIO_NETWORK_ID);
    if (!other) return;
    expect(studioNetworkForArchitect(other)).toBe(other);
  });
});

// REPOSITORY GROUPS (#nodes-are-grouped-by-repository) — a fleet drill stacks its nodes into one
// full-width horizontal band per repo, so a project with two codebases reads as two groups rather than
// one interleaved mass.
//
// This groups data that already exists: every fleet stream carries a `repo` and `bsc plan fleet set`
// validates it as required, so nothing new has to be maintained for the grouping to stay true. The gap
// it closes was purely that `repo` never reached the graph — `GRawNode` had no field for it.
//
// A SEPARATE FILE rather than appended to the record's carried test: `bsc graph tests set` was removed
// from the binary (the verb is now `tests harvest <dir>`, which carries a COLOCATED file onto its node),
// and `glanceGraph` has no file to colocate with. An on-disk test is the pattern the other record-backed
// glance modules already use.
import { describe, it, expect } from "vitest";
import { buildGraph, NW, NH, type GRawNode, type GRawEdge } from "@/features/glance/lib/glanceGraph";
import { withStreamRepos } from "@/features/glance/lib/glanceFleet";

const n = (id: string, repo?: string): GRawNode =>
  ({ id, role: "service", health: "off", activity: "idle", ...(repo ? { repo } : {}) });

const BASE = "kevinthelago/base-studio-code";
const MOBILE = "kevinthelago/mobile-studio-code";

describe("buildGraph — repository groups", () => {
  it("draws one band per repo, labelled with the BARE repo name", () => {
    const m = buildGraph([n("a", BASE), n("b", MOBILE)], []);
    // The owner is identical on every band in a project, so repeating it costs width and distinguishes
    // nothing — the band carries the full `owner/name` as its identity and prints only the name.
    expect(m.repoBands?.map((b) => b.label)).toEqual(["base-studio-code", "mobile-studio-code"]);
    expect(m.repoBands?.map((b) => b.repo)).toEqual([BASE, MOBILE]);
  });

  it("orders bands by FIRST APPEARANCE, not alphabetically", () => {
    // The plan's own stream order is roughly build order and is meaningful; sorting by name would
    // reshuffle it for no reason a reader could see.
    const m = buildGraph([n("a", MOBILE), n("b", BASE)], []);
    expect(m.repoBands?.map((b) => b.repo)).toEqual([MOBILE, BASE]);
  });

  it("puts every node inside its own band's zone, and the bands never overlap", () => {
    const m = buildGraph([n("a", "o/one"), n("b", "o/one"), n("c", "o/two")], []);
    const band = (repo: string) => m.repoBands!.find((b) => b.repo === repo)!;
    for (const node of m.nodes) {
      const b = band(node.repo!);
      expect(node.y).toBeGreaterThanOrEqual(b.y0);
      expect(node.y + NH).toBeLessThanOrEqual(b.y1);
    }
    expect(band("o/one").y1).toBeLessThan(band("o/two").y0);
  });

  it("puts the bands to the RIGHT of everything ungrouped, not below it", () => {
    // The architect, the peer directors, the system sessions and the debug sessions are project-scoped,
    // not repo-scoped. Filing one under a repo would be an invented fact, so they keep their own zone.
    //
    // BESIDE, not beneath — the first attempt stacked the bands under the tier, which implied the repos
    // hang off the architect the way a debug session hangs off its spawner. They are not subordinate to
    // it: the tier is who is working, the bands are the codebases they work in.
    const m = buildGraph([n("architect"), n("a", "o/one"), n("b", "o/two")], []);
    const arch = m.nodes.find((x) => x.id === "architect")!;
    for (const b of m.repoBands!) expect(b.x0).toBeGreaterThan(arch.x + NW);
    for (const node of m.nodes.filter((x) => x.repo)) expect(node.x).toBeGreaterThan(arch.x + NW);
  });

  it("starts the first band level with the top of the graph, so it reads beside the tier", () => {
    const m = buildGraph([n("architect"), n("a", "o/one"), n("b", "o/two")], []);
    const top = Math.min(...m.nodes.map((x) => x.y));
    expect(m.repoBands![0].y0).toBeLessThanOrEqual(top);
  });

  it("draws NO bands for a single repo — one band around everything states nothing", () => {
    expect(buildGraph([n("a", "o/one"), n("b", "o/one")], []).repoBands).toBeUndefined();
  });

  it("leaves a graph with no repos at all untouched — the L0 project network", () => {
    // L0's nodes are PROJECTS and carry no repo, so the project map cannot regress through this path.
    const nodes: GRawNode[] = [n("core"), n("api"), n("web")];
    const edges: GRawEdge[] = [{ from: "web", to: "api", kind: "api" }, { from: "api", to: "core", kind: "data" }];
    const m = buildGraph(nodes, edges);
    expect(m.repoBands).toBeUndefined();
    expect(m.nodes.map((x) => [x.id, x.x, x.y])).toEqual(buildGraph(nodes, edges).nodes.map((x) => [x.id, x.x, x.y]));
  });

  it("WRAPS a wide layer instead of stacking it, so the band's height is bounded", () => {
    // THE REASON THIS EXISTS. A fleet's layers are lopsided — base-studio-code's 30 streams fall into 5
    // layers of which ONE holds 16 — and a layer laid out as a single column makes the band as tall as
    // its widest layer, not as tall as its depth. 16 rows is ~1630px for one band alone.
    const many = Array.from({ length: 16 }, (_, i) => n(`w${i}`, "o/one"));
    const m = buildGraph([n("architect"), ...many, n("z", "o/two")], []);
    const band = m.repoBands!.find((b) => b.repo === "o/one")!;
    const rows = new Set(m.nodes.filter((x) => x.repo === "o/one").map((x) => x.y));
    expect(rows.size).toBeLessThanOrEqual(6);          // wrapped, not stacked 16 deep
    expect(band.y1 - band.y0).toBeLessThan(16 * NH);   // and the band is bounded by that
  });

  it("keeps LAYER ORDER left→right — the dependency meaning the packing must not lose", () => {
    // Re-packing is allowed to change WHERE in a column a node sits; it is not allowed to reorder the
    // layers, because that is the only thing the drill says about what depends on what.
    const raw = [n("a", "o/one"), n("b", "o/one"), n("c", "o/two")];
    const edges: GRawEdge[] = [{ from: "b", to: "a", kind: "api" }];
    const m = buildGraph(raw, edges);
    const at = (id: string) => m.nodes.find((v) => v.id === id)!;
    expect(at("a").layer).toBeLessThan(at("b").layer);
    expect(at("a").x).toBeLessThan(at("b").x);
  });

  it("gives each band a real zone the canvas can wash, out to the world's right edge", () => {
    const m = buildGraph([n("architect"), n("a", "o/one"), n("b", "o/two")], []);
    for (const b of m.repoBands!) {
      expect(b.y1).toBeGreaterThan(b.y0);
      expect(m.worldW).toBeGreaterThan(b.x0);   // a non-negative width for the rect
    }
  });

  it("CENTRES the band stack on the director, not the top of the graph", () => {
    // Built from the graph's top edge (the only reference available while packing), then centred — the
    // director's row is what a reader actually relates the workers to. Without this the workers hang
    // off the tier's top corner and the taller the fleet, the more lopsided it reads.
    const m = buildGraph([
      n("director"), n("a", "o/one"), n("b", "o/one"), n("c", "o/two"), n("d", "o/two"),
    ], []);
    const dir = m.nodes.find((x) => x.id === "director")!;
    const bands = m.repoBands!;
    const mid = (bands[0].y0 + bands[bands.length - 1].y1) / 2;
    expect(Math.abs(mid - (dir.y + NH / 2))).toBeLessThan(2);
  });

  it("never centres the stack off the top of the world", () => {
    // `worldH` is measured from the nodes, so a negative y is unreachable rather than merely ugly. A
    // fleet taller than its tier centres as far as it can and then sits at the top.
    const many = Array.from({ length: 14 }, (_, i) => n(`w${i}`, "o/one"));
    const m = buildGraph([n("director"), ...many, n("z", "o/two")], []);
    for (const b of m.repoBands!) expect(b.y0).toBeGreaterThanOrEqual(0);
    for (const node of m.nodes) expect(node.y).toBeGreaterThanOrEqual(0);
  });
});

describe("withStreamRepos — the join from the plan to the graph", () => {
  const data = (ids: string[]) => ({
    rawNodes: ids.map((id) => n(id)),
    rawEdges: [],
    sample: false,
  });
  const fleet = (streams: { id: string; repo: string }[]) => ({ streams }) as never;

  it("stamps a stream's repo onto the node of the same id", () => {
    const out = withStreamRepos(data(["console", "mobile-shell"]), fleet([
      { id: "console", repo: BASE }, { id: "mobile-shell", repo: MOBILE },
    ]));
    expect(out.rawNodes.map((x) => x.repo)).toEqual([BASE, MOBILE]);
  });

  it("leaves a node with no matching stream alone — the director is not a stream", () => {
    const out = withStreamRepos(data(["director", "console"]), fleet([{ id: "console", repo: BASE }]));
    expect(out.rawNodes.find((x) => x.id === "director")!.repo).toBeUndefined();
  });

  it("treats an EMPTY repo as absent rather than grouping under a nameless band", () => {
    // `parseFleetFile` keeps a stream whose repo could not be resolved VISIBLE with an empty `repo`
    // (#2611). Banding on "" would draw a group with no name, which reads as a bug rather than as the
    // missing datum it actually is — ungrouped is the honest position.
    const out = withStreamRepos(data(["orphan"]), fleet([{ id: "orphan", repo: "  " }]));
    expect(out.rawNodes[0].repo).toBeUndefined();
    expect(buildGraph(out.rawNodes, []).repoBands).toBeUndefined();
  });

  it("is a no-op for a fleet with no repos at all, preserving the graph's own fields", () => {
    const before = data(["a"]);
    expect(withStreamRepos(before, fleet([]))).toBe(before);
  });
});

import { describe, it, expect } from "vitest";
import { partAroundPanel, PUSH_MARGIN, type MorphRect } from "@/features/glance/lib/glancePush";
import { NW, NH } from "@/features/glance/lib/glanceGraph";

// The open terminal panel (#2534/#2662) makes room by PARTING the graph into four rigid curtains (#2671,
// replacing the soft d3-force relaxation). The two properties that matter — and that the old soft force
// could NOT guarantee — are: (1) every neighbour clears the panel (no clipping), and (2) nodes keep their
// spacing (no node-into-node clipping). These are the regression tests for exactly those.
const RECT: MorphRect = { left: 500, top: 400, w: 760, h: 520 };

/** Does a node whose top-left is (x,y) still intersect the panel box? (true = clipping) */
const intersectsPanel = (x: number, y: number, r: MorphRect) =>
  !(x + NW <= r.left || x >= r.left + r.w || y + NH <= r.top || y >= r.top + r.h);

/** Apply a computed shift to a node's top-left. */
const shifted = (n: { id: string; x: number; y: number }, m: Map<string, { dx: number; dy: number }>) => {
  const d = m.get(n.id) ?? { dx: 0, dy: 0 };
  return { x: n.x + d.dx, y: n.y + d.dy };
};

describe("partAroundPanel (#2671 — rigid curtains make room for the open panel)", () => {
  it("leaves a node clear of the panel untouched", () => {
    expect(partAroundPanel([{ id: "far", x: 5000, y: 5000 }], RECT).has("far")).toBe(false);
  });

  it("excludes the grown node (it lives under the panel)", () => {
    const cx = RECT.left + RECT.w / 2 - NW / 2, cy = RECT.top + RECT.h / 2 - NH / 2;
    const m = partAroundPanel([{ id: "g", x: cx, y: cy }, { id: "a", x: cx - 120, y: cy }], RECT, "g");
    expect(m.has("g")).toBe(false);
  });

  it("pushes a node above the panel straight UP, not sideways", () => {
    // Centred horizontally, just above the top edge → the up curtain (vertical, dy<0, dx=0).
    const n = { id: "n", x: RECT.left + RECT.w / 2 - NW / 2, y: RECT.top - NH / 2 };
    const d = partAroundPanel([n], RECT).get("n")!;
    expect(d.dy).toBeLessThan(0);
    expect(d.dx).toBe(0);
  });

  it("pushes a node beside the panel straight OUT, not vertically", () => {
    // Centred vertically, near the right edge → the right curtain (horizontal, dx>0, dy=0).
    const n = { id: "n", x: RECT.left + RECT.w - NW / 2, y: RECT.top + RECT.h / 2 - NH / 2 };
    const d = partAroundPanel([n], RECT).get("n")!;
    expect(d.dx).toBeGreaterThan(0);
    expect(d.dy).toBe(0);
  });

  it("GUARANTEE: every overlapping node in a dense ring around the panel fully clears it (no clipping)", () => {
    // A grid of nodes blanketing the panel and its surroundings — the exact scenario that used to leave
    // residual overlap with the soft force.
    const nodes: { id: string; x: number; y: number }[] = [];
    for (let gx = -1; gx <= 9; gx++)
      for (let gy = -1; gy <= 7; gy++)
        nodes.push({ id: `${gx},${gy}`, x: RECT.left - 200 + gx * 150, y: RECT.top - 200 + gy * 130 });
    // Exclude whatever node sits nearest the panel centre (the grown one).
    const cx0 = RECT.left + RECT.w / 2, cy0 = RECT.top + RECT.h / 2;
    let ex = nodes[0].id, best = Infinity;
    for (const n of nodes) { const d = Math.hypot(n.x + NW / 2 - cx0, n.y + NH / 2 - cy0); if (d < best) { best = d; ex = n.id; } }

    const m = partAroundPanel(nodes, RECT, ex);
    for (const n of nodes) {
      if (n.id === ex) continue;
      const s = shifted(n, m);
      expect(intersectsPanel(s.x, s.y, RECT)).toBe(false); // fully cleared — the hard guarantee
    }
  });

  it("keeps a curtain RIGID: members keep their exact spacing (no node-into-node clipping)", () => {
    // Two nodes stacked directly above the panel — both land in the up curtain and MUST move together, or
    // the lower one would ram the upper one. A rigid block preserves their gap exactly.
    const cx = RECT.left + RECT.w / 2 - NW / 2;
    const lower = { id: "lower", x: cx, y: RECT.top - NH - 10 };       // overlaps → drives the shift
    const upper = { id: "upper", x: cx, y: lower.y - (NH + 40) };      // clear, but must ride along
    const m = partAroundPanel([lower, upper], RECT);
    const dLo = m.get("lower")!, dUp = m.get("upper")!;
    expect(dLo).toEqual(dUp);                                          // identical shift → rigid
    // Spacing before === spacing after.
    const gapBefore = lower.y - upper.y;
    const gapAfter = (lower.y + dLo.dy) - (upper.y + dUp.dy);
    expect(gapAfter).toBeCloseTo(gapBefore, 6);
    // And the overlapping member actually cleared.
    expect(intersectsPanel(lower.x + dLo.dx, lower.y + dLo.dy, RECT)).toBe(false);
  });

  it("clears the panel by at least the margin", () => {
    const n = { id: "n", x: RECT.left + RECT.w - NW / 2, y: RECT.top + RECT.h / 2 - NH / 2 };
    const d = partAroundPanel([n], RECT).get("n")!;
    const clearedLeftEdge = n.x + d.dx;                                // the node's new left edge
    expect(clearedLeftEdge).toBeGreaterThanOrEqual(RECT.left + RECT.w + PUSH_MARGIN - 1e-6);
  });

  it("is deterministic — the same rect yields the same shift (no jitter between frames)", () => {
    const nodes = [{ id: "a", x: 480, y: 420 }, { id: "b", x: 900, y: 660 }, { id: "c", x: 1300, y: 500 }];
    expect(partAroundPanel(nodes, RECT)).toEqual(partAroundPanel(nodes, RECT));
  });
});

// The L0 architect's click OPENS ITS MORPH — asserted by rendering Glance and clicking the node.
//
// WHY THIS IS A RENDER TEST. The morph pipeline gated on the drill in THREE places, and a fix to any
// one of them leaves the click just as dead:
//   1. `expandNode`      — `if (!drill) return;`
//   2. `isLiveAgent`     — `if (!drill) return false;` ahead of the studio branch
//   3. `openChats`       — `if (!drill || …) return [];`, which discards the stored placement
// Source-text assertions caught (1) and would have caught (2) and (3) individually, but nothing that
// reads one site at a time can see a COMPOSITION failure — and the existing
