// The INTEGRATION node projection (`an-integration-is-a-glance-node-with-a-real-signal`) — the join of
// DEMAND (`bsc project integrations`) and SUPPLY (`bsc data connector status`).
//
// Every assertion here is about a decision that could plausibly have gone the other way, and would have
// been wrong in a way the UI would not reveal. The most important of them is that health is DERIVED:
// the surface band was reverted for shipping nodes whose dot could never change, and this projection is
// what stops that repeating.
import { describe, it, expect } from "vitest";
import {
  integrationGraph,
  integrationHealth,
  declaringProjectCount,
  type DeclaredIntegrationRow,
  type ConnectorStatusRow,
} from "@/features/glance/lib/integrationNodes";
import { integrationNodeId, usesIntegrationEdgeId, isBandNode, isBandEdge } from "@/features/glance/lib/glanceGraph";

const DECLARED: DeclaredIntegrationRow[] = [
  { project: "storefront", id: "stripe", name: "Stripe", direction: "runtime" },
  { project: "storefront", id: "salesforce", name: "Salesforce", direction: "source" },
  { project: "billing", id: "stripe", name: "Stripe", direction: "runtime" },
];

describe("the integration projection", () => {
  it("gives every DECLARED integration a node, even with no connector built yet", () => {
    const { nodes } = integrationGraph(DECLARED, []);
    expect(nodes.map((n) => n.id)).toEqual([integrationNodeId("stripe"), integrationNodeId("salesforce")]);
    // Declared-but-unbuilt is the Integrator's QUEUE rendered — wanted, not yet built. It must show,
    // and it must not claim health nobody measured.
    for (const n of nodes) expect(n.health).toBe("off");
  });

  it("also gives a node to a REGISTERED connector nobody declared", () => {
    // The maintainer's rule: if the integration exists, it is in the graph. A connector registered
    // app-wide is real and still needs an owner, so it appears — with no edges, not hidden.
    const { nodes, edges } = integrationGraph([], [{ id: "orphan", state: "live" }]);
    expect(nodes.map((n) => n.id)).toEqual([integrationNodeId("orphan")]);
    expect(edges).toEqual([]);
  });

  it("draws one edge per DECLARATION, so one integration wanted by two projects has two", () => {
    const { edges } = integrationGraph(DECLARED, []);
    expect(edges).toHaveLength(3);
    expect(edges.map((e) => e.id)).toContain(usesIntegrationEdgeId("storefront", "stripe"));
    expect(edges.map((e) => e.id)).toContain(usesIntegrationEdgeId("billing", "stripe"));
    // ...and only ONE node for that integration, which is what makes the shared dependency visible.
    const { nodes } = integrationGraph(DECLARED, []);
    expect(nodes.filter((n) => n.id === integrationNodeId("stripe"))).toHaveLength(1);
  });

  it("renders in the fenced band, node and edge alike", () => {
    const { nodes, edges } = integrationGraph(DECLARED, []);
    for (const n of nodes) expect(isBandNode(n), n.id).toBe(true);
    for (const e of edges) expect(isBandEdge(e.kind), e.kind).toBe(true);
  });

  // ── the half that makes this band renderable at all ───────────────────────────────────────────────

  it("DERIVES health from the verdict — every state reachable by real work", () => {
    const states: [ConnectorStatusRow["state"], string][] = [
      ["never-checked", "off"],
      ["live", "healthy"],
      ["stale", "warning"],
      ["failing", "error"],
    ];
    for (const [state, health] of states) {
      const { nodes } = integrationGraph([{ project: "p", id: "x" }], [{ id: "x", state }]);
      expect(nodes[0].health, `${state} must render ${health}`).toBe(health);
    }
  });

  it("says NO SIGNAL rather than healthy for anything nobody has verified", () => {
    // Both halves of "unmeasured": never built, and built but never checked.
    expect(integrationHealth(undefined)).toBe("off");
    expect(integrationHealth("never-checked")).toBe("off");
    // ...and never accidentally green.
    expect(integrationHealth(undefined)).not.toBe("healthy");
  });

  it("treats a STALE verdict as a warning, not an error — unverified is not broken", () => {
    // A manifest edited since the check says nothing about the current shape. Reporting `error` would
    // claim a failure nobody observed; reporting `healthy` would carry a green light onto code nobody
    // ran. `warning` is the only honest one.
    expect(integrationHealth("stale")).toBe("warning");
  });

  it("carries the failure reason ONLY when the dot actually changed", () => {
    const failing = integrationGraph([{ project: "p", id: "x" }], [{ id: "x", state: "failing", error: "404 on /invoices" }]);
    expect(failing.nodes[0].reason).toBe("404 on /invoices");
    // A reason beside a healthy dot reads as a problem that is not there.
    const live = integrationGraph([{ project: "p", id: "x" }], [{ id: "x", state: "live", error: "stale text" }]);
    expect(live.nodes[0].reason).toBeUndefined();
  });

  // ── the edges that must NOT be drawn ──────────────────────────────────────────────────────────────

  it("drops an edge to a project that is not in the graph", () => {
    // A dangling edge is worse than a missing one: the layout would carry an id nothing renders.
    const { edges } = integrationGraph(DECLARED, [], ["storefront"]);
    expect(edges.map((e) => e.from)).toEqual(["storefront", "storefront"]);
  });

  it("keeps every edge when the caller does not say which projects exist", () => {
    // `undefined` means "I do not know the project set" — filtering to nothing there would silently
    // empty the band for a caller that simply had not been given the list.
    expect(integrationGraph(DECLARED, []).edges).toHaveLength(3);
  });

  it("never draws the same edge twice, however often a project repeats a declaration", () => {
    const dupes = [...DECLARED, { project: "storefront", id: "stripe" }];
    expect(integrationGraph(dupes, []).edges).toHaveLength(3);
  });

  it("counts the projects a broken integration would reach", () => {
    expect(declaringProjectCount(DECLARED, "stripe")).toBe(2);
    expect(declaringProjectCount(DECLARED, "salesforce")).toBe(1);
    expect(declaringProjectCount(DECLARED, "nope")).toBe(0);
  });

  it("prefers the declared display name, falling back to the id", () => {
    const { nodes } = integrationGraph([{ project: "p", id: "stripe", name: "Stripe" }, { project: "p", id: "bare" }], []);
    expect(nodes.map((n) => n.slug)).toEqual(["Stripe", "bare"]);
  });
});

// THE TECHNOLOGY TAB IS A LENS, NOT A PARTITION (`the-tab-is-a-lens-not-a-partition`) — the Components
// half of the guard, mirroring `features/algorithms/algorithmsLens.test.ts`.
//
// The claim a tab bar must never make is that technologies cannot cooperate. They can, and the model
// already says so: `@bsc/algorithms/fibonacci` is kit-less, so a React component resolves a TypeScript
// implementation across both pillar and technology (epic #3114, whose purpose was ending that siloing).
// Technology here is a CURATION scope — `studioScopeDirective` splits the designer per technology,
// governing who may WRITE a kit's components — and nothing more.
//
// What that obliges: scoping the rail to one technology must not make any kit, component or
// `composes` edge unreachable. That holds structurally rather than by luck, because a component's
// `composes` graph never leaves its kit and a kit belongs to exactly one technology — but "it holds
// today" is what a guard is for.
import { describe, it, expect } from "vitest";
import { groupKits, OTHER_BUCKET, type KitGroup, type KitTreeNode } from "@/features/designs/lib/kitGroups";
import type { Kit } from "@/features/designs/lib/model";

const kit = (id: string, tech?: string, style?: string): Kit =>
  ({ id, name: id, stack: "?", dot: "var(--accent)", ...(tech ? { tech } : {}), ...(style ? { style } : {}) }) as Kit;

/** Every kit id reachable by walking one technology group's subtree — what its tab can show. */
const kitsUnder = (node: KitTreeNode): string[] => {
  if (node.kind === "kit") return [node.kit.id];
  const own = node.kit ? [node.kit.id] : [];
  return [...own, ...node.children.flatMap(kitsUnder)];
};

const techGroups = (kits: Kit[]): KitGroup[] =>
  groupKits(kits).filter((n): n is KitGroup => n.kind === "group");

describe("the technology tab is a lens over the component library", () => {
  it("every kit is reachable from exactly one technology tab", () => {
    // Total and unambiguous. A kit under no tab is invisible in the UI; a kit under two is two copies
    // of one record, and edits to it would depend on which tab you happened to be on.
    const kits = [
      kit("studio", "react", "studio"),
      kit("fleet", "react", "studio"),
      kit("viz", "react", "data-viz"),
      kit("mobile", "react-native", "mobile"),
      kit("bare"), // no tech at all
    ];
    const seen = new Map<string, number>();
    for (const g of techGroups(kits)) {
      for (const id of g.children.flatMap(kitsUnder)) seen.set(id, (seen.get(id) ?? 0) + 1);
    }
    expect([...seen.keys()].sort()).toEqual(["bare", "fleet", "mobile", "studio", "viz"]);
    expect([...seen].filter(([, n]) => n > 1)).toEqual([]);
  });

  it("a kit with no technology still gets a tab rather than disappearing", () => {
    // The `other` bucket was a trailing rail GROUP; as a tab it must still exist, or an imported or
    // hand-authored kit that never set `tech` becomes unreachable — silently, since nothing errors.
    const groups = techGroups([kit("studio", "react", "studio"), kit("bare")]);
    const other = groups.find((g) => g.key === `tech:${OTHER_BUCKET}`);
    expect(other, "a kit with no `tech` must still have a tab").toBeTruthy();
    expect(other!.children.flatMap(kitsUnder)).toEqual(["bare"]);
    // …and it sorts LAST, so the real technologies lead.
    expect(groups[groups.length - 1].key).toBe(`tech:${OTHER_BUCKET}`);
  });

  it("scoping to one technology never splits a kit across tabs", () => {
    // The edge case that would sever something real: a kit's components compose only within that kit,
    // so a kit landing whole on one tab is what makes "no edge is lost" structural here rather than
    // coincidental. Two technologies sharing a STYLE name must not merge into one group.
    const groups = techGroups([kit("a", "react", "studio"), kit("b", "react-native", "studio")]);
    expect(groups.map((g) => g.key)).toEqual(["tech:react", "tech:react-native"]);
    expect(groups[0].children.flatMap(kitsUnder)).toEqual(["a"]);
    expect(groups[1].children.flatMap(kitsUnder)).toEqual(["b"]);
  });
});

// Tests for GENERIC rendering of general nodes (#3494, slice 3b of the keystone #3484).
//
// The legacy `kind` path is covered by the existing KitRenderer tests, which are deliberately
// UNMODIFIED by this slice — that they still pass is the parity evidence for the two production
// surfaces (SessionsBehaviorCard, TransformationsBody). These tests cover only the new path.
import { describe, it, expect, vi } from "vitest";
import { render, screen } from "@testing-library/react";
import { KitRenderer } from "@/shared/ui/spec/KitRenderer";
import { validateGeneralNode, type GeneralNode } from "@/shared/ui/spec/generalNode";
import { UI_KIT } from "@/shared/ui/manifest";

describe("generic rendering through the registry (#3494)", () => {
  it("renders a primitive resolved by `type`, not by a per-primitive branch", () => {
    render(<KitRenderer node={{ type: "Text", children: "hello world" } as GeneralNode} />);
    expect(screen.getByText("hello world")).toBeTruthy();
  });

  it("renders nested children recursively", () => {
    const tree: GeneralNode = {
      type: "Stack",
      children: [
        { type: "Text", children: "first" },
        { type: "Text", children: "second" },
      ],
    };
    render(<KitRenderer node={tree} />);
    expect(screen.getByText("first")).toBeTruthy();
    expect(screen.getByText("second")).toBeTruthy();
  });

  it("renders MANY different primitives with no renderer edit — the point of the slice", () => {
    // If the renderer were still branching per primitive, most of these would come back blank. Picking
    // them from the manifest (rather than a hardcoded list) is what makes this a genericity test.
    const simple = UI_KIT.filter((p) =>
      ["Text", "Chip", "Button", "Code", "SectionLabel"].includes(p.name),
    );
    expect(simple.length).toBeGreaterThan(3);
    for (const p of simple) {
      const { unmount } = render(
        <KitRenderer node={{ type: p.name, children: `body-${p.name}` } as GeneralNode} />,
      );
      expect(screen.getByText(`body-${p.name}`), `${p.name} rendered nothing`).toBeTruthy();
      unmount();
    }
  });
});

describe("bindings on the generic path (#3494)", () => {
  it("resolves a DECLARED function prop as an ACTION NAME against the host callbacks", () => {
    // The 3a contract: a data tree binds handlers by NAME; it can never carry a function. The renderer
    // knows WHICH props are handlers from the manifest's declared `type: "function"` — never by
    // guessing from the prop's name.
    const onClick = vi.fn();
    const { container } = render(
      <KitRenderer
        node={{ type: "Toggle", props: { on: true, onClick: "doTheThing" } } as GeneralNode}
        on={{ doTheThing: onClick }}
      />,
    );
    (container.firstElementChild as HTMLElement).click();
    expect(onClick).toHaveBeenCalledOnce();
  });

  it("an unknown action name is a no-op, not a crash", () => {
    // Same tolerance the legacy `button` branch has always had — a missing host callback must not
    // take down a surface that is otherwise fine.
    const { container } = render(
      <KitRenderer
        node={{ type: "Toggle", props: { on: true, onClick: "missing" } } as GeneralNode}
        on={{}}
      />,
    );
    expect(() => (container.firstElementChild as HTMLElement).click()).not.toThrow();
  });

  it("binds a handler on a PASSTHROUGH primitive via the actions map (#3496)", () => {
    // This closes the gap #3494 recorded. `Button` is passthrough and does NOT declare `onClick`, so
    // the manifest cannot tell the renderer that prop is a handler — the actions map states it
    // outright instead of the renderer guessing from the prop's name.
    const onClick = vi.fn();
    render(
      <KitRenderer
        node={{ type: "Button", children: "Go", actions: { onClick: "doTheThing" } } as GeneralNode}
        on={{ doTheThing: onClick }}
      />,
    );
    screen.getByText("Go").click();
    expect(onClick).toHaveBeenCalledOnce();
  });

  it("the actions map WINS over a declared function prop of the same name (#3496)", () => {
    // Documented precedence: the explicit map beats the implicit declared-type path. Asserted rather
    // than left to chance, because "which one wins" is exactly what an author needs to be able to rely
    // on when they reach for the map to disambiguate.
    const viaProp = vi.fn();
    const viaMap = vi.fn();
    const { container } = render(
      <KitRenderer
        node={{ type: "Toggle", props: { on: true, onClick: "fromProp" }, actions: { onClick: "fromMap" } } as GeneralNode}
        on={{ fromProp: viaProp, fromMap: viaMap }}
      />,
    );
    (container.firstElementChild as HTMLElement).click();
    expect(viaMap).toHaveBeenCalledOnce();
    expect(viaProp).not.toHaveBeenCalled();
  });

  it("an unknown action name in the map is a no-op, not a crash", () => {
    const { container } = render(
      <KitRenderer
        node={{ type: "Button", children: "Go", actions: { onClick: "missing" } } as GeneralNode}
        on={{}}
      />,
    );
    expect(() => (container.querySelector("button") as HTMLElement).click()).not.toThrow();
  });
});

describe("failure is visible, never blank (#3494)", () => {
  it("an unresolvable type renders a stated error rather than nothing", () => {
    // A silent blank in a data-driven UI is indistinguishable from "the data said render nothing" —
    // precisely the failure mode this migration must not introduce.
    render(<KitRenderer node={{ type: "NotAPrimitive" } as unknown as GeneralNode} />);
    expect(screen.getByText(/unknown primitive "NotAPrimitive"/)).toBeTruthy();
  });

  it("does not throw on a bad node — one bad node must not white-screen a surface", () => {
    expect(() =>
      render(<KitRenderer node={{ type: "AlsoNotReal" } as unknown as GeneralNode} />),
    ).not.toThrow();
  });
});

// #3500 — the legacy `kind` vocabulary is GONE. A tree carrying one is no longer a second dialect the
// renderer understands; it is simply an invalid node, and must fail the way any invalid node does:
// visibly, without throwing. (The interop suite that used to live here tested a coexistence that no
// longer exists, so keeping it would have asserted the opposite of the contract.)
describe("the retired vocabulary is not silently accepted (#3500)", () => {
  it("a node carrying the legacy `kind` discriminant does not validate", () => {
    const legacy = { kind: "text", text: "legacy" } as unknown as GeneralNode;
    expect(validateGeneralNode(legacy)).toEqual(['$: missing string "type"']);
  });

  it("a legacy node nested in a general tree does not validate either", () => {
    const tree = {
      type: "Stack",
      children: [{ kind: "text", text: "legacy child" }],
    } as unknown as GeneralNode;
    // The `children` slot rejects it as a non-node, and the walk does not descend into it — one clear
    // error at the container, not a confusing cascade from inside a node that was never valid.
    expect(validateGeneralNode(tree)).toEqual(["$.props.children: expected nodes or text"]);
  });

  it("rendering one shows a visible error instead of silently dropping it", () => {
    const legacy = { kind: "text", text: "legacy" } as unknown as GeneralNode;
    render(<KitRenderer node={legacy} />);
    expect(screen.getByText(/unknown primitive/)).toBeTruthy();
  });
});

// `bsc-agent`'s native permission doc, captured from the LIVE TypeScript so the Rust rendering can be
// proved equal.
//
// This doc IS the gate on the model-agnostic harness. There is no `.claude/settings.json` on that path:
// `crates/bsc-agent/src/main.rs` calls `Permissions::from_env()` and enforces the result on every tool
// call, deserializing exactly `deny_tools` / `deny_bash` / `write_globs`. So a Rust runtime enforces,
// per tool call, a permission document computed in a renderer.
//
// Two details a port is most likely to drop, both covered below:
//   * The USER'S GLOBAL DENYLIST rides in here rather than through a settings file, because bsc-agent
//     has none. It is trimmed and de-duplicated against the role denies.
//   * The catastrophic floor (sudo / rm -rf / force-push) is NOT in this doc — it is always-on inside
//     the runtime via `bsc_util::dangerous`, so an empty doc still cannot run those.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/bscAgentPerms.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { roleCapability, bscAgentPerms, type SessionRole } from "@/shared/lib/session/sessionRoles";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/bscAgentPerms.fixtures.json");

const ROLES: SessionRole[] = [
  "planner", "worker", "director", "triage", "tester", "reviewer",
  "issuer", "juror", "documentor", "designer", "architect", "librarian", "sound-designer", "marketer",
] as SessionRole[];

const PUSH_GRANT = ["git push", "gh pr create"];

type Case = { label: string; role: string | null; globs?: string[]; granted?: string[]; extraDeny?: string[]; surfaces?: string[] };

/** A stand-in `bsc surface list` catalog. Small and FIXED rather than the real one: the complement is
 *  what a role did NOT declare, so a live catalog would silently rewrite every expectation here each
 *  time a surface is added. `plan`/`skill` are surfaces no studio role declares; `ui` is one the
 *  designer does, so the pair proves the complement rather than a blanket deny. */
const CATALOG = ["plan", "skill", "ui"];

const SUBJECTS: Case[] = [
  // A role-less ad-hoc console: only the user's denylist applies.
  { label: "NO capability — an ad-hoc bsc-agent console", role: null },
  { label: "NO capability, but the user has a denylist", role: null, extraDeny: ["curl", "wget"] },

  ...ROLES.map((r) => ({ label: `role ${r}`, role: r })),

  // The flow reconciliation (#304), mirroring the Claude path.
  { label: "worker + the flow's push grant", role: "worker", granted: PUSH_GRANT },
  { label: "director + the flow's push grant", role: "director", granted: PUSH_GRANT },
  { label: "designer + a push grant it cannot use", role: "designer", granted: PUSH_GRANT },

  // The user's global denylist — the half that has no settings file to ride in on.
  { label: "worker + user denylist", role: "worker", extraDeny: ["curl", "npm publish"] },
  { label: "user denylist entries are TRIMMED", role: "worker", extraDeny: ["  curl  ", "npm publish"] },
  { label: "empty and whitespace-only denylist entries are dropped", role: "worker", extraDeny: ["", "   ", "curl"] },
  { label: "a user deny DUPLICATING a role deny is de-duplicated", role: "worker", extraDeny: ["gh pr merge"] },
  { label: "user denylist plus a push grant together", role: "worker", granted: PUSH_GRANT, extraDeny: ["curl"] },

  // write_globs: code:write takes its own, a carve-out keeps its scoped set, everything else gets none.
  { label: "worker with own write globs", role: "worker", globs: ["src/**", "docs/**"] },
  { label: "designer — code:none WITH a carve-out keeps its globs", role: "designer" },
  { label: "documentor — the doc-globs carve-out", role: "documentor" },
  { label: "triage — code:none with NO carve-out gets no globs and loses the write tools", role: "triage" },
  { label: "triage handed globs it has no carve-out for", role: "triage", globs: ["src/**"] },

  // The persona SURFACE COMPLEMENT (`a-bsc-agent-session-is-denied-less-than-the-same-role-on-claude`).
  // It used to be absent here entirely, so a bsc-agent session was denied strictly less than the same
  // role on Claude. An EMPTY catalog still denies nothing extra, which is the fail-open the launch
  // relies on when the catalog poll has not resolved.
  { label: "designer + the surface catalog — undeclared surfaces are denied", role: "designer", surfaces: CATALOG },
  { label: "designer + an EMPTY catalog denies no surface", role: "designer", surfaces: [] },
  { label: "worker + the surface catalog", role: "worker", surfaces: CATALOG },
];

const render = (c: Case) => {
  const cap = c.role ? roleCapability(c.role as SessionRole, c.globs?.length ? { writeGlobs: c.globs } : {}) ?? null : null;
  return { cap, perms: bscAgentPerms(cap, c.granted ?? [], c.extraDeny ?? [], c.surfaces ?? []) };
};

describe("bscAgentPerms fixtures", () => {
  it("captures the rendered doc over every role and every input", () => {
    const cases = SUBJECTS.map((c) => {
      const { cap, perms } = render(c);
      return {
        label: c.label,
        role: c.role,
        writeGlobs: c.globs ?? [],
        granted: c.granted ?? [],
        extraDenyBash: c.extraDeny ?? [],
        // The catalog the complement was computed against — emitted so the Rust parity test drives
        // the SAME input rather than assuming an empty one, which is the assumption that hid this bug.
        activeSurfaces: c.surfaces ?? [],
        capability: cap,
        perms,
      };
    });
    const next = { note: "GENERATED from @/shared/lib/session/sessionRoles bscAgentPerms — do not hand-edit; see the .gen.test.ts", cases };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("is non-vacuous: every branch of all three fields actually occurs", () => {
    const rendered = SUBJECTS.map(render);
    expect(rendered.filter((r) => r.perms.deny_tools.length > 0).length, "no case denied the write tools").toBeGreaterThan(0);
    expect(rendered.filter((r) => r.perms.deny_tools.length === 0).length, "no case KEPT the write tools").toBeGreaterThan(0);
    expect(rendered.filter((r) => r.perms.write_globs.length > 0).length, "no case produced write globs").toBeGreaterThan(0);
    expect(rendered.filter((r) => r.perms.deny_bash.length > 0).length, "no case produced bash denies").toBeGreaterThan(0);
  });

  it("the catastrophic floor is NOT in the doc — it lives in the runtime", () => {
    // If it were rendered here, an empty doc would look insufficient and a future edit might "restore"
    // it, hiding that the real floor is `bsc_util::dangerous` inside bsc-agent and cannot be dropped.
    for (const { perms } of SUBJECTS.map(render)) {
      expect(perms.deny_bash.some((d) => d.includes("sudo") || d.includes("rm -rf"))).toBe(false);
    }
  });

  it("a push grant lifts ONLY what the role actually denied", () => {
    const worker = roleCapability("worker" as SessionRole, {})!;
    const plain = bscAgentPerms(worker).deny_bash;
    const granted = bscAgentPerms(worker, PUSH_GRANT).deny_bash;
    const lifted = plain.filter((d) => !granted.includes(d));
    expect(lifted, "a worker is git:write, so only the gh half was ever denied").toEqual(["gh pr create"]);
  });
});

// EVERY PACKAGED APP RECORD MUST SURVIVE ITS OWN LOAD PROJECTION — `seed === load(push(seed))` (#2514).
//
// `SEED_COMPONENTS` stamps each packaged JSON with `stampSeedHash(projectComponent(raw))`. If the raw JSON
// carries a field the projection normalizes — an empty array where the projection wants it absent, a key it
// drops — then the stamped hash describes content the store will never reproduce. The record then reads as
// PRISTINE-BUT-CHANGED on every single boot: `reconcileSeed` reports `refreshed`, `hydrateComponents`
// re-pushes it, and the same write repeats forever.
//
// Nothing else notices. The app works, the record renders, and the churn is invisible unless a test happens
// to assert an empty reconcile — which is exactly how this was found: promoting two records made three
// unrelated `store.test.ts` cases fail, and the failure named `console-pane-menu` rather than the field that
// broke it. This test names the field.
import { describe, it, expect } from "vitest";
import type { ComponentRecord } from "@/features/designs/lib/model";
import { projectComponent } from "@/features/designs/lib/componentBridge";
import { seedHashOf } from "@/features/designs/lib/seedRefresh";

const raw = import.meta.glob<Partial<ComponentRecord>>("@data/components/app/**/*.json", {
  eager: true,
  import: "default",
});

describe("packaged app records round-trip through the load projection (#2514)", () => {
  const paths = Object.keys(raw).sort();

  it("has records to check", () => {
    expect(paths.length).toBeGreaterThan(20);
  });

  it("no id appears twice — the glob is FLAT, so folders do not namespace", () => {
    // `SEED_COMPONENTS` globs `app/**` and keys by `id`, so two files under different folders sharing an
    // id are two records with one identity. `reconcileSeed` then reports that id as pristine-but-changed
    // on every boot and re-pushes it, forever. The app keeps working, which is why it took three unrelated
    // `store.test.ts` failures to surface — and those named the record, not the duplication.
    const seen = new Map<string, string[]>();
    for (const p of paths) {
      const id = raw[p]?.id;
      if (!id) continue;
      seen.set(id, [...(seen.get(id) ?? []), p]);
    }
    const dupes = [...seen].filter(([, ps]) => ps.length > 1).map(([id, ps]) => `${id}: ${ps.join(" · ")}`);
    expect(dupes).toEqual([]);
  });

  it("projecting a packaged record TWICE is the same as projecting it once", () => {
    // The round-trip in the form this test can see without a store: the projection must be idempotent,
    // or the hash stamped over `project(raw)` cannot survive `project(load(...))`.
    const unstable: string[] = [];
    for (const p of paths) {
      const once = projectComponent(raw[p]);
      const twice = projectComponent({ ...once });
      if (seedHashOf(once) !== seedHashOf(twice)) {
        const a = once as unknown as Record<string, unknown>;
        const b = twice as unknown as Record<string, unknown>;
        const fields = [...new Set([...Object.keys(a), ...Object.keys(b)])].filter(
          (k) => JSON.stringify(a[k]) !== JSON.stringify(b[k]),
        );
        unstable.push(`${p.split("/").pop()} — differs on: ${fields.join(", ") || "(field set)"}`);
      }
    }
    expect(unstable).toEqual([]);
  });

  it("a packaged record carries only fields the projection preserves", () => {
    // A field the projection DROPS is the other half of the same bug: it is in the JSON, absent from the
    // stamped record, and every reader after that disagrees with the file about what the record is.
    const dropped: string[] = [];
    for (const p of paths) {
      const projected = projectComponent(raw[p]) as unknown as Record<string, unknown>;
      const missing = Object.keys(raw[p] as Record<string, unknown>).filter((k) => !(k in projected));
      if (missing.length) dropped.push(`${p.split("/").pop()} — ${missing.join(", ")}`);
    }
    expect(dropped).toEqual([]);
  });
});

// A PERSONA'S LOCAL MODEL MUST REACH THE LAUNCH (`a-personas-local-model-reaches-the-launch`).
//
// MAINTAINER 2026-09-02: "these nodes are still being opened into a claude cli sessions."
//
// The persona carried `qwen3.5:35b-a3b` and the terminal ran Claude. Two independent places dropped it,
// and BOTH failed silently — `ClaudeCodeAdapter.model_flag` maps the known tiers and ignores anything
// else, so a local name handed to Claude Code produces no error at all, just the wrong harness.
import { describe, it, expect } from "vitest";
import { providerForModel } from "@/app/console/lib/models";
import { streamPaneWiring } from "@/store/slices/projects";
// A cross-feature `import type` (allowed by #1545); `AgentStream` is not on the planner barrel — the
// same import `GlanceWorkspace` itself uses for `FleetPlan`.
import type { AgentStream } from "@/features/planner/fleet/planFleet";

const stream = (over: Partial<AgentStream> = {}): AgentStream =>
  ({ id: "s", name: "s", repo: "acme/r", owns: [], ...over }) as AgentStream;

describe("the harness a model implies", () => {
  it("sends a non-tier model to bsc-agent, and a tier to the default", () => {
    expect(providerForModel("qwen3.5:35b-a3b")).toBe("bsc-agent");
    expect(providerForModel("sonnet-4.5")).toBeUndefined();
    // unset is a real state — NOT "claude"
    expect(providerForModel(undefined)).toBeUndefined();
    expect(providerForModel("")).toBeUndefined();
  });
});

describe("a persona's model survives streamPaneWiring", () => {
  it("adopts a LOCAL model from the persona and derives bsc-agent", () => {
    // The regression: this used to adopt `persona.model` only when it was a Claude tier, so a local
    // name was dropped here and the session launched on Claude Code with nothing reporting it.
    const w = streamPaneWiring(stream(), { role: "worker", model: "qwen3.5:35b-a3b" });
    expect(w.model).toBe("qwen3.5:35b-a3b");
