// `discovery-chooses-the-model` — the PROJECT's level of the model precedence chain.
//
// The chain, nearest first:
//     a fleet stream's own model  (bsc plan fleet model)
//       > a team placement's      (bsc teams model)          the NODE
//       > the project's own       (bsc plan classify.model)  DISCOVERY
//       > the persona's default   (bsc persona model)
//       > the harness's own default (no --model at all)
//
// Every one of these is tested as a SEPARATION rather than in isolation: a level only means anything
// relative to the ones on either side of it, and a test that sets one level with the others empty
// passes for a chain assembled in any order.
import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
import type { AgentStream, FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

const NAME = "discovery-model-test";
const KEY = sanitizeProjectKey(NAME);
const HUB = "/home/user/.base-studio-code/projects/discovery-model-test";
const PANE = `${KEY}:curator`;

const fleet = (streams: AgentStream[]): FleetPlan => ({ recommended: 1, reasoning: "t", streams, director: { enabled: false } });
const persona: Persona = { id: "persona-curator", name: "Curator", blurb: "", role: "curator", startPrompt: "curate", skills: [] };
const stream: AgentStream = { id: "curator", name: "Curator", repo: "", owns: [], issues: [], dependsOn: [], persona: "persona-curator" };

/** Seat the store with one persona and one project classification, then launch. */
function launch(opts: { personaModel?: string; projectModel?: string; streamModel?: string }) {
  useAppStore.setState({
    tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, paneModels: {},
    paneProviders: {},
    personas: [{ ...persona, ...(opts.personaModel ? { model: opts.personaModel } : {}) }],
    planClassification: opts.projectModel ? { [KEY]: { model: opts.projectModel } } : {},
  });
  useAppStore.getState().fleetStartProject(
    NAME,
    fleet([{ ...stream, ...(opts.streamModel ? { model: opts.streamModel } : {}) }]),
    KEY,
    { hubPath: HUB },
  );
  return useAppStore.getState();
}

describe("the project's discovery model", () => {
  beforeEach(() => {
    useAppStore.setState({ tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, personas: [persona], planClassification: {} });
  });

  it("beats the persona's default — a global identity is further away than this project", () => {
    // THE BITE. Before this, `classify.model` reached no launch at all: the architect could record the
    // decision and every session went on resolving `sess.model ?? persona.model`, so the project ran
    // on the persona's tier while the classification said otherwise. A recorded decision that changes
    // nothing is worse than an absent one — it reads as settled.
    expect(launch({ personaModel: "opus-4.5", projectModel: "haiku-4.5" }).paneModels[PANE]).toBe("haiku-4.5");
  });

  it("LOSES to the stream's own model, which already carries the node's placement", () => {
    // The nearer pair. `teamRoleStreams` puts a team placement's model on the stream, so beating
    // `sess.model` here would make a per-NODE choice unreachable — the thing
    // `a-node-cannot-carry-a-local-model` had just finished making possible.
    expect(launch({ personaModel: "opus-4.5", projectModel: "haiku-4.5", streamModel: "sonnet-4.5" }).paneModels[PANE])
      .toBe("sonnet-4.5");
  });

  it("applies when the persona has no default of its own", () => {
    expect(launch({ projectModel: "haiku-4.5" }).paneModels[PANE]).toBe("haiku-4.5");
  });

  it("falls through to the persona when the project made no choice", () => {
    // Non-regression for every project classified before this axis existed: an absent project model
    // must be indistinguishable from the axis not existing.
    expect(launch({ personaModel: "opus-4.5" }).paneModels[PANE]).toBe("opus-4.5");
  });

  it("leaves the pane with NO model when no level names one", () => {
    // An entry here would be the app choosing a tier on the user's behalf; the harness's own default
    // is what "nobody decided" has to mean.
    expect(launch({}).paneModels[PANE]).toBeUndefined();
  });

  it("routes the whole project to bsc-agent when discovery chose a LOCAL model", () => {
    // The point of the axis for today's work: ONE write moves a project onto the local runtime,
    // rather than one write per node. Asserting only `paneModels` would pass with the session still
    // launching Claude Code.
    const s = launch({ personaModel: "opus-4.5", projectModel: "qwen3.5:35b-a3b" });
    expect(s.paneModels[PANE]).toBe("qwen3.5:35b-a3b");
    expect(s.paneProviders[PANE]).toBe("bsc-agent");
  });

  it("lets ONE node stay on Claude inside a locally-classified project", () => {
    // The direction that proves the levels are ordered rather than merged: the project says local,
    // the stream (a node's placement, carried by `teamRoleStreams`) says a tier, and the tier wins.
    const s = launch({ projectModel: "qwen3.5:35b-a3b", streamModel: "opus-4.5" });
    expect(s.paneModels[PANE]).toBe("opus-4.5");
    expect(s.paneProviders[PANE]).not.toBe("bsc-agent");
  });
});

// Team role-actor hub launch (#3103): a repo-less stream — the shape `teamRoleStreams` emits for a
// team's curator/documentor/… — must launch at the project HUB (like the director), NOT in a per-repo
// worktree, while its persona still drives the pane role. Workers are unaffected. Verified through
// fleetStartProject without a real git worktree or Tauri process (mirrors loadStream.test.ts).

import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
import type { AgentStream, FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

const NAME = "team-launch-test";
const KEY = sanitizeProjectKey(NAME);
const HUB = "/home/user/.base-studio-code/projects/team-launch-test";

const fleet = (streams: AgentStream[]): FleetPlan => ({ recommended: 1, reasoning: "t", streams, director: { enabled: false } });

const curatorPersona: Persona = { id: "persona-curator", name: "Curator", blurb: "", role: "curator", startPrompt: "harvest the library", skills: [] };

// A repo-less role-actor stream (exactly what teamRoleStreams produces).
const curatorStream: AgentStream = { id: "curator", name: "Curator", repo: "", owns: [], issues: [], dependsOn: [], persona: "persona-curator" };
const workerStream: AgentStream = { id: "engine", name: "Engine", repo: "org/app", owns: ["src/**"], issues: ["#1"], dependsOn: [] };

describe("team role-actor hub launch (#3103)", () => {
  beforeEach(() => {
    useAppStore.setState({ tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, personas: [curatorPersona] });
  });

  it("routes a repo-less role-actor to the HUB cwd and its persona role; the worker keeps its worktree", () => {
    useAppStore.getState().fleetStartProject(NAME, fleet([workerStream, curatorStream]), KEY, {
      hubPath: HUB, worktreePaths: { engine: "/wt/engine" },
    });
    const s = useAppStore.getState();
    const curatorPane = `${KEY}:curator`;
    expect(s.paneRoles[curatorPane]).toBe("curator");   // persona resolves the role
    expect(s.paneCwds[curatorPane]).toBe(HUB);           // hub-scoped, NOT a worktree path
    // The worker is unaffected — worktree cwd + worker role.
    const workerPane = `${KEY}:engine`;
    expect(s.paneRoles[workerPane]).toBe("worker");
    expect(s.paneCwds[workerPane]).toBe("/wt/engine");
  });

  // ── the model a role-actor launches on (a-model-cannot-be-chosen-from-the-command-surface) ────
  //
  // End to end, because the value crosses three hands — the team record, `teamRoleStreams`, and this
  // launch — and the middle one is the only place a unit test would otherwise see it.

  it("launches a role-actor on its placement's model, then the persona's, then the harness default", () => {
    // A persona carrying its own default, placed once. The stream shape is what `teamRoleStreams`
    // emits: the placement's override (when there is one) lands on `model`.
    useAppStore.setState({
      tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, paneModels: {},
      personas: [{ ...curatorPersona, model: "opus-4.5" }],
    });
    useAppStore.getState().fleetStartProject(NAME, fleet([{ ...curatorStream, model: "haiku-4.5" }]), KEY, { hubPath: HUB });
    // The placement wins over the persona's default — the point of the override.
    expect(useAppStore.getState().paneModels[`${KEY}:curator`]).toBe("haiku-4.5");

    // No override → the persona's own default.
    useAppStore.setState({ tabs: [], fleetPaneStreams: {}, paneModels: {} });
    useAppStore.getState().fleetStartProject(NAME, fleet([curatorStream]), KEY, { hubPath: HUB });
    expect(useAppStore.getState().paneModels[`${KEY}:curator`]).toBe("opus-4.5");

    // Neither → NO pane model at all, which is what makes the session launch with no `--model` and run
    // on Claude Code's own default. An entry here would be the app choosing a tier on the user's behalf.
    useAppStore.setState({ tabs: [], fleetPaneStreams: {}, paneModels: {}, personas: [curatorPersona] });
    useAppStore.getState().fleetStartProject(NAME, fleet([curatorStream]), KEY, { hubPath: HUB });
    expect(useAppStore.getState().paneModels[`${KEY}:curator`]).toBeUndefined();
  });

  it("launches a role-actor on a LOCAL model, and routes it to bsc-agent rather than Claude", () => {
    // `a-node-cannot-carry-a-local-model`, at the far end. The unit half is
    // `src/features/planner/fleet/teamFleet.test.ts` (the position → stream hop, where the value used
    // to be dropped); this is the half that proves a carried local model actually changes which
    // HARNESS the session runs on. Asserting only `paneModels` would pass with the session still
    // launching Claude Code — the exact silent-no-op shape the item was filed about.
    useAppStore.setState({
      tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, paneModels: {},
      paneProviders: {}, personas: [curatorPersona],
    });
    useAppStore.getState().fleetStartProject(NAME, fleet([{ ...curatorStream, model: "qwen3.5:35b-a3b" }]), KEY, { hubPath: HUB });
    const pane = `${KEY}:curator`;
    expect(useAppStore.getState().paneModels[pane]).toBe("qwen3.5:35b-a3b");
    expect(useAppStore.getState().paneProviders[pane]).toBe("bsc-agent");
  });

  it("keeps a Claude TIER on the claude harness — the local routing is derived, not global", () => {
    // The counterpart that stops the fix from over-reaching: `providerForModel` derives `bsc-agent`
    // from a model being OUTSIDE the tier registry, so a tier must go on producing no such provider.
    useAppStore.setState({
      tabs: [], bscBaseDir: "/home/user/.base-studio-code", fleetPaneStreams: {}, paneModels: {},
      paneProviders: {}, personas: [curatorPersona],
    });
    useAppStore.getState().fleetStartProject(NAME, fleet([{ ...curatorStream, model: "haiku-4.5" }]), KEY, { hubPath: HUB });
    expect(useAppStore.getState().paneProviders[`${KEY}:curator`]).not.toBe("bsc-agent");
  });

  it("falls back to the derived hub dir when no absolute hubPath is passed (never a worktree path)", () => {
    useAppStore.getState().fleetStartProject(NAME, fleet([curatorStream]), KEY);
    const cwd = useAppStore.getState().paneCwds[`${KEY}:curator`];
    // Derived hub path (projectHubCwd) — contains the project key under the base dir, and is NOT the
    // worktrees tree (a repo-less stream must never resolve to an agentWorktreeCwd).
    expect(cwd).toContain(KEY);
    expect(cwd).not.toContain("worktrees");
  });
});

import { describe, it, expect } from "vitest";
import { fnv1a32, fnv1a32hex, buildManifest, diffManifests, projectId, phaseId, issueId, nodeId } from "@/features/planner/lib/plannerCore";
import type { CanonicalFile, PlanManifest } from "@/features/planner/lib/plannerCore/types";
import fixtures from "./plannerCore.fixtures.json";

// ── FNV-1a hash (pinned vectors) ─────────────────────────────────────────────

describe("fnv1a32 — pinned fixture vectors", () => {
  it("empty string returns the FNV-1a offset basis", () => {
    expect(fnv1a32hex("")).toBe(fixtures.fnv1a32.empty);
  });

  it('"a" hashes to the known FNV-1a vector', () => {
    expect(fnv1a32hex("a")).toBe(fixtures.fnv1a32.a);
  });

  it('"foobar" hashes to the known FNV-1a vector', () => {
    expect(fnv1a32hex("foobar")).toBe(fixtures.fnv1a32.foobar);
  });

  it("fnv1a32 returns an unsigned 32-bit integer", () => {
    expect(fnv1a32("foobar")).toBeGreaterThanOrEqual(0);
    expect(fnv1a32("foobar")).toBeLessThanOrEqual(0xffffffff);
    expect(Number.isInteger(fnv1a32("foobar"))).toBe(true);
  });

  it("fnv1a32hex is always exactly 8 lowercase hex chars", () => {
    for (const input of ["", "a", "foobar", "hello world", "é"]) {
      const h = fnv1a32hex(input);
      expect(h).toMatch(/^[0-9a-f]{8}$/);
    }
  });

  it("hashes UTF-8 bytes (not UTF-16 code units) — multi-byte char differs from its code unit", () => {
    // 'é' is U+00E9: UTF-16 code unit 0xE9, but UTF-8 bytes 0xC3 0xA9.
    // If the implementation hashes code units, it would hash one byte (0xE9).
    // If it hashes UTF-8 bytes, it hashes two bytes (0xC3, 0xA9).
    // We verify the result is deterministic and non-trivially different from hashing 0xE9.
    const byteHash = fnv1a32hex("é");
    // Hash of a single byte 0xE9 via fnv1a32:
    //   h = 0x811c9dc5 ^ 0xe9 = 0x811c9d2c
    //   h = Math.imul(0x811c9d2c, 0x01000193) >>> 0 = some value
    // Since 'é' takes 2 UTF-8 bytes, the output will differ from the 1-byte interpretation.
    // We just verify the implementation is stable across calls (idempotent).
    expect(fnv1a32hex("é")).toBe(byteHash);
  });
});

