const comps: ComponentRecord[] = [
  { id: "button", name: "Button", kitId: "react-ui", role: "primitive", version: "1", used: 0, tags: [], variants: ["default"], composes: [], props: [], whenUse: [], whenNot: [], src: "", srcText: "" },
];

