});

// The HANDOFF: RequestSessionsMount → TerminalHost → TerminalView → pty_create.
//
// `RequestSessionsMount`'s own test asserts the charter lands in `paneStartupPromptText`, and stubs
// `TerminalSlot` out entirely — so nothing had ever checked that the charter reaches the LAUNCH. It
// did not. Every debug session in the running app came up as a bare `claude --model sonnet` (three
// argv entries, read from /proc) and sat at an empty prompt with no work, for as long as the feature
// has existed: no session transcript has ever contained the charter's first line.
//
// That is this repo's recurring shape — a green test covering less than its name implies — so the
// guard has to be the seam itself, not either side of it. This file mocks only what jsdom cannot run
// (xterm) and the two external stores (`bsc`, the Tauri bridge); the mount, the host, the slot and the
// view are all real, and the assertion is on the argument `pty_create` actually received.
import { describe, it, expect, beforeAll, beforeEach, afterEach, vi } from "vitest";
import { render, cleanup, waitFor } from "@testing-library/react";
import { TerminalHost } from "@/app/console/terminal/TerminalHost";
import { RequestSessionsMount } from "@/features/debug/RequestSessionsMount";
import { useAppStore } from "@/store";
import { invoke } from "@tauri-apps/api/core";

const REQUEST = { id: 7, status: "open", claimed_by: null, origin: "design-studio:designer-react", display_title: "ui list needs --kit" };
const { queue } = vi.hoisted(() => ({ queue: { rows: [] as (typeof REQUEST)[] } }));

// The queue, modelling the one contract that matters here: `claim` flips the oldest open row and
// returns it, so the mount has a definite id to bind a session to.
vi.mock("@/shared/lib/core/bsc", () => ({
  bscJson: vi.fn(async (_cwd: unknown, args: string[]) => {
    // The GLOBAL gate (`debug-sessions-have-a-global-off-switch`). `bsc request sessions --json`
    // resolves the policy and the pause in Rust and returns `allowed`; a blanket return answers it
    // with the row list, leaving `allowed` undefined — which reads as CLOSED and launches nothing.
    if (args[1] === "sessions") return { enabled: true, paused: false, allowed: true };
    if (args[1] === "claim") {
      const next = queue.rows.find((r) => r.status === "open");
      if (!next) return null;
      next.status = "claimed";
      return next;
    }
    return queue.rows;
  }),
  bsc: vi.fn(async () => ""),
  bscRun: vi.fn(async () => {}),
  bscWrite: vi.fn(async () => {}),
}));
// Run the poll body once, deterministically, rather than on a 20s timer.
// `usePoll` hands its callback an `isCancelled` probe (the mount checks it before writing state after
// an await). A mock that calls `fn()` bare passes `undefined` for it, so the first `isCancelled()`
// throws — the callback never ran, and the test failed for a reason that had nothing to do with it.
vi.mock("@/shared/hooks/usePoll", () => ({
  usePoll: (fn: (isCancelled: () => boolean) => void | Promise<void>) => { void fn(() => false); },
}));
// xterm cannot initialize in jsdom (`open()` needs real measurements).
vi.mock("@xterm/xterm", () => {
  class Terminal {
    cols = 80; rows = 24; options = {}; parser = { registerOscHandler: vi.fn() };
    loadAddon = vi.fn(); open = vi.fn(); write = vi.fn(); scrollToBottom = vi.fn();
    onData = vi.fn(() => ({ dispose: vi.fn() })); focus = vi.fn(); dispose = vi.fn();
    attachCustomKeyEventHandler = vi.fn(); getSelection = vi.fn(() => ""); refresh = vi.fn();
  }
  return { Terminal };
});
vi.mock("@xterm/addon-fit", () => ({ FitAddon: class { fit = vi.fn(); } }));
vi.mock("@xterm/xterm/css/xterm.css", () => ({}));

beforeAll(() => {
  Object.defineProperty(HTMLElement.prototype, "offsetWidth", { configurable: true, value: 800 });
  Object.defineProperty(HTMLElement.prototype, "offsetHeight", { configurable: true, value: 600 });
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => { cb(0); return 0; });
  vi.stubGlobal("ResizeObserver", class { observe() {} unobserve() {} disconnect() {} });
});

beforeEach(() => {
  queue.rows = [{ ...REQUEST }];
  vi.mocked(invoke).mockClear();
  vi.mocked(invoke).mockImplementation(async (cmd: string, payload?: unknown) => {
    if (cmd === "debug_repo_root") return "/repo";
    if (cmd === "pty_pane_runtime") {
      const ids = (payload as { paneIds?: string[] } | undefined)?.paneIds ?? [];
      return ids.map((paneId) => ({ paneId, live: false }));
    }
    if (cmd === "pty_create") return true;
    return "";
  });
  useAppStore.setState({ paneStartupPromptText: {}, paneContinue: {} });
});
afterEach(cleanup);

/** The `pty_create` payload, or undefined if the launch never happened. */
const launch = () => {
  const call = vi.mocked(invoke).mock.calls.find((c) => c[0] === "pty_create");
  return call?.[1] as { startupPrompt?: string; initCmd?: string; cwd?: string; continueSession?: boolean } | undefined;
};

describe("a spawned debug session launches with its charter", () => {
  it("bakes the charter into pty_create, naming the request it was spawned for", async () => {
    render(<TerminalHost><RequestSessionsMount /></TerminalHost>);
    await waitFor(() => {
      const p = launch();
      expect(p, "pty_create was never called — no session launched at all").toBeTruthy();
      // The whole point: a session that reaches claude with no prompt sits at an empty prompt forever,
      // and looks exactly like one that has finished.
      expect(p!.startupPrompt, "launched with NO charter — the session has nothing to do").toBeTruthy();
      expect(p!.startupPrompt).toContain("YOUR REQUEST IS #7");
      // ...and it is THIS request's charter, not a generic "go find work" (#one-request-one-debug-session).
      expect(p!.startupPrompt).toContain("bsc request get 7");
    });
  });

  /// The bug this file was written for, and the assertion that would have caught it first time.
  ///
  /// The charter was reaching `pty_create` all along — and the BACKEND threw it away.
  /// `resolveStartupPromptFreshOnly` returned true for every `debug-studio:` pane, and `plan_launch`
  /// suppresses the prompt when `fresh_only && has_history`. Every debug session runs in the
  /// base-studio-code repo, where claude has always run before, so `has_history` is permanently true:
  /// the charter was dropped on every launch that has ever happened, and the session came up as a
  /// bare `claude` with nothing to do.
  ///
  /// Asserting the payload — not just the prompt — is what makes this a guard rather than a
  /// coincidence: a prompt that is present in the payload and then discarded downstream looks
  /// identical to a working launch from here.
  ///
  /// The FLAG IS GONE (`the-launch-derives-its-own-fresh-only-instead-of-receiving-it`). The frontend
  /// no longer decides; it sends the two facts and the backend derives the rule from them plus its own
  /// studio registry. So the assertion moves with it: send the facts that make the backend DELIVER,
  /// and let `console::pty::tests::the_launch_derives_fresh_only_from_the_facts_it_is_given` prove the
  /// backend does. Asserting the old key here would have gone vacuous rather than red — `undefined`
  /// is not `false`, but a `?? false` would have swallowed exactly that.
  it("does NOT ask the backend to suppress the charter — the launch is fresh, so there is nothing to re-greet", async () => {
    render(<TerminalHost><RequestSessionsMount /></TerminalHost>);
    await waitFor(() => {
      const p = launch() as
        | ({ startupPromptFreshOnly?: boolean; restoreRequested?: boolean; startupPromptIsErrand?: boolean } & Record<string, unknown>)
        | undefined;
      expect(p, "pty_create was never called").toBeTruthy();
      expect(
        p!.startupPromptFreshOnly,
        "the computed flag must not come back — the backend derives it, and a second opinion on the wire is what this whole inversion removes",
      ).toBeUndefined();
      // A per-request session is not a crash restore, and `debug-studio:req-<id>` is not in the studio
      // registry — so these two facts are what make the backend deliver the charter.
      expect(p!.restoreRequested, "a freshly claimed request is not a crash restore").toBe(false);
      expect(typeof p!.startupPromptIsErrand, "the errand fact must be sent, not omitted").toBe("boolean");
    });
  });

  it("launches fresh in the repo, never resuming another conversation (#3497)", async () => {
    render(<TerminalHost><RequestSessionsMount /></TerminalHost>);
    await waitFor(() => {
      const p = launch();
      expect(p?.cwd).toBe("/repo");
      expect(p?.initCmd).toBe("claude");
      expect(p?.continueSession).toBe(false);
    });
  });

  it("carries the charter even when the STORE never got it — the property the prop buys", async () => {
    // The failure this fixes was invisible from either side: the mount wrote the charter, the view read
    // the store, and in production the write never reached the read. Emptying the store mid-flight is
    // the only way to assert that the launch no longer DEPENDS on that route.
    const original = useAppStore.setState;
    const spy = vi.spyOn(useAppStore, "setState").mockImplementation(((...args: Parameters<typeof original>) => {
      const out = original(...args);
      // Whatever the mount wrote, drop it again before anything can read it.
      original({ paneStartupPromptText: {} } as never);
      return out;
    }) as never);
    try {
      render(<TerminalHost><RequestSessionsMount /></TerminalHost>);
      await waitFor(() => {
        expect(useAppStore.getState().paneStartupPromptText).toEqual({});
        const prompt = launch()?.startupPrompt;
        expect(prompt, "the launch still depends on the store — it went out with no charter").toBeTruthy();
        expect(prompt).toContain("YOUR REQUEST IS #7");
      });
    } finally {
      spy.mockRestore();
    }
  });
});

// The role gate's behaviour, captured from the LIVE TypeScript so Rust can be proved to match it.
//
// ## Why a fixture rather than a hand-written table
//
// `launch-rules.ts` derives the security policy a session launches under — which commands are denied,
// which tools, which paths. Rust ENFORCES it (`deny_matches`, bsc-util/src/deny.rs) and WRITES it
// (`ensure_session_settings` takes the computed lists) but never COMPUTES it, so the policy is decided
// in the renderer. `epic-frontend-logic-over-backend-resources-belongs-in-rust` moves that derivation.
//
// A port of security policy that is subtly different is worse than no port. So this generates the
// answer from the implementation that is live TODAY, and a Rust test asserts its own derivation
// matches case for case. Hand-writing the expectations would only prove Rust agrees with whoever
// typed the table.
//
// Same pattern as `tunnelProtocol.fixtures.json` / `plannerCore.fixtures.json`: one byte-exact
// artifact read by BOTH sides. Regenerate deliberately:
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/roleGate.fixtures.gen.test.ts
//
// A regeneration that changes the file is a CHANGE OF POLICY. Read the diff before committing it.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { ROLE_DEFAULTS, roleCapability, type SessionRole } from "@/shared/lib/session/roleModel";
import {
  roleDeniedCommands,
  roleDeniedTools,
  roleWriteRules,
  sessionScopes,
} from "@/shared/lib/session/launchRules";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/roleGate.fixtures.json");

/** A surface catalog to complement against. Two shapes, because the EMPTY one fails open by design
 *  (see `roleDeniedCommands`) and that asymmetry is exactly the kind of thing a port drops. */
const SURFACES: Record<string, string[]> = {
  none: [],
  catalog: ["ui", "plan", "graph", "persona", "teams", "request", "fleet", "logs"],
};

/** Write globs are filled PER ASSIGNMENT, so a worker with an owned glob is a distinct case from one
 *  without: the carve-out logic branches on it. */
const GLOBS: Record<string, string[]> = {
  none: [],
  owned: ["src/**/*.ts", "contracts/**/*.json"],
};

function build() {
  const roles = Object.keys(ROLE_DEFAULTS).sort() as SessionRole[];
  const cases = [];
  for (const role of roles) {
    for (const [surfaceKey, surfaces] of Object.entries(SURFACES)) {
      for (const [globKey, writeGlobs] of Object.entries(GLOBS)) {
        const cap = roleCapability(role, writeGlobs.length ? { writeGlobs } : {});
        cases.push({
          role,
          surfaces: surfaceKey,
          globs: globKey,
          // EVERY field the derivation reads, so Rust can reproduce it from the fixture alone.
          // `allow` and `surfaces` were missing on the first pass and they are not decoration:
          // `isRestrictedRole`, `capabilitySurfaces` and `mayFileToolingRequest` all branch on them,
          // so a fixture without them cannot express the cases that matter most.
          capability: {
            role: cap.role,
            github: cap.github, git: cap.git, code: cap.code, net: cap.net, ui: cap.ui,
            // `graph` joins the projection the moment `roleDeniedCommands` starts reading it. This is
            // the exact trap the comment above records: a derivation that reads a field the fixture
            // does not carry cannot be reproduced from the fixture, and Rust's parity test fails
            // pointing at the DERIVATION when the fault is in what was captured
            // (`the-algorithms-graph-has-no-write-gate`).
            graph: cap.graph,
            writeGlobs: cap.writeGlobs ?? [],
            allow: [...(cap.allow ?? [])],
            surfaces: cap.surfaces ? [...cap.surfaces] : null,
          },
          deniedCommands: roleDeniedCommands(cap, surfaces),
          deniedTools: roleDeniedTools(cap),
          writeRules: roleWriteRules(cap),
          scopes: sessionScopes(cap),
        });
      }
    }
  }
  return { note: "GENERATED from the live TypeScript — see roleGate.fixtures.gen.test.ts", roles, surfaces: SURFACES, cases };
}

describe("the role gate's behaviour is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const built = build();
    const text = JSON.stringify(built, null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") {
      writeFileSync(FIXTURE, text);
    }
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("covers every role the table defines, so a new role cannot slip past the port", () => {
    const built = build();
    expect(built.roles.length).toBeGreaterThanOrEqual(9);
    expect(new Set(built.cases.map((c) => c.role)).size).toBe(built.roles.length);
  });
});

// #funnel-planner-takes-team-and-context — the three-tier funnel's capability shape.
//
// The funnel is architect → director → workers, and the property that makes it safe to run unattended
// is MONOTONIC capability: the closer a tier sits to the human, the less it can do; the closer to the
// code, the more. The architect ingests raw user prose, so it is the highest prompt-injection surface
// in the system and is deliberately the LEAST capable session anywhere. A worker is the most capable,
// and it is also the one confined to a single worktree on a single branch.
//
// This is asserted as an ORDER rather than as three separate row snapshots, because the invariant is
// the relationship: any future change that widens the architect past the director, or the director past
// a worker, is the regression — regardless of what the individual rows happen to say.
import { describe, it, expect } from "vitest";
import { ROLE_DEFAULTS, roleDeniedCommands, canWritePath } from "@/shared/lib/session/sessionRoles";
import { restrictedRoleCommands, type RoleCapability } from "@/shared/lib/session/roleModel";

/** The funnel, ordered least-capable first. `planner` is deliberately NOT here: it still exists as a
 *  role and its Glance node stands, but its RESPONSIBILITIES moved to the director, so it is not one of
 *  the three tiers this invariant is about. */
const TIERS = ["architect", "director", "worker"] as const;

/** Rank a capability tier so the axes can be compared as an order. */
const RANK: Record<string, number> = { none: 0, read: 1, write: 2 };
const rank = (v: string | undefined): number => RANK[v ?? "none"] ?? 0;

const cap = (role: (typeof TIERS)[number]): RoleCapability => ROLE_DEFAULTS[role];

describe("the three-tier funnel is monotonic — architect < director < worker", () => {
  it("never widens a git/github/code/net axis as you move UP the funnel toward the human", () => {
    // Walk the tiers in order and assert each axis is non-decreasing from architect to worker.
    for (const axis of ["git", "github", "code", "net"] as const) {
      const ranks = TIERS.map((t) => rank(cap(t)[axis] as string));
      for (let i = 1; i < ranks.length; i++) {
        expect(
          ranks[i],
          `${axis}: ${TIERS[i]} (${cap(TIERS[i])[axis]}) must not be NARROWER than ${TIERS[i - 1]} (${cap(TIERS[i - 1])[axis]})`,
        ).toBeGreaterThanOrEqual(ranks[i - 1]);
      }
    }
  });

  it("keeps the architect strictly the least capable — none on every axis", () => {
    // Not merely "≤ the director": being the least capable session in the system is the deliberate
    // property, because this is the tier that reads raw user prose.
    const a = cap("architect");
    for (const axis of ["git", "github", "code", "net", "ui"] as const) {
      expect(a[axis], `architect.${axis}`).toBe("none");
    }
  });

  it("gives ONLY the worker a git write — the two tiers above it cannot mutate history", () => {
    expect(cap("worker").git).toBe("write");
    for (const t of ["architect", "director"] as const) {
      expect(cap(t).git, `${t} must not hold git write`).not.toBe("write");
      // The two tiers deny at DIFFERENT granularities and both are correct: the architect is
      // `git: "none"`, so the whole binary is denied, while the director is `git: "read"` and denies
      // the mutating verbs individually. Asserting `git push` literally would have failed the stricter
      // of the two — so the check is "is a push reachable", not "is this exact string listed".
      const denies = roleDeniedCommands(cap(t));
      const blocked = (verb: string) => denies.includes("git") || denies.includes(`git ${verb}`);
      for (const verb of ["push", "merge"]) {
        expect(blocked(verb), `${t} must not be able to git ${verb}`).toBe(true);
      }
    }
  });

  it("lets NO tier mutate GitHub — local-first means there is nothing up there to write", () => {
    for (const t of TIERS) {
      expect(rank(cap(t).github as string), `${t}.github`).toBeLessThan(RANK.write);
    }
  });

  it("separates the two WRITE surfaces by path, not just by tier", () => {
    // Both the director and a worker are `code: write`, so the order alone does not distinguish them —
    // what does is WHERE. The director writes plan/context prose at the hub; the worker writes code in
    // its own lane. Neither can reach the other's.
    const dir = cap("director"), worker = cap("worker");
    expect(dir.code).toBe("write");
    expect(worker.code).toBe("write");
    // The director cannot touch project source, whatever its writeGlobs say about markdown.
    for (const p of ["src/App.tsx", "crates/kb/src/lib.rs", "web/src/auth/login.ts"]) {
      expect(canWritePath(dir, p), `director must not write ${p}`).toBe(false);
    }
    // …and it CAN write the context files it is now responsible for authoring.
    for (const p of ["prompts/api-kickoff.md", "goal.md"]) {
      expect(canWritePath(dir, p), `director must be able to author ${p}`).toBe(true);
    }
  });
});

describe("the director's team-design surface (#funnel-planner-takes-team-and-context)", () => {
  it("can reach bsc teams, because it is NOT a restricted-allow role", () => {
    // There is no per-role allow-list to add to here: `bsc` sits in the always-allowed mandatory tier
    // (permissions/base.json), and a role only gets a narrowed surface if it appears in the restricted
    // table. The director does not — so team authoring is reachable by construction. This pins that
    // fact, because "add it to the allow-list" would be a no-op that reads like a change.
    expect(restrictedRoleCommands("director")).toEqual([]);
  });

  it("designs the TEAM but no longer authors the PERSONAS in it", () => {
    // NARROWED by the maintainer (2026-08-19, epic `the-persona-is-the-whole-agent`): "we should
    // restrict role creation and modification to the architect. this will be the role responsible of
    // configuring them before the director is requested to design their team and the capability."
    //
    // So the two halves split. The ARCHITECT configures the personas and their capability; the
    // DIRECTOR then composes a team out of the personas that already exist. That is coherent because a
    // team PLACES personas into positions — it does not need to mint them — and it is why the director
    // keeps `bsc teams` untouched while losing the three persona write verbs.
    const denies = roleDeniedCommands(cap("director"));
    for (const c of denies) {
      expect(c.startsWith("bsc teams"), `role gate must not deny ${c}`).toBe(false);
    }
    expect(denies).toContain("bsc persona set");
    expect(denies).toContain("bsc persona remove");
    expect(denies).toContain("bsc persona rename");
    // READS stay open — a director must still be able to see what its team is made of.
    expect(denies).not.toContain("bsc persona");
    expect(denies.some((c) => c.startsWith("bsc persona get") || c.startsWith("bsc persona list"))).toBe(false);
  });

  it("keeps the ARCHITECT's team surface narrow — the persona half is now PERMANENT, not transitional", () => {
    // `bsc persona` on this surface used to be labelled transitional, "until team design moves to the
    // director". Team design DID move; persona authoring deliberately did not, and is now the
    // architect's standing job (see the director case above). `bsc teams` remains so the architect can
    // READ the team its personas are composed into. The surface is still a fixed restricted list, so
    // it cannot grow into the director's job by accident.
    const surface = restrictedRoleCommands("architect");
    expect(surface).toContain("bsc teams");
    expect(surface).toContain("bsc persona");
    // …and it still cannot reach the plan beyond its own two handoff nouns.
    expect(surface).not.toContain("bsc plan");
  });
});

describe("the architect's view of its tier (#architect-sees-director-state, revised)", () => {
  // SUPERSEDED IN PART by #architect-creates-a-director-with-discovery. This item framed the grant as
  // READ-ONLY ("seeing is not reaching"), and that half is gone: the architect DOES create directors.
  // What survives — and is what these tests now pin — is that the READ still resolves, and that the
  // grant still stops short of `bsc fleet wake`.
  it("can still read director state — the read got MORE useful, not less", () => {
    // An architect that can create a director needs to see which already run before creating another.
    // The grant is now the singular verb, and `directors` resolves through its prefix.
    const surface = restrictedRoleCommands("architect");
    expect(surface).toContain("bsc fleet director");
    expect(surface.some((c) => "bsc fleet directors".startsWith(c))).toBe(true);
  });

  it("is granted the FULL verb, never the `bsc fleet` prefix — that would carry `wake`", () => {
    // Grants are prefix matches expanded to `Bash(<cmd> *)`. `"bsc fleet"` would auto-run
    // `bsc fleet wake` too — the DIRECTOR's lever over a stopped worker, one tier below where this
    // session belongs. Creating a director is additive and allowed; reaching into its fleet is not.
    const surface = restrictedRoleCommands("architect");
    expect(surface).not.toContain("bsc fleet");
    expect(surface.filter((c) => c.startsWith("bsc fleet"))).toEqual(["bsc fleet director", "bsc fleet directors"]);
    expect("bsc fleet wake".startsWith("bsc fleet director")).toBe(false);
  });

  it("still cannot reach WORKERS — the tier boundary is one level, not two", () => {
    // `bsc fleet list` is the DIRECTOR's view of its workers. An architect holding it would be reading
    // past the tier it hands work to, into a fleet it does not run.
    expect(restrictedRoleCommands("architect")).not.toContain("bsc fleet list");
  });

  it("gains no WRITE from seeing — the read gate does not lift its role floor", () => {
    const a = cap("architect");
    for (const axis of ["git", "github", "code", "net", "ui"] as const) {
      expect(a[axis], `architect.${axis}`).toBe("none");
    }
  });
});

import { describe, it, expect } from "vitest";
import { ROLE_DEFAULTS, PLAN_WRITE_GLOBS, DOC_GLOBS, DB_OWNED_PLAN_FILES, DEP_MANIFEST_FILES, roleDeniedCommands, sessionScopes, canWritePath } from "@/shared/lib/session/sessionRoles";
import { mergeRoleDefaults, roleCapability, restrictedRoleCommands, type RoleCapability } from "@/shared/lib/session/roleModel";

// Security guard for the externalized role→capability table (@data/permissions/role-capabilities.json,
// #2027 P1). The role gate is least-privilege; a JSON edit that WIDENS a role's access (e.g. gives a
// reviewer git:write, or hands a non-planner default write globs) must trip a test here, not ship.
describe("role capability table (loaded from @data/permissions/role-capabilities.json)", () => {
  it("has exactly the 19 roles with their intended github/git/code/net/ui tiers", () => {
    const tiers = Object.fromEntries(
      Object.values(ROLE_DEFAULTS).map((c) => [c.role, `${c.github}/${c.git}/${c.code}/${c.net}/${c.ui}`]),
    );
    // ui: "read" across the board (#2470) — every existing role may USE the component kit but never
    // redefine it; `write` is reserved for the designer session (#2471).
    expect(tiers).toEqual({
      planner:    "read/read/write/read/read",
      worker:     "read/write/write/read/read",
      // Director (#funnel-planning-moves-to-director): it absorbed the PLANNING surface, and with it
      // the planner's tiers. `git`/`github` dropped from `write` to `read` — the only session at a
      // project hub that could push or merge without owning a worktree, and now there is none. Merging
      // belongs to the integration stream; the commons belong to the commons stream. Any edit that
      // widens either axis back to `write` must fail this test.
      director:   "read/read/write/read/read",
      triage:     "write/none/none/read/read",
      tester:     "read/read/none/read/read",
      // Surface OPERATOR (`surface-operator-runs-confined-to-its-own-noun`): the tiers are copied
      // VERBATIM from the floor its persona already carried, so NO access axis moved. What is new is
      // its `allow` list, whose PRESENCE confines it — the build tier that let it run `cargo` in the
      // app's own tree is suppressed outright, and its per-session noun arrives by profile instead.
      operator:   "read/read/none/read/read",
      reviewer:   "read/read/none/read/read",
      issuer:     "write/read/none/read/read",
      juror:      "read/read/none/read/read",
      // Documentor (#1555): read-only on git/GitHub, code:none — writes come solely from its
      // DOC_GLOBS carve-out (asserted below), never a code tier.
      documentor: "read/read/none/read/read",
      // Designer (#2471): the Design Studio's UI-kit session — `none` on every OTHER axis; the kit
      // store is its one write grant (`ui: write`, #2470), and its whole command surface is
      // `bsc ui`, granted at launch via the restricted allow-list.
      designer:   "none/none/none/none/write",
      // Architect (#2755): the Teams Studio's team-authoring session — `none` on EVERY axis, `ui`
      // included (unlike the designer it is not a UI-kit session). Its whole command surface is
      // `bsc teams` + `bsc persona`, granted at launch via the restricted allow-list.
      architect:  "none/none/none/none/none",
      // Librarian (#2787): the Algorithms tab's knowledge-store session — `none` on github/git/code/net.
      // Its write surface is `bsc graph`, granted at launch via the restricted allow-list. THE ONE
      // DEVIATION IS `ui: "read"` (#4090), and it is deliberate: it must be able to ask "is this harvest
      // candidate already a component?" so the algorithms and component graphs partition the tree instead
      // of both claiming it. `read` denies every mutating verb — the designer still owns that store — so
      // an edit that widens this to `write` must fail this test.
      librarian:  "none/none/none/none/read",
      // Sound-designer (#3369, epic #3071 phase 4): the Sounds tab's sound-kit authoring session —
      // `none` on EVERY axis, `ui` included: a sound is a synthesis descriptor in its own store, not a
      // UI kit. Its whole command surface is `bsc sound`, granted at launch via the restricted
      // allow-list. Identical posture to the architect/librarian.
      "sound-designer": "none/none/none/none/none",
      // Integrator (#4023): the Integration Studio's session — `none` on github/git/code/ui like its
      // studio siblings, with `bsc data connector` as its whole command surface via the restricted
      // allow-list. THE ONE DEVIATION IS `net: "read"`, and it is deliberate: this role's work starts at
      // the vendor's documentation, so it is the only studio allowed the web tools. Any edit that widens
      // another axis here — or that quietly drops net back to none — must fail this test.
      integrator: "none/none/none/read/none",
      // Marketer (#2431): read-only on git/GitHub, code:none — writes come solely from its
      // marketing-content carve-out (asserted below), never a code tier.
      marketer:   "read/read/none/read/read",
      // Curator (#3092, epic #3087): the reusable-library post-landing actor — `none` on GitHub/net,
      // `code: none` (never edits project files), `git: read` (reads the landed repo it harvests from),
      // and `ui: write` (the ONE write grant — the component/kit store; `bsc graph` for algorithms comes
      // via the restricted allow-list at launch). No writeGlobs — its writes go to the stores, not files.
      curator:    "none/read/none/none/write",
      // Debugger (#3322): the app's own full-cap maintenance session — write on git/GitHub/code + ui.
      debugger:   "read/write/write/read/write",
      // Steward (`a-network-gets-a-root-session-that-can-use-what-it-owns`): a NETWORK's root session
      // — it USES what the network has already built, where the architect PLANS what it will build.
      // `none` on every axis, like the architect and the designer: its whole auto-runnable surface is
      // its `allow` list of READ verbs, so every mutating command falls through to a prompt and the
      // human decides per action. Deliberately not the `operator` above, which is confined to ONE
      // `bsc` noun and measures what that noun costs.
      steward:    "none/none/none/none/none",
    });
  });

  it("only the director + planner + documentor + marketer ship default write globs; every other role starts empty (no code writes)", () => {
    // PLAN_WRITE_GLOBS derives from the DIRECTOR now — it carries the planning write surface.
    expect(PLAN_WRITE_GLOBS).toBe(ROLE_DEFAULTS.director.writeGlobs); // same array — derived, not duplicated
    expect(PLAN_WRITE_GLOBS).toEqual(["*.md", "*.json", "prompts/*.md", "prompts/*", "discovery/*.md", "discovery/*"]);
    // The documentor ships DOC_GLOBS by default (its prose-doc carve-out, #1555) — strictly markdown/docs.
    expect(DOC_GLOBS).toBe(ROLE_DEFAULTS.documentor.writeGlobs); // same array — derived, not duplicated
    // No `docs/**`: that would grant code files under docs/ (e.g. docs/gen.ts) — the boundary is
    // markdown/prose only (#2326). `**/*.md` already covers every markdown file, incl. docs/*.md.
    expect(DOC_GLOBS).toEqual(["*.md", "**/*.md", "README*", "**/README*", "CHANGELOG*"]);
    // The marketer ships a marketing-content carve-out (#2431) — markdown/mdx under marketing/·content/
    // plus README/CHANGELOG. STRICTLY markdown/mdx (no open dirs, so no code extension can slip in),
    // so `code: "none"` stays honest.
    expect(ROLE_DEFAULTS.marketer.writeGlobs).toEqual([
      "marketing/**/*.md", "marketing/**/*.mdx", "content/**/*.md", "content/**/*.mdx",
      "README*", "**/README*", "CHANGELOG*", "**/CHANGELOG*",
    ]);
    expect(ROLE_DEFAULTS.marketer.writeGlobs.every((g) => /\.(md|mdx)$|README|CHANGELOG/.test(g))).toBe(true);
    // The four RESTRICTED studio roles ship a `scratch/**` carve-out (#3373) — NOT project content: a
    // sealed staging dir inside their own workspace, the only way they can author at all now that a
    // heredoc cannot be allow-listed. Pinned exactly, so a widening past the staging dir fails here.
    // `steward` joins them for the same reason: it is a restricted session whose surface is `bsc`, so
    // `scratch/**` is the only place it can put a working note at all. Pinned exactly here too, so a
    // widening past the staging dir fails rather than ships.
    for (const role of ["designer", "architect", "librarian", "sound-designer", "integrator", "steward"] as const) {
      expect(ROLE_DEFAULTS[role].writeGlobs).toEqual(["scratch/**"]);
    }
    const CARVED = ["director", "planner", "documentor", "marketer", "designer", "architect", "librarian", "sound-designer", "integrator", "steward"];
    for (const c of Object.values(ROLE_DEFAULTS)) {
      if (!CARVED.includes(c.role)) expect(c.writeGlobs).toEqual([]);
    }
  });

  it("carries the db-owned + dep-manifest deny lists", () => {
    expect(DB_OWNED_PLAN_FILES).toEqual(["deploy.md", "deploy.json", "phases.json", "issues.json", "fleet.json", "repos.json", "features.json"]);
    expect(DEP_MANIFEST_FILES).toEqual(["package.json", "package-lock.json", "Cargo.toml", "Cargo.lock", "pnpm-lock.yaml", "yarn.lock"]);
  });

  // Regression for #2325: `overlayFile` (#2047) FULLY REPLACES role-capabilities.json with a config-dir
  // copy. A STALE override seeded before the shipped default gained a role (documentor, #1555) would drop
  // it, and reading that role at module load (`DOC_GLOBS = ROLE_DEFAULTS.documentor.writeGlobs`) threw
  // `TypeError reading writeGlobs`, crashing the whole UI. `mergeRoleDefaults` floors on the embedded set.
  it("floor-merges a stale override onto the embedded roles so a newly-shipped role never vanishes (#2325)", () => {
    const cap = (role: string, writeGlobs: string[] = []): RoleCapability =>
      ({ role, github: "read", git: "read", code: "none", net: "read", ui: "read", writeGlobs }) as RoleCapability;
    const embedded = { planner: cap("planner", ["*.md"]), documentor: cap("documentor", ["docs/**"]) };
    const staleOverride = { planner: cap("planner", ["*.md"]) }; // seeded before documentor existed — no documentor key

    const merged = mergeRoleDefaults(embedded, staleOverride);

    // The role the stale override lacked survives from the embedded floor (not undefined → no crash).
    expect(merged.documentor).toBeDefined();
    expect(merged.documentor.writeGlobs).toEqual(["docs/**"]);
    // And an override that DOES carry a role still customizes it (overlay wins on top of the floor).
    const customized = mergeRoleDefaults(embedded, { planner: cap("planner", ["custom/**"]) });
    expect(customized.planner.writeGlobs).toEqual(["custom/**"]);
  });

  // Regression for #4108: `config/` is seeded ONCE (`ensure_seeded` writes "only files that are ABSENT")
  // and NEVER refreshed, so on every existing install the mirror is frozen at whatever shipped the day
  // it was first run. A capability granted later is invisible forever. Measured: the librarian's
  // `projects` harvest root landed in the packaged default and was dropped by a mirror still carrying
  // `['app-repo']` — which is exactly why the Algorithms studio could not see mobile-studio-code.
  it("a stale mirror cannot REVOKE a shipped harvest root (#4108)", () => {
    const cap = (role: string, harvestRoots: string[]): RoleCapability =>
      ({ role, github: "read", git: "read", code: "none", net: "read", ui: "read", writeGlobs: [], harvestRoots }) as RoleCapability;
    const embedded = { librarian: cap("librarian", ["app-repo", "projects"]) };
    const staleMirror = { librarian: cap("librarian", ["app-repo"]) };   // written before `projects` shipped

    const merged = mergeRoleDefaults(embedded, staleMirror);
    expect(merged.librarian.harvestRoots).toEqual(["app-repo", "projects"]);
  });

  it("a mirror may still ADD a harvest root the shipped default lacks (#4108)", () => {
    const cap = (role: string, harvestRoots: string[]): RoleCapability =>
      ({ role, github: "read", git: "read", code: "none", net: "read", ui: "read", writeGlobs: [], harvestRoots }) as RoleCapability;
    const merged = mergeRoleDefaults(
      { librarian: cap("librarian", ["app-repo"]) },
      { librarian: cap("librarian", ["app-repo", "some-local-root"]) },
    );
    // Union, not replace — and no duplicate for the root both sides name.
    expect(merged.librarian.harvestRoots).toEqual(["app-repo", "some-local-root"]);
  });

  it("does NOT floor write-bearing fields — a mirror may still narrow those (#4108)", () => {
    // The asymmetry is deliberate: a harvest root is read-only scan reach the app decides, but
    // silently WIDENING a write grant would be the opposite mistake.
    const cap = (role: string, writeGlobs: string[]): RoleCapability =>
      ({ role, github: "read", git: "read", code: "none", net: "read", ui: "read", writeGlobs }) as RoleCapability;
    const merged = mergeRoleDefaults(
      { documentor: cap("documentor", ["docs/**", "*.md"]) },
      { documentor: cap("documentor", ["docs/**"]) },
    );
    expect(merged.documentor.writeGlobs).toEqual(["docs/**"]);
  });

  // Regression for #2470 (the per-FIELD companion to #2325): a stale config-dir override written
  // BEFORE the `ui` axis shipped must never yield a write grant. Nothing may crash, and the gate must
  // fail CLOSED (behave as `read`).
  //
  // #4108 fixed this a LAYER EARLIER: `mergeRoleDefaults` now merges per FIELD, so a missing field
  // falls back to the embedded value instead of vanishing. This test therefore asserts the field
  // survives the merge, AND keeps every consumer-level check below — those are the defence in depth
  // that still has to hold for a capability built by hand rather than through the merge.
  it("a stale override missing the ui field defaults to read everywhere it's consumed (#2470/#4108)", () => {
    // The pre-#2470 capability shape: role present, no `ui` field (what a stale override yields).
    const stale = {
      role: "worker", github: "read", git: "write", code: "write", net: "read", writeGlobs: [] as string[],
    } as RoleCapability;
    expect(stale.ui).toBeUndefined(); // the hazard under test

    // The merge now RESTORES the missing field from the embedded floor (#4108) rather than propagating
    // the hole — the same protection that stops a stale mirror revoking a harvest root.
    const embedded = { worker: { ...stale, ui: "read" as const } };
    expect(mergeRoleDefaults(embedded, { worker: stale }).worker.ui).toBe("read");

    // The accessor prepends the field floor, so a capability built through it always carries a tier.
    expect(roleCapability("worker").ui).toBe("read");
    // The hard gate fails closed on the missing tier: mutating verbs stay denied…
    const denies = roleDeniedCommands(stale);
    expect(denies).toContain("bsc ui set");
    expect(denies).toContain("bsc component kit remove");
    expect(denies).not.toContain("bsc ui"); // …but not the whole tool (that's the `none` tier).
    // And the runtime scope doc renders the same read floor — on BOTH stores.
    //
    // `graph` is the stronger case of the two, because the stale capability predates the axis
    // ENTIRELY rather than merely omitting a known field: until `the-algorithms-graph-has-no-write-gate`
    // there was no tier for the algorithms store at all, and `bsc-graph` had no gate to read one. A
    // capability from that era must therefore narrow to `read` here, never inherit the total access
    // every role actually had. This is the assertion that fails if `?? "read"` is ever dropped.
    expect(stale.graph).toBeUndefined(); // the second hazard under test
    expect(sessionScopes(stale)).toEqual({ graph: "read", ui: "read" });
  });
});

// The stale-mirror CEILING (#funnel-planning-moves-to-director). The #2325 floor above stops a mirror
// DROPPING something the app ships; this is the other direction — a mirror must not RE-GRANT a
// capability the app has revoked. `config/` is seeded once and never refreshed, so without this the
// director's narrowing to git/github `read` would apply to nobody with an existing install.
describe("mergeRoleDefaults — the capability ceiling", () => {
  const cap = (role: string, over: Partial<RoleCapability> = {}): RoleCapability =>
    ({ role, github: "read", git: "read", code: "none", net: "read", ui: "read", writeGlobs: [], ...over }) as RoleCapability;

  it("clamps a mirror that re-grants a tier the shipped app revoked", () => {
    const embedded = { director: cap("director", { git: "read", github: "read" }) };
    const staleMirror = { director: cap("director", { git: "write", github: "write" }) };
    const merged = mergeRoleDefaults(embedded, staleMirror);
    expect(merged.director.git).toBe("read");
    expect(merged.director.github).toBe("read");
  });

  it("still lets a mirror NARROW a tier — tightening is the user's prerogative", () => {
    const embedded = { worker: cap("worker", { git: "write", code: "write" }) };
    const tightened = { worker: cap("worker", { git: "read", code: "none" }) };
    const merged = mergeRoleDefaults(embedded, tightened);
    expect(merged.worker.git).toBe("read");
    expect(merged.worker.code).toBe("none");
  });

  it("restores shipped writeGlobs when the mirror supplies an EMPTY list", () => {
    // The exact stale-mirror shape: the director gained `code: write` AND its plan globs in one
    // change, so a mirror written before it carries `writeGlobs: []` and would leave the role able
    // to write with no boundary defined.
    const embedded = { director: cap("director", { code: "write", writeGlobs: ["*.md", "*.json"] }) };
    const staleMirror = { director: cap("director", { code: "none", writeGlobs: [] }) };
    const merged = mergeRoleDefaults(embedded, staleMirror);
    expect(merged.director.writeGlobs).toEqual(["*.md", "*.json"]);
  });

  it("a NON-empty mirror glob list still wins (a real narrowing survives)", () => {
    const embedded = { director: cap("director", { code: "write", writeGlobs: ["*.md", "*.json"] }) };
    const narrowed = { director: cap("director", { code: "write", writeGlobs: ["*.md"] }) };
    expect(mergeRoleDefaults(embedded, narrowed).director.writeGlobs).toEqual(["*.md"]);
  });

  it("the SHIPPED director really is clamped — a mirror cannot hand it push/merge back", () => {
    // End to end against the actual shipped row, not a fixture.
    const staleMirror = { director: { ...ROLE_DEFAULTS.director, git: "write", github: "write" } };
    const merged = mergeRoleDefaults({ director: ROLE_DEFAULTS.director }, staleMirror as Record<string, RoleCapability>);
    const denies = roleDeniedCommands(merged.director);
    expect(denies).toContain("git push");
    expect(denies).toContain("gh pr merge");
  });
});

// The invariant this whole slice exists to establish.
