// The RENDERED settings a session actually launches with — the one artifact no other guard reads.
//
// Three defects shipped together in `surface-operator-runs-confined-to-its-own-noun`, and every gate
// leg was green for all of them, because each existed only in the composed result: a granted noun
// that `permissions.deny` also matched, a confined session writing into a shared tree, and a role the
// cage could not classify. The fixtures next door capture SHAPE per role; this asserts a PROPERTY of
// the composition — that the file does not contradict itself.
import { describe, it, expect } from "vitest";
import { buildSessionSettings } from "@/app/console/lib/sessionLaunch";
import { ROLE_DEFAULTS, type SessionRole } from "@/shared/lib/session/sessionRoles";
import type { AppStore } from "@/store/types";

const PANE = "p:0";

/** A REAL catalog, not `[]`. An empty one denies nothing extra by design, so a test that passed one
 *  would assert the invariant against a settings file with no surface denies in it at all — vacuous,
 *  and it passed the bite unchanged until this was fixed. These are the surfaces the operator's noun
 *  is drawn from plus a few it must never reach. */
const CATALOG = [
  { name: "studio" }, { name: "persona" }, { name: "teams" }, { name: "graph" }, { name: "ui" },
  { name: "plan" }, { name: "surface" }, { name: "request" }, { name: "errors" }, { name: "mem" },
  { name: "perf" }, { name: "logs" }, { name: "session" }, { name: "worktree" }, { name: "disk" },
  { name: "component", status: "deprecated" },
];

const BASE = {
  paneRoles: {}, paneProfiles: {}, agentProfiles: [], paneRoleGlobs: {}, deniedCommands: [],
  paneFlows: {}, surfaceCatalog: CATALOG, fleetPaneStreams: {}, appRepoRoot: "/repo", bscBaseDir: "/base",
  mcpServers: [], skills: [], sessionSkillOverrides: {}, sessionSkillGroups: {}, skillGroups: [],
  paneSkills: {}, personas: [], panePersonas: {}, bypassPermissions: false,
} as unknown as AppStore;

/** The command a `Bash(...)` rule names, or null for a whole-tool rule like `Read`. */
function bashPrefix(rule: string): string | null {
  const m = /^Bash\((.*)\)$/.exec(rule);
  if (!m) return null;
  return m[1].replace(/\s*\*$/, "").trim();
}

/**
 * Does `deny` swallow `allow`? Claude Code precedence is deny > ask > allow, so an allow the deny
 * list also matches is not a grant — it is a grant that silently does nothing.
 *
 * A trailing `*` makes a rule a PREFIX; without one it matches the bare command. Both directions
 * matter: `Bash(bsc studio *)` in deny swallows `Bash(bsc studio)` in allow, which is exactly the
 * pair the operator shipped with.
 */
function denySwallows(deny: string, allow: string): boolean {
  const d = bashPrefix(deny), a = bashPrefix(allow);
  if (d === null || a === null) return false;
  return deny.includes("*") ? a === d || a.startsWith(`${d} `) : a === d;
}

function contradictions(settings: { allowedCommands?: string[]; deniedCommands?: string[] }) {
  const allow = (settings.allowedCommands ?? []).map((c) => `Bash(${c})`);
  const deny = (settings.deniedCommands ?? []).map((c) => `Bash(${c})`);
  const out: string[] = [];
  for (const a of allow) for (const d of deny) if (denySwallows(d, a)) out.push(`${a} is granted, and ${d} denies it`);
  return out;
}

const settingsFor = (role: string | undefined, profile?: Record<string, unknown>) =>
  buildSessionSettings(
    {
      ...BASE,
      paneRoles: role ? { [PANE]: role } : {},
      paneProfiles: profile ? { [PANE]: profile.id as string } : {},
      agentProfiles: profile ? [profile] : [],
    } as unknown as AppStore,
    PANE,
  ) as unknown as { allowedCommands?: string[]; deniedCommands?: string[] };

describe("a rendered session never denies what it grants", () => {
  // THE REGRESSION. The operator's noun arrives on a per-pane PROFILE, because a noun chosen per
  // session is not something a static role can name. The undeclared-surface complement was built from
  // the ROLE alone, so `Bash(bsc studio *)` landed in allow AND deny — and deny wins, leaving the one
  // command that session exists to run denied by the same change that granted it.
  it("a granted per-pane noun is not denied by the role's undeclared-surface complement", () => {
    const profile = {
      id: "gen_surface_studio", name: "op", color: "#000", category: "generated", desc: "", mode: "deny",
      commands: ["bsc studio", "bsc-ask", "bsc-answer"],
      tools: { read: "allow", grep: "allow", glob: "allow", edit: "deny", write: "deny", bash: "deny", web: "deny", task: "deny" },
      paths: { allow: [], deny: ["**/*"] }, net: { allow: [] },
    };
    const s = settingsFor("operator", profile);
    expect(s.allowedCommands ?? []).toContain("bsc studio");
    expect(contradictions(s)).toEqual([]);
  });

  // The property, over the whole table — so the next role added cannot reintroduce it quietly.
  it("holds for every role in the capability table", () => {
    for (const role of Object.keys(ROLE_DEFAULTS) as SessionRole[]) {
      expect(contradictions(settingsFor(role)), role).toEqual([]);
    }
  });

  it("holds for a pane with no role at all", () => {
    expect(contradictions(settingsFor(undefined))).toEqual([]);
  });
});

import { describe, it, expect } from "vitest";
import { UNCAGED_ROLES, isUncagedRole, sandboxPlanFor } from "@/app/console/lib/sessionLaunch";
import type { AppStore } from "@/store/types";

// THE SAME LIST as `UNCAGED_ROLES` in `bsc-sandbox--profile.rs`. The two decide the same question on
// opposite sides of the bridge: Rust decides whether to CAGE, the frontend decides whether to write
// the `/bsc-hook` guest paths that only exist inside a cage. When they disagreed, every launch of
// these panes wrote hooks Rust then had to repair — 13 repairs in one app run, the notice printed in
// the pane each time, because the writer kept regenerating what the repair had just fixed.
const RUST_UNCAGED = ["designer", "architect", "librarian", "director", "integrator", "operator", "steward"];

const state = (role: string | undefined) =>
  ({ paneRoles: role ? { p: role } : {}, sandboxConsoles: false, paneWslDistro: {} } as unknown as AppStore);

describe("uncaged roles — the backend's list, mirrored", () => {
  it("matches the Rust list exactly", () => {
    expect([...UNCAGED_ROLES].sort()).toEqual([...RUST_UNCAGED].sort());
  });

  it("recognises each one, and nothing else", () => {
    for (const r of RUST_UNCAGED) expect(isUncagedRole(r as never), r).toBe(true);
    for (const r of ["worker", "tester", "reviewer", "triage", "juror"]) {
      expect(isUncagedRole(r as never), r).toBe(false);
    }
    expect(isUncagedRole(undefined)).toBe(false);
  });

  it("does NOT plan a namespace for a role the backend will refuse to cage", () => {
    // The bug: a director got backend "namespace", so `namespaceHooks` was true and the settings
    // writer emitted `/bsc-hook` — a path that exists only inside a cage the backend then declined.
    const plan = sandboxPlanFor(state("director"), "p", true);
    expect(plan.backend).not.toBe("namespace");
    expect(plan.namespaceHooks).toBe(false);
    expect(plan.role).toBeUndefined();
  });

  it("still plans a namespace for a role the backend WILL cage", () => {
    // The fix must not disable caging generally — a worker is exactly what the cage is for.
    const plan = sandboxPlanFor(state("worker"), "p", true);
    expect(plan.backend).toBe("namespace");
    expect(plan.namespaceHooks).toBe(true);
    expect(plan.role).toBe("worker");
  });

  it("plans nothing for a pane with no role at all", () => {
    expect(sandboxPlanFor(state(undefined), "p", true).backend).not.toBe("namespace");
  });
});

import { describe, it, expect } from "vitest";
import { resolveStartupPromptFreshOnly } from "@/app/console/lib/sessionLaunch";
import { SINGLE_STUDIO_PANE_IDS, designerSessionId } from "@/shared/lib/session/systemSessions";
import { useAppStore } from "@/store";
import type { AppStore } from "@/store/types";

// Any app-owned studio pane. A per-technology one on purpose: it is the class whose recognition
// moved from a list to a grammar, so it is the one worth exercising here.
const STUDIO = designerSessionId("react");
const FLEET = "twitter-clone-test:director";
const MANUAL = "man:tab_abc:p2";
const state = (restore: Record<string, boolean> = {}) =>
  ({ restoreRequested: restore } as unknown as AppStore);

// `bsc-agent` takes `--continue`/`-c`, deliberately mirroring claude's, so every rule about RESUMING
// applies to it. This one was gated on `isClaudeProvider`, which made its protection Claude-only: a
// local studio session never suppressed its charter kickoff, so a resumed one was RE-INSTRUCTED on
// every launch. The rule is about resuming, not about which harness resumes.
describe("fresh-only is about resuming, not about the harness", () => {
  it("marks a studio session's kickoff fresh-only for a LOCAL pane, not just a Claude one", () => {
    expect(resolveStartupPromptFreshOnly(state(), STUDIO, false))
      .toBe(resolveStartupPromptFreshOnly(state(), STUDIO, true));
    expect(resolveStartupPromptFreshOnly(state(), STUDIO, false)).toBe(true);
  });

  it("honours an explicit restore request on either harness", () => {
    const s = state({ [FLEET]: true });
    expect(resolveStartupPromptFreshOnly(s, FLEET, false)).toBe(true);
    expect(resolveStartupPromptFreshOnly(s, FLEET, true)).toBe(true);
  });

  it("still exempts a manual console — the user's shell has no charter to re-deliver", () => {
    expect(resolveStartupPromptFreshOnly(state(), MANUAL, false)).toBe(false);
    expect(resolveStartupPromptFreshOnly(state(), MANUAL, true)).toBe(false);
  });

  it("leaves an ordinary fleet pane alone on both harnesses", () => {
    // A director is not a studio session: its kickoff is not fresh-only, and its resume comes from
    // `paneContinue` instead. Pinned so this change cannot be read as making everything fresh-only.
    expect(resolveStartupPromptFreshOnly(state(), FLEET, false)).toBe(false);
    expect(resolveStartupPromptFreshOnly(state(), FLEET, true)).toBe(false);
  });
});

describe("the resume flag survives a restart", () => {
  it("persists paneContinue alongside the other launch facts", () => {
    // THE director's resume path. `fleetStartProject` sets it for every fleet pane; unpersisted, a
    // cold start read false and `resume: continue_session && has_history` was false however much
    // history existed. Measured: `has_history=true · resumed=false` beside a 54 KB conversation.json.
    const persisted = (useAppStore.persist?.getOptions?.().partialize?.(
      useAppStore.getState() as never,
    ) ?? {}) as Record<string, unknown>;
    expect(Object.prototype.hasOwnProperty.call(persisted, "paneContinue")).toBe(true);
  });
});

import { describe, it, expect } from "vitest";
import { ROLE_DEFAULTS, roleCapability, roleWriteRules, hasScopedWriteCarveOut, type SessionRole } from "@/shared/lib/session/sessionRoles";
import { roleProfileId } from "@/shared/lib/session/roleProfile";
import { PROFILES, APP_ROLES, type AgentProfile } from "./agentProfiles";

// Role → profile consistency (the unified model). Every session role maps to a DEFAULT profile
// (roleProfile.ROLE_PROFILE), which must (a) exist in the packaged set and (b) not escalate past the
// role's code tier — a code:none role's profile must never auto-ALLOW the file-write tools. The role
// gate is the backstop: it hard-denies the write tools for code:none roles regardless of the profile.

const ROLES = Object.keys(ROLE_DEFAULTS) as SessionRole[];
const ALL: AgentProfile[] = [...PROFILES, ...APP_ROLES];
const profileFor = (role: SessionRole) => ALL.find((p) => p.id === roleProfileId(role));
const WRITE_TOOLS = ["Edit", "Write", "NotebookEdit"]; // no MultiEdit — removed tool (#3534)

describe("role → profile consistency (sessionRoles ↔ roleProfile)", () => {
  it("every role maps to a packaged profile that exists", () => {
    for (const role of ROLES) {
      expect(profileFor(role), `role '${role}' → '${roleProfileId(role)}' resolves to no profile`).toBeTruthy();
    }
  });

  it("no code:'none' role's profile auto-allows the file-write tools", () => {
    for (const role of ROLES) {
      if (ROLE_DEFAULTS[role].code !== "none") continue;
      // A scoped carve-out role (documentor's DOC_GLOBS) intentionally allows writes, hard-limited to
      // its globs by the bsc-scope hook — its profile allow is by design, not an escalation (#2326).
      if (hasScopedWriteCarveOut(roleCapability(role))) continue;
      const p = profileFor(role)!;
      expect(p.tools.edit, `${role}: code:none profile must not allow edit`).not.toBe("allow");
      expect(p.tools.write, `${role}: code:none profile must not allow write`).not.toBe("allow");
    }
  });

  it("the role gate hard-denies the write tools for every code:none role (backstop)", () => {
    // Makes a looser profile safe: at launch the sessionRoles gate denies the file-write tools
    // outright for every code:none role (no commons carve-out), and Claude precedence is deny > allow.
    for (const role of ROLES) {
      if (ROLE_DEFAULTS[role].code !== "none") continue;
      // Carve-out roles (documentor) lift the whole-tool deny so their per-glob doc allows aren't
      // masked; the bsc-scope hook is their backstop instead. Every OTHER code:none role keeps the deny.
      if (hasScopedWriteCarveOut(roleCapability(role))) continue;
      const deny = roleWriteRules(roleCapability(role)).deny;
      for (const t of WRITE_TOOLS) {
        expect(deny, `${role}: role gate must deny ${t}`).toContain(t);
      }
    }
  });
});

// #1338 ph2 — the global skills.db bridge + the store's hydrate / write-through cache behavior.
// Migrated to the generic `bsc` bridge (#2142): every call goes through `invoke("bsc", { projectKey,
// args, stdin? })` with `projectKey: null` (skills are global) and `bsc skill …` args; reads return
// raw stdout (a JSON string) the bridge parses, writes feed the JSON body on stdin.
import { describe, it, expect, beforeEach, vi } from "vitest";
import { invoke } from "@tauri-apps/api/core";
import { loadLibrary, pushSkill, dropSkill, pushGroup, dropGroup } from "@/features/skills/lib/skillBridge";
import { blankSkill, seedSkills, type SkillDef } from "@/features/skills/lib/skills";
import { useAppStore } from "@/store";

const sk = (over: Partial<SkillDef> & { id: string; name: string }): SkillDef =>
  ({ ...blankSkill(), ...over });

/** A `bsc` invoke payload the bridge sends. */
type BscPayload = { projectKey: string | null; args: string[]; stdin?: string };

/** Build a mock `invoke` that dispatches on the `bsc skill …` args, returning JSON strings for the two
 *  reads (`list --full`, `group list`) and "" for every write (`add`/`remove`). Records every call. */
function mockBsc(reads: { skills?: unknown; groups?: unknown }, calls?: BscPayload[]) {
  vi.mocked(invoke).mockImplementation(async (cmd: string, payload?: unknown) => {
    if (cmd !== "bsc") return undefined;
    const p = payload as BscPayload;
    calls?.push(p);
    const key = p.args.join(" ");
    if (key === "skill list --full") return JSON.stringify(reads.skills ?? []);
    if (key === "skill group list") return JSON.stringify(reads.groups ?? []);
    return ""; // writes (add / remove / group add / group remove)
  });
}

describe("skillBridge (#1338 → bsc #2142)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    vi.mocked(invoke).mockResolvedValue(undefined);
  });

  it("loadLibrary drives `bsc skill list --full` + `group list` and maps rows to full SkillDefs", async () => {
    const calls: BscPayload[] = [];
    mockBsc(
      {
        skills: [{ id: "s1", name: "Open PR", kind: "workflow", source: "team", desc: "d", prompt: "p", tools: ["Bash"], profiles: ["build"], projects: [], enabled: true, pinned: false }],
        groups: [{ id: "g1", name: "Grp", hue: "var(--accent)", skillIds: ["s1"] }],
      },
      calls,
    );
    const lib = await loadLibrary();
    expect(lib).not.toBeNull();
    expect(lib!.skills).toHaveLength(1);
    const s = lib!.skills[0];
    expect(s).toMatchObject({ id: "s1", name: "Open PR", enabled: true, tools: ["Bash"], prompt: "p" });
    // Telemetry is display-only and not stored in skills.db → re-defaulted to zero on the way in.
    expect(s.invocations).toBe(0);
    expect(s.trend).toEqual([]);
    expect(lib!.groups).toEqual([{ id: "g1", name: "Grp", hue: "var(--accent)", skillIds: ["s1"] }]);
    // Skills are global → projectKey null; the reads use the verified `bsc skill` args.
    expect(calls).toEqual([
      { projectKey: null, args: ["skill", "list", "--full"] },
      { projectKey: null, args: ["skill", "group", "list"] },
    ]);
  });

  it("loadLibrary tolerates sparse rows (missing fields default)", async () => {
    mockBsc({ skills: [{ id: "x", name: "Bare" }], groups: [] });
    const lib = await loadLibrary();
    expect(lib!.skills[0]).toMatchObject({ id: "x", name: "Bare", kind: "workflow", source: "first-party", enabled: false, tools: [] });
  });

  it("loadLibrary returns null when the bridge rejects (no Tauri host)", async () => {
    vi.mocked(invoke).mockRejectedValue(new Error("no command"));
    expect(await loadLibrary()).toBeNull();
  });

  it("write-through helpers drive the matching `bsc skill` verbs in order", async () => {
    const calls: BscPayload[] = [];
    mockBsc({}, calls);
    await pushSkill(sk({ id: "s1", name: "x" }));
    await dropSkill("s1");
    await pushGroup({ id: "g1", name: "G", hue: "h", skillIds: [] });
    await dropGroup("g1");
    expect(calls.map((c) => c.args)).toEqual([
      ["skill", "add"],
      ["skill", "remove", "s1"],
      ["skill", "group", "add"],
      ["skill", "group", "remove", "g1"],
    ]);
    // The upserts feed their JSON body on stdin; the removes are positional (no stdin).
    expect(JSON.parse(calls[0].stdin!)).toMatchObject({ id: "s1", name: "x" });
    expect(calls[1].stdin).toBeUndefined();
    expect(JSON.parse(calls[2].stdin!)).toMatchObject({ id: "g1", name: "G" });
    expect(calls[3].stdin).toBeUndefined();
  });

  it("write-through never throws when the bridge is absent", async () => {
    vi.mocked(invoke).mockRejectedValue(new Error("absent"));
    await expect(pushSkill(sk({ id: "s", name: "n" }))).resolves.toBeUndefined();
    await expect(dropGroup("g")).resolves.toBeUndefined();
  });
});

describe("skills store ↔ skills.db (#1338 → bsc #2142)", () => {
  beforeEach(() => {
    vi.mocked(invoke).mockReset();
    vi.mocked(invoke).mockResolvedValue(undefined);
    useAppStore.setState({ skills: [], skillGroups: [] });
  });

  it("hydrateSkills replaces the library from the bridge + reconciles the packaged set", async () => {
    mockBsc({
      skills: [{ id: "user-1", name: "Mine", enabled: true }],
      groups: [{ id: "g1", name: "G", hue: "h", skillIds: [] }],
    });
    await useAppStore.getState().hydrateSkills();
    const { skills, skillGroups } = useAppStore.getState();
    expect(skills.some((s) => s.id === "user-1")).toBe(true);  // the user's db skill is preserved
    expect(skills.some((s) => s.packaged)).toBe(true);          // packaged set reconciled in from code
    expect(skillGroups).toEqual([{ id: "g1", name: "G", hue: "h", skillIds: [] }]);
  });

  it("hydrateSkills re-pushes NOTHING when the db already holds the current packaged set (#3672)", async () => {
    const calls: BscPayload[] = [];
    // The db already mirrors the code-owned packaged set → no content drift → no re-push burst.
    mockBsc({ skills: seedSkills(), groups: [] }, calls);
    await useAppStore.getState().hydrateSkills();
    await Promise.resolve();
    expect(calls.filter((c) => c.args[0] === "skill" && c.args[1] === "add")).toEqual([]);
  });

  it("hydrateSkills re-pushes ONLY a packaged skill whose authored content drifted (#3672)", async () => {
    const calls: BscPayload[] = [];
    // The db's stored copy of the first packaged skill lags the code (its prompt changed).
    const stale = seedSkills().map((s, i) => (i === 0 ? { ...s, prompt: "STALE BODY" } : s));
    mockBsc({ skills: stale, groups: [] }, calls);
    await useAppStore.getState().hydrateSkills();
    await Promise.resolve();
    const adds = calls.filter((c) => c.args[0] === "skill" && c.args[1] === "add");
    expect(adds.length).toBe(1); // just the drifted one, not all ~40
  });

  it("refreshSkills re-reads the library WITHOUT pushing the set back (cheap poll, #1419)", async () => {
    const calls: BscPayload[] = [];
    mockBsc({
      skills: [{ id: "authored-now", name: "Authored", enabled: true }],
      groups: [{ id: "grp-session-acme", name: "Acme", hue: "h", skillIds: ["authored-now"] }],
    }, calls);
    await useAppStore.getState().refreshSkills();
    const { skills, skillGroups } = useAppStore.getState();
    expect(skills.some((s) => s.id === "authored-now")).toBe(true); // freshly-authored skill surfaces
    expect(skillGroups).toEqual([{ id: "grp-session-acme", name: "Acme", hue: "h", skillIds: ["authored-now"] }]);
    // The whole point vs hydrateSkills: NO write-back, so it's safe to poll on a timer.
    expect(calls.map((c) => c.args)).not.toContainEqual(["skill", "add"]);
  });

  it("hydrateSkills is a no-op (keeps the seeded set) when the bridge is unreachable", async () => {
    useAppStore.setState({ skills: [sk({ id: "keep", name: "Keep" })] });
    vi.mocked(invoke).mockRejectedValue(new Error("no host"));
    await useAppStore.getState().hydrateSkills();
    expect(useAppStore.getState().skills).toEqual([sk({ id: "keep", name: "Keep" })]);
  });

  it("addSkill / removeSkill write through to the bridge", async () => {
    const calls: BscPayload[] = [];
    mockBsc({}, calls);
    const id = useAppStore.getState().addSkill({ ...blankSkill(), name: "Authored here" });
    useAppStore.getState().removeSkill(id);
    // fire-and-forget — let the microtasks settle
    await Promise.resolve();
    await Promise.resolve();
    expect(calls.map((c) => c.args)).toEqual([
      ["skill", "add"],
      ["skill", "remove", id],
    ]);
  });

  it("addSkillGroup writes the group through to the bridge", async () => {
    const calls: BscPayload[] = [];
    mockBsc({}, calls);
    useAppStore.getState().addSkillGroup("Rendering");
    await Promise.resolve();
    expect(calls.map((c) => c.args)).toContainEqual(["skill", "group", "add"]);
  });
});

// GENERATOR + parity guard for `storePayloads.fixtures.json` (#3761 / D3 of Mobile-Studio-Code#246).
//
// `store_state` is `{ domain, rev, json }` where `json` is an OPAQUE serialized string, so every
// per-domain payload shape crosses the wire completely unguarded — the class of bug behind the glance
// `status`→`health`/`activity` split (mobile read a deleted field for ~12 days) and the security
// invented-shape (every section blank against a live feed). This file runs the REAL builders over the
// model-checked `PROJECTION_INPUTS` and pins the canonical output as a byte-comparable fixture that
// mobile-studio-code decodes with its own selectors — so a silent shape change fails a test.
//
// Regenerate:  UPDATE_STORE_FIXTURES=1 npx vitest run storePayloads.fixtures   (or `npm run fixtures:store`)
// The write is env-gated so CI (which never sets it) can never self-heal a real drift.

import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  buildGlancePayload, buildOrgPayload, buildBlueprintsPayload, buildSkillsPayload,
  buildComponentsPayload, buildThemesPayload, buildAutomationsPayload, buildMcpPayload,
  buildAlertsPayload, buildSecurityPayload,
} from "@/features/tunnel/lib/storeProjections";
// #3760: the `plan` domain's builder lives in the planner feature (it's planner-published), reached
// via the barrel so the harness covers plan like every other domain.
import { buildPlanBoardPayload } from "@/features/planner";
import { PROJECTION_INPUTS } from "@/features/tunnel/lib/storeProjections.fixtures";
import { STORE_DOMAINS } from "@/features/tunnel/lib/tunnelClient";

// Resolved from cwd (repo/worktree root when vitest runs), matching the primitives.gen idiom.
const FILE = join(process.cwd(), "src/features/tunnel/lib/storePayloads.fixtures.json");

// Every registered store domain now has a builder + fixture (#3760 brought `plan` in — its builder
// lives in the planner feature, `buildPlanBoardPayload`). The exemption list is kept (empty) so a
// future planner-only or transient domain can be documented here rather than silently dropped.
const UNPROJECTED_DOMAINS = [] as const;

// The canonical payloads — the REAL builders over the canonical inputs, one per projected domain.
const domains = {
  glance: buildGlancePayload(PROJECTION_INPUTS.glance),
  org: buildOrgPayload(PROJECTION_INPUTS.org),
  blueprints: buildBlueprintsPayload(PROJECTION_INPUTS.blueprints),
  skills: buildSkillsPayload(PROJECTION_INPUTS.skills),
  components: buildComponentsPayload(PROJECTION_INPUTS.components),
  themes: buildThemesPayload(PROJECTION_INPUTS.themes),
  automations: buildAutomationsPayload(PROJECTION_INPUTS.automations),
  mcp: buildMcpPayload(PROJECTION_INPUTS.mcp),
  alerts: buildAlertsPayload(PROJECTION_INPUTS.alerts),
  security: buildSecurityPayload(PROJECTION_INPUTS.security),
  plan: buildPlanBoardPayload(PROJECTION_INPUTS.plan),
};

// Variants pin optionality + nullability the way `auth_ok_pre_grant` does for frames: each toggles ONE
// nullable input so mobile's selectors are exercised against the null branch, not just the populated one.
const variants = {
  glance_l0: buildGlancePayload({ ...PROJECTION_INPUTS.glance, drill: null }),
  skills_no_lessons: buildSkillsPayload({ ...PROJECTION_INPUTS.skills, lessons: null }),
  blueprints_no_team: buildBlueprintsPayload({
    blueprints: [PROJECTION_INPUTS.blueprints.blueprints[1]], // the team-less `migrate` card
    activeBlueprintId: "migrate",
  }),
};

const generated = {
  $comment:
    "Canonical store_state PAYLOAD fixtures (#3761 / Mobile-Studio-Code#246), GENERATED from the real " +
    "build*Payload functions over PROJECTION_INPUTS (storeProjections.fixtures.ts) — never hand-authored. " +
    "Shared BYTE-IDENTICALLY with mobile-studio-code, whose selectors decode `domains.<d>` / `variants.<v>` " +
    "and assert a non-degenerate view. INVARIANT: no field here equals a mobile selector's fallback (no " +
    "`idle` health, real ISO-8601 audit timestamps, non-default enums), so the smoke layer can tell " +
    "'read correctly' from 'fell back' — a pure field DELETION still fails. Small on purpose (2-3 rows / " +
    "collection); cap behaviour (SECURITY_AUDIT_CAP / AUTOMATION_RUNS_CAP) is asserted in " +
    "storeProjections.test.ts, NOT by inflating this file. Regenerate: `npm run fixtures:store`. " +
    "All 11 registered domains are covered — `plan` (planner-published, built by buildPlanBoardPayload) " +
    "was brought in by #3760.",
  domains,
  variants,
};

const serialised = JSON.stringify(generated, null, 2) + "\n";

describe("storePayloads.fixtures.json — canonical per-domain payload parity (#3761)", () => {
  it("regenerates the committed fixture when UPDATE_STORE_FIXTURES=1 (env-gated so CI can't self-heal)", () => {
    if (process.env.UPDATE_STORE_FIXTURES) writeFileSync(FILE, serialised);
    expect(existsSync(FILE), "storePayloads.fixtures.json missing — run `npm run fixtures:store`").toBe(true);
  });

  it("matches the builder output round-tripped through JSON (drops undefined-valued keys, as the wire does)", () => {
    const onDisk = JSON.parse(readFileSync(FILE, "utf8").replace(/\r\n/g, "\n"));
    // JSON.parse(JSON.stringify(...)) drops `undefined`-valued keys — exactly what serialization sends
    // over the tunnel, so the fixture is compared against what mobile ACTUALLY receives.
    expect(onDisk).toEqual(JSON.parse(JSON.stringify(generated)));
  });

  it("covers every registered store domain (minus the tracked UNPROJECTED exemptions)", () => {
    const covered = new Set(Object.keys(domains));
    const missing = STORE_DOMAINS.filter((d) => !covered.has(d) && !UNPROJECTED_DOMAINS.includes(d as never));
    expect(missing, `store domains with no payload fixture: ${missing.join(", ")}`).toEqual([]);
  });

  it("pins the nullable fields via variants (the null branch mobile's selectors must handle)", () => {
    expect(variants.glance_l0.drill).toBeNull();
    expect(variants.glance_l0.drillFleet).toBeNull();
    expect(variants.skills_no_lessons.lessons).toBeNull();
    expect(variants.blueprints_no_team.activeTeam).toBeNull();
  });
});

// #fleet-wake-reaches-a-session-with-no-pane — the director's one lever over a stopped stream.
//
// Reported from a running fleet: "the director is unable to wake sessions that aren't running."
// `wakePane` resolved the owning tab and bailed when there was none, so it could only ever wake a pane
// that ALREADY EXISTED in an open tab — which is the opposite of the case the director protocol names
// it for ("a stream still has open issues but its session is not live").
//
// It matters more now than when it was filed: under the no-app-injection directive the app never starts
// or prompts a session, so a stream that has stopped has exactly ONE way back that is not a user click,
// and this is it.
//
// NOTE the adjacent fix this is NOT: #4025 made wake resolve the owning tab by IDENTITY rather than by
// the retired positional id, which fixed wake for panes that exist. This is the pane that does not.
import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
import { resetFleetPanes } from "@/test/storeReset";
import { fleetPaneId } from "@/app/console/lib/paneIdentity";

const KEY = "demo";
const STREAM = "api";
const PANE = fleetPaneId(KEY, STREAM);

/** A build tab for `demo` that does NOT contain the api pane — a closed-and-reopened fleet, or a
 *  stream that was planned but never launched. */
function buildTab(paneIds: string[]) {
  return {
    id: "tab-1", name: "Demo · build", layout: "2×2", state: "idle",
    runId: 1, projectKey: KEY, kind: "build" as const, seq: 0, paneIds,
  };
}

/** Arm the store as a real fleet leaves it: the roster knows the stream, the tab does not hold it. */
function arm(paneIds: string[], over: Record<string, unknown> = {}) {
  useAppStore.setState({
    tabs: [buildTab(paneIds)],
    fleetPaneStreams: { [PANE]: { id: STREAM, name: "API", repo: "own/api", owns: [], issues: [], dependsOn: [] } },
    disabledPanes: {},
    dormantPanes: {},
    endedPanes: {},
    ...over,
  } as never);
}

describe("wakePane reaches a stream whose pane does not exist", () => {
  beforeEach(() => { resetFleetPanes(); useAppStore.setState({ tabs: [] }); });

  it("creates the pane in the project's build tab and reports success", () => {
    // The regression: an empty `paneIds` used to make `findPaneOwnerTab` return null and wake return
    // false, which the Rust side surfaces as "it resolved to no open tab, or is disabled".
    arm([]);
    const ok = useAppStore.getState().wakePane(PANE, "pick up your open issues");
    expect(ok, "wake must succeed for a planned stream with no pane").toBe(true);
    expect(useAppStore.getState().tabs[0].paneIds).toContain(PANE);
  });

  it("bumps the owning tab's runId, so the new pane actually mounts", () => {
    // Seating the pane without the remount would leave the grid rendering yesterday's cells.
    arm([]);
    useAppStore.getState().wakePane(PANE, "go");
    expect(useAppStore.getState().tabs[0].runId).toBe(2);
  });

  it("bakes the prompt and asks to RESUME, exactly as an existing-pane wake does", () => {
    // This asserted `false` — describing the behaviour rather than justifying it, and the two wake
    // paths agreed on the wrong thing. `plan_launch` computes `resume: continue_session &&
    // has_history`, so a cleared flag meant a woken worker could never continue however much history
    // it had: it re-read its kickoff and started over. Waking a parked worker is by definition
    // "pick this back up", and with no history the launch still starts fresh and still delivers the
    // prompt, because `resume` needs both halves.
    arm([]);
    useAppStore.getState().wakePane(PANE, "pick up #12");
    const st = useAppStore.getState();
    expect(st.paneStartupPromptText[PANE]).toBe("pick up #12");
    expect(st.paneContinue[PANE]).toBe(true);
  });

  it("fills a FREE cell before extending the grid", () => {
    // A reaped fleet leaves holes. Appending past them would grow the layout for no reason and leave
    // an empty cell in the middle of the grid.
    arm(["demo:director", "", "demo:web"]);
    useAppStore.getState().wakePane(PANE, "go");
    expect(useAppStore.getState().tabs[0].paneIds).toEqual(["demo:director", PANE, "demo:web"]);
  });

  it("REFUSES a stream that is not in the project's fleet — an unknown stream is a real error", () => {
    // The acceptance draws this line deliberately: an UNLAUNCHED stream is not an error, an UNKNOWN one
    // is. `fleetPaneStreams` is the roster, so its absence is what distinguishes them.
    arm([]);
    expect(useAppStore.getState().wakePane(fleetPaneId(KEY, "not-a-stream"), "go")).toBe(false);
    expect(useAppStore.getState().tabs[0].paneIds).toEqual([]);
  });

  it("mints a fresh build tab when the project has NO tab at all (#165)", () => {
    // The regression this fixes: a stream already in the roster (it ran once) but its build tab was
    // closed ENTIRELY — not just missing this one pane. The old refusal ("that is a relaunch, not a
    // wake") sent a director straight past this lever to a whole-fleet `bsc fleet start --force`, just
    // to reseat one pane and repair its `.claude/settings.json` (request #165).
    useAppStore.setState({
      tabs: [],
      fleetPaneStreams: { [PANE]: { id: STREAM, name: "API", repo: "own/api", owns: [], issues: [], dependsOn: [] } },
    } as never);
    expect(useAppStore.getState().wakePane(PANE, "go")).toBe(true);
    const tab = useAppStore.getState().tabs[0];
    expect(tab.kind).toBe("build");
    expect(tab.projectKey).toBe(KEY);
    expect(tab.paneIds).toContain(PANE);
  });

  it("SEATS a disabled pane and clears the flag — a wake revives, it does not refuse", () => {
    // This asserted the opposite. Maintainer's call (2026-08-26), after being blocked three times:
    // ending a session must not prevent the director from restarting it. The old refusal made
    // `disabledPanes` a permanent, director-unreachable state — only a Console pane-menu toggle
    // clears it — so "paused" and "ended twenty minutes ago" were the same thing, forever.
    arm([], { disabledPanes: { [PANE]: true } });
    expect(useAppStore.getState().wakePane(PANE, "go")).toBe(true);
    expect(useAppStore.getState().tabs[0].paneIds).toContain(PANE);
    expect(useAppStore.getState().disabledPanes[PANE]).toBeUndefined();
  });

  it("leaves the EXISTING-pane path exactly as it was (#4025 must not regress)", () => {
    arm([PANE], { dormantPanes: { [PANE]: true }, endedPanes: { [PANE]: true } });
    const before = useAppStore.getState().tabs[0].paneIds;
    expect(useAppStore.getState().wakePane(PANE, "resume")).toBe(true);
    const st = useAppStore.getState();
    expect(st.tabs[0].paneIds).toEqual(before);          // not re-seated, not duplicated
    expect(st.dormantPanes[PANE]).toBeUndefined();        // the reaped placeholder is cleared…
    expect(st.endedPanes[PANE]).toBeUndefined();          // …and so is the ended mark
    expect(st.tabs[0].runId).toBe(2);
  });
});

// ── STARTING a stream that never launched (#the-director-cannot-start-a-stream-that-never-launched) ──
//
// Reported from a running fleet: "the director is unable to start sessions that aren't already opened."
//
// The refusal above (`REFUSES a stream that is not in the project's fleet`) used `fleetPaneStreams` as
// the oracle for "is this a real stream". But that map is written by `fleetStartProject` alone, so it is
// the roster of what LAUNCHED — never of what the plan HOLDS. A stream plan.db names and no session ever
// ran has no entry, so it read as UNKNOWN and the wake refused. `bsc fleet list` calls that state
// `never-launched` and sent the director to `bsc fleet start <projectKey>`, a WHOLE-fleet launch that is
// refused outright while any pane is live — so a director with a running fleet had no lever at all.
//
// Rust reads plan.db (`fleet/start.rs` already does) and now carries the row, with the absolute cwd it
// resolved, on `bsc://fleet-wake` for a pane that is NOT LIVE. So the store's answer to "is this real"
// comes from the plan rather than from its own launch history, and the acceptance's line survives
// intact: Rust resolving NOTHING means plan.db does not name it, and that still refuses.
import type { AgentStream } from "@/features/planner/fleet/planFleet";

/** The plan row for a stream that has never launched, as Rust hands it over. */
const NEVER_LAUNCHED: AgentStream & { cwd: string } = {
  id: STREAM, name: "API", repo: "own/api", owns: ["src/api/"], issues: ["#7"], dependsOn: [],
  cwd: "/home/u/.base-studio-code/worktrees/demo/api--api",
};

describe("wakePane STARTS a stream the roster never saw", () => {
  beforeEach(() => { resetFleetPanes(); useAppStore.setState({ tabs: [] }); });

  /** A build tab exists (the director is running in it) and the roster is EMPTY — the never-launched case. */
  function armUnlaunched() {
    useAppStore.setState({
      tabs: [buildTab([`${KEY}:director`])],
      fleetPaneStreams: {}, disabledPanes: {}, dormantPanes: {}, endedPanes: {},
      personas: [], blueprints: [], projectBlueprintId: {},
    } as never);
  }

  it("seats the pane when Rust supplies the plan row", () => {
    armUnlaunched();
    expect(useAppStore.getState().wakePane(PANE, "start on #7", NEVER_LAUNCHED)).toBe(true);
    expect(useAppStore.getState().tabs[0].paneIds).toContain(PANE);
  });

  it("adopts the row into the roster, so the NEXT wake needs no plan lookup", () => {
    // The roster is what `bsc fleet wake` reads on the second call, and what the coordinator resolves a
    // pane's stream through — a pane seated without it would be a session nothing could attribute.
    armUnlaunched();
    useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED);
    expect(useAppStore.getState().fleetPaneStreams[PANE]?.id).toBe(STREAM);
    // `cwd` is a LAUNCH fact, not part of the plan row — it must not be stored as if it were.
    expect(useAppStore.getState().fleetPaneStreams[PANE]).not.toHaveProperty("cwd");
  });

  it("uses the absolute cwd RUST resolved, never a re-derived one", () => {
    // #905: re-deriving it here reads the async-loaded `bscBaseDir` mirror, and an empty one drops the
    // session at the user's home dir. `bscBaseDir` is deliberately left unset to prove nothing falls back.
    armUnlaunched();
    useAppStore.setState({ bscBaseDir: "" } as never);
    useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED);
    expect(useAppStore.getState().paneCwds[PANE]).toBe(NEVER_LAUNCHED.cwd);
  });

  it("still REFUSES when Rust resolved nothing — an unknown stream stays an error", () => {
    // This is the whole reason the refusal moved rather than being deleted: plan.db not naming the
    // stream is what "unknown" now means, and it arrives as an absent `stream`.
    armUnlaunched();
    expect(useAppStore.getState().wakePane(fleetPaneId(KEY, "not-a-stream"), "go")).toBe(false);
    expect(useAppStore.getState().tabs[0].paneIds).not.toContain(fleetPaneId(KEY, "not-a-stream"));
  });

  it("mints a build tab too, for a stream that never launched AND has no tab at all (#165)", () => {
    // The exact dogfood shape request #165 was filed over: a stream plan.db has always named, whose
    // worktree already exists on disk, that has NEVER seated a pane — and whose project has no open
    // build tab either (closed, or the fleet's director never launched one). `bsc fleet start` refuses
    // outright while any OTHER stream in the fleet is live, and `--force` would relaunch every one of
    // them just to repair this one worktree's missing `.claude/settings.json`.
    useAppStore.setState({
      tabs: [], fleetPaneStreams: {}, disabledPanes: {}, dormantPanes: {}, endedPanes: {},
      personas: [], blueprints: [], projectBlueprintId: {},
    } as never);
    expect(useAppStore.getState().wakePane(PANE, "start on #7", NEVER_LAUNCHED)).toBe(true);
    const tab = useAppStore.getState().tabs[0];
    expect(tab.paneIds).toEqual([PANE]);
    expect(useAppStore.getState().paneCwds[PANE]).toBe(NEVER_LAUNCHED.cwd);
  });

  it("wires the woken pane EXACTLY as a launch would have wired it", () => {
    // The anti-drift guard, and the reason `streamPaneWiring` exists. Two launch paths that agree today
    // and diverge later is the failure this codebase has paid for before (`fleetStartBridge`'s header
    // names it). So: launch the same row, record what it produced, then wake it and compare.
    const streamRow: AgentStream = (({ cwd: _cwd, ...row }) => row)(NEVER_LAUNCHED);
    resetFleetPanes();
    useAppStore.setState({ tabs: [], personas: [], blueprints: [], projectBlueprintId: {}, bscBaseDir: "/base" } as never);
    useAppStore.getState().fleetStartProject("Demo", { recommended: 1, reasoning: "t", streams: [streamRow], director: { enabled: false } }, KEY,
      { hubPath: "/hub", worktreePaths: { [STREAM]: NEVER_LAUNCHED.cwd } });
    const launched = useAppStore.getState();
    const asLaunched = {
      role: launched.paneRoles[PANE], profile: launched.paneProfiles[PANE], repo: launched.paneRepos[PANE],
      globs: launched.paneRoleGlobs[PANE], flow: launched.paneFlows[PANE], model: launched.paneModels[PANE],
      stream: launched.paneStream[PANE], cwd: launched.paneCwds[PANE],
    };

    resetFleetPanes();
    armUnlaunched();
    useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED);
    const woken = useAppStore.getState();
    expect({
      role: woken.paneRoles[PANE], profile: woken.paneProfiles[PANE], repo: woken.paneRepos[PANE],
      globs: woken.paneRoleGlobs[PANE], flow: woken.paneFlows[PANE], model: woken.paneModels[PANE],
      stream: woken.paneStream[PANE], cwd: woken.paneCwds[PANE],
    }).toEqual(asLaunched);
    // Non-vacuity: the comparison is worthless if the launch wired nothing.
    expect(asLaunched.role).toBe("worker");
    expect(asLaunched.globs, "the owned path became a write boundary").toEqual(["src/api/**"]);
  });

  it("leaves the ALREADY-ROSTERED path alone — a plain wake still needs no stream", () => {
    arm([]);
    expect(useAppStore.getState().wakePane(PANE, "resume")).toBe(true);
    expect(useAppStore.getState().tabs[0].paneIds).toContain(PANE);
  });

  // #173 (studio-code:director): `bsc plan fleet model <id> qwen3.5:9b` stored the model, but no
  // harness actually consumed it — every pane launched on the fleet-wide toggle (default "claude"),
  // so a director-assigned local model silently ran on Claude Code's own default, no ollama/bsc-agent
  // process anywhere in the pane's tree. A stream's own local model must now win the HARNESS too, on
  // both launch paths — a fresh `fleetStartProject` and a `wakePane` adoption.
  describe("a stream's own local model overrides the fleet's default harness (#173)", () => {
    const LOCAL: AgentStream & { cwd: string } = { ...NEVER_LAUNCHED, model: "qwen3.5:9b" };

    it("fleetStartProject launches a local-model stream on bsc-agent, and every other pane on the fleet default", () => {
      const streamRow: AgentStream = (({ cwd: _cwd, ...row }) => row)(LOCAL);
      resetFleetPanes();
      useAppStore.setState({
        tabs: [], personas: [], blueprints: [], projectBlueprintId: {}, bscBaseDir: "/base",
        llmProvider: "anthropic", fleetHarness: "claude",
      } as never);
      useAppStore.getState().fleetStartProject("Demo", { recommended: 1, reasoning: "t", streams: [streamRow], director: { enabled: true } }, KEY,
        { hubPath: "/hub", worktreePaths: { [STREAM]: LOCAL.cwd } });
      const st = useAppStore.getState();
      expect(st.paneModels[PANE]).toBe("qwen3.5:9b");
      expect(st.paneProviders[PANE]).toBe("bsc-agent");
      // The director carries no stream model, so it stays on the fleet-wide default — one local
      // worker must not drag the rest of the fleet onto bsc-agent with it.
      expect(st.paneProviders[`${KEY}:director`]).toBe("claude");
    });

    it("wakePane adopts a local-model stream onto bsc-agent the same way", () => {
      resetFleetPanes();
      armUnlaunched();
      useAppStore.setState({ llmProvider: "anthropic", fleetHarness: "claude" } as never);
      useAppStore.getState().wakePane(PANE, "go", LOCAL);
      const st = useAppStore.getState();
      expect(st.paneModels[PANE]).toBe("qwen3.5:9b");
      expect(st.paneProviders[PANE]).toBe("bsc-agent");
    });

    // THE GAP #173 LEFT, and what this file did not catch. Every assertion above checks
    // `paneProviders`, which was always derived correctly — while `paneInitCmds`, the string that
    // ACTUALLY LAUNCHES, was written as the literal "claude" one line above it in both paths. So the
    // provider was decorative: measured on merged main, a `blueprint` stream set to qwen3.5:9b still
    // came up as `pty[studio-code:blueprint] created · provider=claude`.
    it("writes the HARNESS as the init cmd, not the literal claude — the provider alone launches nothing", () => {
      resetFleetPanes();
      armUnlaunched();
      useAppStore.setState({ llmProvider: "anthropic", fleetHarness: "claude" } as never);
      useAppStore.getState().wakePane(PANE, "go", LOCAL);
      const st = useAppStore.getState();
      expect(st.paneInitCmds[PANE]).toBe("bsc-agent");
      // ...and it agrees with the provider. These two disagreeing IS the bug, so pin the pair.
      expect(st.paneInitCmds[PANE]).toBe(st.paneProviders[PANE]);
    });

    it("fleetStartProject writes the harness as the init cmd too", () => {
      const streamRow: AgentStream = (({ cwd: _cwd, ...row }) => row)(LOCAL);
      resetFleetPanes();
      useAppStore.setState({
        tabs: [], personas: [], blueprints: [], projectBlueprintId: {}, bscBaseDir: "/base",
        llmProvider: "anthropic", fleetHarness: "claude",
      } as never);
      useAppStore.getState().fleetStartProject("Demo", { recommended: 1, reasoning: "t", streams: [streamRow], director: { enabled: true } }, KEY,
        { hubPath: "/hub", worktreePaths: { [STREAM]: LOCAL.cwd } });
      const st = useAppStore.getState();
      expect(st.paneInitCmds[PANE]).toBe("bsc-agent");
      // The director has no stream wiring, so it keeps the fleet-wide harness — one local worker
      // must not drag the rest of the fleet with it, on the init cmd any more than on the provider.
      expect(st.paneInitCmds[`${KEY}:director`]).toBe("claude");
    });

    it("a Claude stream still gets the claude init cmd — the fix must not invert the default", () => {
      resetFleetPanes();
      armUnlaunched();
      useAppStore.setState({ llmProvider: "anthropic", fleetHarness: "claude" } as never);
      useAppStore.getState().wakePane(PANE, "go", { ...NEVER_LAUNCHED, model: "opus-4.5" });
      expect(useAppStore.getState().paneInitCmds[PANE]).toBe("claude");
    });

    it("a Claude-tier stream model stays on the fleet default — only a NON-tier model forces bsc-agent", () => {
      resetFleetPanes();
      armUnlaunched();
      useAppStore.setState({ llmProvider: "anthropic", fleetHarness: "claude" } as never);
      useAppStore.getState().wakePane(PANE, "go", { ...NEVER_LAUNCHED, model: "opus-4.5" });
      const st = useAppStore.getState();
      expect(st.paneModels[PANE]).toBe("opus-4.5");
      expect(st.paneProviders[PANE]).toBe("claude");
    });
  });
});

// ── the grid has to have a cell for it (#a-woken-pane-needs-a-cell-in-the-grid) ──────────────────
//
// Every test above uses a `2×2` fixture, so there was always a spare cell and the layout never had to
// grow. A REAL build tab whose fleet never launched holds one pane — the director — and is `1×1`. So
// seating a second id put it outside the grid: the pane was in the roster, fully wired, with the right
// cwd and role, and TerminalView never mounted it, so `pty_create` never ran. Observed on the live
// app: `woke studio-code:accessibility` returned success and `bsc fleet list` still said `stopped`.
//
// The success is the dangerous half — `wakePane` returned true because it had done everything it
// thought it had to.
describe("a woken pane gets a cell, not just a slot in the array", () => {
  beforeEach(() => { resetFleetPanes(); useAppStore.setState({ tabs: [] }); });

  /** The shape a director-only build tab actually has. */
  function armOnePaneTab() {
    useAppStore.setState({
      tabs: [{ ...buildTab([`${KEY}:director`]), layout: "1×1" }],
      fleetPaneStreams: {}, disabledPanes: {}, dormantPanes: {}, endedPanes: {},
      personas: [], blueprints: [], projectBlueprintId: {},
    } as never);
  }

  it("grows the layout so the pane it just seated can render", () => {
    armOnePaneTab();
    expect(useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED)).toBe(true);
    const tab = useAppStore.getState().tabs[0];
    const ids = tab.paneIds ?? [];
    expect(ids).toEqual([`${KEY}:director`, PANE]);
    const [cols, rows] = tab.layout.split("×").map(Number);
    expect(cols * rows, `the grid must hold ${ids.length} panes, got ${tab.layout}`)
      .toBeGreaterThanOrEqual(ids.length);
  });

  it("grows the layout for a pane that is ALREADY seated but does not fit", () => {
    // The correction. Checking capacity only where the pane is SEATED was not enough: once seated, the
    // next wake finds an owning tab, takes the early path, and skipped the check — so a pane that never
    // fit stayed outside the grid forever, and every wake killed its PTY and remounted a grid without
    // it. Observed live: a `live` worker became `stopped` once per wake, while the wake said it worked.
    useAppStore.setState({
      tabs: [{ ...buildTab([`${KEY}:director`, PANE]), layout: "1×1" }],
      fleetPaneStreams: { [PANE]: { id: STREAM, name: "API", repo: "own/api", owns: [], issues: [], dependsOn: [] } },
      disabledPanes: {}, dormantPanes: {}, endedPanes: {},
    } as never);
    expect(useAppStore.getState().wakePane(PANE, "go")).toBe(true);
    const tab = useAppStore.getState().tabs[0];
    const [cols, rows] = tab.layout.split("×").map(Number);
    expect(cols * rows, `a seated pane still needs a cell; layout ${tab.layout}`)
      .toBeGreaterThanOrEqual((tab.paneIds ?? []).length);
  });

  it("leaves a layout that already fits exactly as it was", () => {
    // Reshaping a grid the user arranged, to seat a pane that already had a home, would be a second bug.
    arm(["", `${KEY}:director`]);
    const before = useAppStore.getState().tabs[0].layout;
    useAppStore.getState().wakePane(PANE, "go", NEVER_LAUNCHED);
    expect(useAppStore.getState().tabs[0].layout).toBe(before);
  });
});

// ls-stream: unit tests for the load migration stream wiring in fleetStartProject (#ls-stream).
//
// Verifies that when a fleet plan contains the "load-stream" AgentStream with the correct
// owns/dependsOn, fleetStartProject wires paneRoleGlobs, fleetPaneStreams, and the startup
// prompt doc correctly — without requiring a real git worktree or Tauri process.

import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "./";
import { resetFleetPanes } from "@/test/storeReset";
import type { AgentStream, FleetPlan } from "@/features/planner/fleet/planFleet";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

const LOAD_STREAM_OWNS = [
  "src/store/index.ts",
  "src-tauri/src/lib.rs",
  "@/features/planner/LoadReconcile.tsx",
  "crates/data/src/reconcile.rs",
  "crates/data/src/ddl.rs",
  "prompts/load-stream-kickoff.md",
  "src/__tests__/loadStream.test.ts",
  "src/__tests__/loadReconcile.test.tsx",
];

function loadStream(p: Partial<AgentStream> = {}): AgentStream {
  return {
    id: "load-stream",
    name: "Build-time load",
    repo: "org/studio-code",
    owns: LOAD_STREAM_OWNS,
    issues: ["ls-stream", "ls-reconcile-ui", "ls-lineage-verify"],
    dependsOn: ["source-experience"],
    prompt: "prompts/load-stream-kickoff.md",
    ...p,
  };
}

function fleet(streams: AgentStream[]): FleetPlan {
  return {
    recommended: 2,
    reasoning: "test",
    streams,
    director: { enabled: false },
  };
}

const PROJECT_NAME = "migration-test";
const PROJECT_KEY  = sanitizeProjectKey(PROJECT_NAME);

describe("load-stream fleet wiring (#ls-stream)", () => {
  beforeEach(() => {
    // #3836: `paneRoleGlobs` is what this suite ASSERTS on and a sibling launch populates it, so it
    // has to be cleared here or a later test reads the earlier project's globs.
    resetFleetPanes();
    useAppStore.setState({ tabs: [], bscBaseDir: "/home/user/.base-studio-code" });
  });

  it("paneRoleGlobs contains all load-stream owns, expanding trailing-slash globs", () => {
    const rows = useAppStore.getState().fleetStartProject(PROJECT_NAME, fleet([loadStream()]), PROJECT_KEY);
    const { paneRoleGlobs } = useAppStore.getState();

    // Find the pane the LOAD STREAM landed in — by its stream id, not by "the first pane with any
    // globs". The commons lane carries globs now (#funnel-commons-and-integration-streams) and it
    // launches FIRST, so a positional lookup silently reads the commons set instead.
    const { fleetPaneStreams } = useAppStore.getState();
    const paneId = Object.keys(fleetPaneStreams).find((k) => fleetPaneStreams[k].id === "load-stream");
    expect(paneId).toBeDefined();
    const globs = paneRoleGlobs[paneId!];

    // Every owned path from LOAD_STREAM_OWNS should appear in the role globs
    for (const owned of LOAD_STREAM_OWNS) {
      const expected = owned.endsWith("/") ? owned + "**" : owned;
      expect(globs).toContain(expected);
    }

    // One roster row per session: the load stream plus the two lanes every project now gets.
    expect(rows.length).toBe(3);
  });

  it("fleetPaneStreams records the load-stream AgentStream", () => {
    useAppStore.getState().fleetStartProject(PROJECT_NAME, fleet([loadStream()]), PROJECT_KEY);
    const { fleetPaneStreams } = useAppStore.getState();
    const streams = Object.values(fleetPaneStreams);
    // The load stream plus the commons + integration lanes.
    expect(streams.length).toBe(3);
    const s = streams.find((x) => x.id === "load-stream")!;
    expect(s).toBeDefined();
    expect(s.dependsOn).toContain("source-experience");
    expect(s.issues).toEqual(expect.arrayContaining(["ls-stream", "ls-reconcile-ui", "ls-lineage-verify"]));
