import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { compileVariantsCss } from "@/shared/ui/kit/variants";
import { flattenTokens, type StyleDescriptor } from "@/features/designs/lib/styleContract";

// #3394 — the FIRST SLICE of #2553: Button is the "exhausted" component. Every VISUAL property of
// `.btn` resolves from a `--btn-*` token the design store owns, so the designer LLM can restyle it —
// a brand-new variant included — entirely through `bsc ui`, live, with zero React edits.
//
// The bug these tests exist to prevent is subtle and was the ORIGINAL state of this component: the
// runtime applier (`applyThemeToRoot`) faithfully writes ANY token a theme defines to `:root`, and
// `kitTokens()` is not allow-listed — so `--btn-height` could always be SET. It just did nothing,
// because `.btn` said `height:28px`. A token nothing consumes is indistinguishable from a token that
// works, right up until a designer tries to use it. Hence the load-bearing assertion here is
// CONSUMPTION (test 2), not declaration.

const TOKENS_CSS = join(process.cwd(), "src/styles/tokens.css");
const DESCRIPTOR = join(process.cwd(), "src-tauri/data/ui/style-descriptor.json");
const css = readFileSync(TOKENS_CSS, "utf8").replace(/\r\n/g, "\n");
const descriptor = JSON.parse(readFileSync(DESCRIPTOR, "utf8")) as StyleDescriptor;

/** Every `.btn…{ … }` rule body in tokens.css, keyed by its selector. */
function btnRules(): { selector: string; body: string }[] {
  const out: { selector: string; body: string }[] = [];
  for (const m of css.matchAll(/^(\.btn[^{]*)\{([^}]*)\}/gm)) {
    out.push({ selector: m[1].trim(), body: m[2] });
  }
  return out;
}

/** Split a rule body into `prop: value` pairs, dropping comments and blanks. */
function decls(body: string): [string, string][] {
  return body
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .split(";")
    .map((d) => d.trim())
    .filter(Boolean)
    .map((d) => {
      const i = d.indexOf(":");
      return [d.slice(0, i).trim(), d.slice(i + 1).trim()] as [string, string];
    });
}

// STRUCTURE and BEHAVIOUR, not design — #2553's reach table puts these outside the designer's line
// ("a component's internal structure/DOM" needs code once; "behavior" is never design). They stay
// hardcoded deliberately, so this allowlist is the spec for what "exhausted" excludes.
const STRUCTURAL = new Set(["display", "align-items", "cursor"]);

describe("Button is token-exhausted (#3394, first slice of #2553)", () => {
  it("has NO hardcoded visual literal — every non-structural declaration reads a --btn-* token", () => {
    const rules = btnRules();
    expect(rules.length, "expected the .btn rules to be found in tokens.css").toBeGreaterThan(5);

    const offenders: string[] = [];
    for (const { selector, body } of rules) {
      for (const [prop, value] of decls(body)) {
        if (STRUCTURAL.has(prop)) continue;
        // `padding:0 var(--btn-pad-x)` keeps a literal 0 for the VERTICAL axis on purpose: the button
        // is a fixed-height inline-flex box that centres its content, so vertical padding is inert —
        // tokenizing it would offer the designer a knob that cannot change what is rendered.
        if (!value.includes("var(--btn-")) offenders.push(`${selector} { ${prop}: ${value} }`);
      }
    }
    expect(offenders, `these .btn declarations still hardcode a visual value:\n${offenders.join("\n")}`).toEqual([]);
  });

  it("CONSUMES every --btn-* token the descriptor declares (a token nothing reads is a dead knob)", () => {
    // The exact failure mode this slice fixes: a token can be declared, themed and applied to :root
    // and still do nothing, because no rule references it. Declaration is not reach — consumption is.
    const declared = flattenTokens(descriptor)
      .map((t) => t.name)
      .filter((n) => n.startsWith("--btn-"));
    expect(declared.length).toBeGreaterThan(15);

    const unread = declared.filter((name) => !css.includes(`var(${name})`));
    expect(unread, `declared but never consumed by tokens.css: ${unread.join(", ")}`).toEqual([]);
  });

  it("defaults reproduce the pre-tokenization values exactly (a zero-visual-change landing)", () => {
    // Pinning these is the whole basis for claiming the commit is visually inert. If someone changes a
    // default they must change it here too — which is the point: it becomes a deliberate design edit.
    const expected: Record<string, string> = {
      "--btn-height": "28px",
      "--btn-pad-x": "12px",
      "--btn-gap": "6px",
      "--btn-font-size": "11px",
      "--btn-font-weight": "400",
      "--btn-border-width": "1px",
      "--btn-disabled-opacity": "0.4",
      "--btn-primary-font-weight": "600",
      "--btn-primary-hover-brightness": "1.05",
      "--btn-sm-height": "24px",
      "--btn-sm-pad-x": "9px",
      "--btn-sm-font-size": "10.5px",
    };
    const byName = new Map(flattenTokens(descriptor).map((t) => [t.name, t.default]));
    for (const [name, value] of Object.entries(expected)) {
      expect(byName.get(name), `${name} default drifted`).toBe(value);
    }
  });

  it("lets a data-defined variant change SIZE and TYPE — the reach that did not exist before", () => {
    // Before this slice a variant could only restyle colour/radius: `.btn` hardcoded height, padding
    // and font-size, so a variant setting them was silently inert. This is the proof of the new reach,
    // and it runs through the REAL compiler the app uses (`compileVariantsCss`), not a mock.
    const out = compileVariantsCss([
      {
        id: "btn:brand",
        component: "btn",
        variant: "brand",
        tokens: { height: "40px", "pad-x": "20px", "font-size": "14px", "font-weight": "700", bg: "var(--accent)" },
      },
    ]);

    expect(out).toContain(".btn.brand {");
    expect(out).toContain("--btn-height: 40px;");
    expect(out).toContain("--btn-pad-x: 20px;");
    expect(out).toContain("--btn-font-size: 14px;");
    expect(out).toContain("--btn-font-weight: 700;");

    // …and the emitted custom properties are exactly the ones `.btn` reads, so the rule actually bites.
    for (const name of ["--btn-height", "--btn-pad-x", "--btn-font-size", "--btn-font-weight"]) {
      expect(css, `${name} must be consumed by .btn for the variant to have any effect`).toContain(`var(${name})`);
    }
  });

  it("still refuses an injecting value in a variant (the guard is not weakened by new token types)", () => {
    // `number`/`font` widen what `bsc ui tokens` LABELS, never what the compiler ACCEPTS.
    const out = compileVariantsCss([
      { id: "btn:evil", component: "btn", variant: "evil", tokens: { height: "40px}html{display:none" } },
    ]);
    expect(out).toBe("");
  });
});

// What `matchGlob` actually means, captured from the LIVE TypeScript so the Rust matcher can be
// measured against it.
//
// TWO ENGINES DECIDE ONE WRITE SCOPE. `write-scope.ts`'s `matchGlob` compiles a glob to a RegExp;
// `bsc_util::scope`'s `fnmatch` is a hand-written POSIX-style matcher. The `bsc-scope` hook ENFORCES
// writes with the Rust one, while the role model, the launch write-rules and the warden's
// conformance check all reason with this one. Nothing binds them.
//
// This file is the measurement, not a claim: it records what the TypeScript does for pairs chosen to
// separate the two readings, and the Rust side asserts against it. A disagreement is a finding.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/globSemantics.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { matchGlob } from "@/shared/lib/session/writeScope";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/globSemantics.fixtures.json");

/** Each pair is chosen to separate the two readings, not to be representative traffic. */
const PAIRS: Array<[string, string, string]> = [
  // [why it is here, glob, path]
  ["plain literal", "src/a.ts", "src/a.ts"],
  ["literal miss", "src/a.ts", "src/b.ts"],
  ["* within one segment", "src/*.ts", "src/a.ts"],
  ["* ACROSS a separator — the security case", "src/*.ts", "src/a/b.ts"],
  ["* across two separators", "src/*.ts", "src/a/b/c.ts"],
  ["** across a separator", "src/**/*.ts", "src/a/b.ts"],
  ["** at the tail", "src/**", "src/a/b/c.ts"],
  ["** matching nothing", "src/**", "src/"],
  ["* does not escape the prefix", "src/*.ts", "lib/a.ts"],
  ["anchoring — no prefix match", "src/a.ts", "x/src/a.ts"],
  ["anchoring — no suffix match", "src/a.ts", "src/a.tsx"],
  ["? as a wildcard or a literal", "src/a?.ts", "src/ab.ts"],
  ["? against a literal question mark", "src/a?.ts", "src/a?.ts"],
  // If `?` is LITERAL these are false; if it is a REGEX QUANTIFIER leaking through the compiler
  // (`a?` = optional 'a') the first is true. That distinction is the difference between a missing
  // feature and an unescaped metacharacter in a security predicate.
  ["? as a leaked regex quantifier — 'a' absent", "src/a?.ts", "src/.ts"],
  ["? as a leaked regex quantifier — 'a' present", "src/a?.ts", "src/a.ts"],
  ["unescaped alternation leaks too?", "src/a|b.ts", "src/a"],
  ["bracket class or literal brackets", "src/[ab].ts", "src/a.ts"],
  ["bracket against literal brackets", "src/[ab].ts", "src/[ab].ts"],
  ["dot is not a wildcard", "src/a.ts", "src/axts"],
  ["plus is literal", "src/a+.ts", "src/a+.ts"],
  ["parens are literal", "src/(a).ts", "src/(a).ts"],
  ["dollar is literal", "src/a$.ts", "src/a$.ts"],
  ["contracts glob from a real capability", "contracts/**/*.json", "contracts/x/y.json"],
  ["real capability glob, one level", "src/**/*.tsx", "src/app/Thing.tsx"],
  ["real capability glob, zero levels", "src/**/*.tsx", "src/Thing.tsx"],
];

function build() {
  return {
    note: "GENERATED from the live TypeScript matchGlob — see globSemantics.fixtures.gen.test.ts",
    pairs: PAIRS.map(([why, glob, path]) => ({ why, glob, path, matches: matchGlob(glob, path) })),
  };
}

describe("what matchGlob means is captured for the Rust matcher to be measured against", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const text = JSON.stringify(build(), null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") writeFileSync(FIXTURE, text);
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("contains both matches and non-matches, or it separates nothing", () => {
    const m = build().pairs;
    expect(m.some((p) => p.matches)).toBe(true);
    expect(m.some((p) => !p.matches)).toBe(true);
  });
});

// The write-scope env, captured from the LIVE TypeScript so the Rust derivation can be proved equal.
//
// Two variables, both pure security:
//
//   BSC_SCOPE_GLOBS — the globs the `bsc-scope` PreToolUse hook hard-blocks outside of. This is the
//                     HARD deny the role gate's allow-only rules lack, and it survives the bypass
//                     posture where `permissions.deny` is ignored entirely.
//   BSC_SCOPES      — the role's per-store access tiers, checked by the store CLIs before a mutating
//                     verb (#2470).
//
// The `bsc-hook--main.rs` record reads the first and BLOCKS on it; `crates/bsc-cli-util` reads the
// second and refuses a store write on it. Rust enforces both on every tool call and computes neither.
//
// The values are read out of `buildAgentEnv` itself rather than recomposed from its parts, so the
// fixture records the decision the LAUNCH actually makes — including its three-way branch, which is
// what the Rust port has to reproduce:
//
//   globs non-empty            → the globs, space-joined
//   empty AND code:none        → the deny-all sentinel (#1916 Step 3.5)
//   empty AND code is not none → UNSET, so an ungated pane stays allow-all
//
// Getting that branch order wrong inverts a hard deny into a permit: `scope_verdict` reads an ABSENT
// scope as "no scope configured" and allows.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/session/writeScopeEnv.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { buildAgentEnv, SCOPE_DENY_ALL } from "@/app/console/lib/sessionLaunch";
import { roleCapability, type SessionRole } from "@/shared/lib/session/sessionRoles";
import type { AppStore } from "@/store/types";

const FIXTURE = join(process.cwd(), "src/shared/lib/session/writeScopeEnv.fixtures.json");
const PANE = "p1";

const BASE = {
  deniedCommands: [], paneRoles: {}, paneRoleGlobs: {}, paneProfiles: {}, agentProfiles: [],
  paneFlows: {}, surfaceCatalog: [], fleetPaneStreams: {}, appRepoRoot: "/repo", bscBaseDir: "/base",
  mcpServers: [], skills: [], sessionSkillOverrides: {}, sessionSkillGroups: {}, skillGroups: [], paneSkills: {},
};

/** Every role the gate knows, plus the glob-carrying variants. `claude` as the provider keeps the
 *  bsc-agent branch of `buildAgentEnv` out of this — the two scope vars are set before it. */
const ROLES: SessionRole[] = [
  "planner", "worker", "director", "triage", "tester", "reviewer",
  "issuer", "juror", "documentor", "designer", "architect", "librarian", "sound-designer", "marketer",
] as SessionRole[];

const SUBJECTS: Array<[string, { role?: string; globs?: string[] }]> = [
  ["no role at all — an ungated pane is never scoped", {}],
  ...ROLES.map((r) => [`role ${r}, no own globs`, { role: r }] as [string, { role?: string; globs?: string[] }]),
  ["worker with own write globs", { role: "worker", globs: ["src/**", "docs/**"] }],
  ["worker with ONE glob", { role: "worker", globs: ["src/**"] }],
  ["designer with own globs — a carve-out role keeps its scoped write", { role: "designer", globs: ["scratch/**"] }],
  ["triage with own globs — code:none WITHOUT a carve-out grants nothing", { role: "triage", globs: ["src/**"] }],
  ["director with own globs — the commons carve-out", { role: "director", globs: ["docs/**"] }],
  ["a glob containing a space-free path stays space-joined", { role: "worker", globs: ["a/**", "b/**", "c/**"] }],
];

const envFor = (role: string | undefined, globs: string[] | undefined) =>
  buildAgentEnv(
    { ...BASE, paneRoles: role ? { [PANE]: role } : {}, paneRoleGlobs: globs ? { [PANE]: globs } : {} } as unknown as AppStore,
    PANE,
    "claude",
    "",
  );

describe("writeScopeEnv fixtures", () => {
  it("captures BSC_SCOPE_GLOBS and BSC_SCOPES over every role", () => {
    const cases = SUBJECTS.map(([label, { role, globs }]) => {
      const env = envFor(role, globs) ?? {};
      return {
        label,
        role: role ?? null,
        writeGlobs: globs ?? [],
        // The resolved capability, so Rust can deserialize it rather than needing a role→capability
        // function. The self-check below proves it is the one the live launch used.
        capability: role ? roleCapability(role as SessionRole, globs?.length ? { writeGlobs: globs } : {}) ?? null : null,
        scopeGlobs: env.BSC_SCOPE_GLOBS ?? null,
        scopes: env.BSC_SCOPES ?? null,
      };
    });
    const next = {
      note: "GENERATED from @/app/console/lib/sessionLaunch buildAgentEnv — do not hand-edit; see the .gen.test.ts",
      denyAllSentinel: SCOPE_DENY_ALL,
      cases,
    };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("is non-vacuous: all three branches actually occur in the corpus", () => {
    const scoped = SUBJECTS.filter(([, s]) => {
      const g = envFor(s.role, s.globs)?.BSC_SCOPE_GLOBS;
      return g && g !== SCOPE_DENY_ALL;
    });
    const sentinel = SUBJECTS.filter(([, s]) => envFor(s.role, s.globs)?.BSC_SCOPE_GLOBS === SCOPE_DENY_ALL);
    const unset = SUBJECTS.filter(([, s]) => !envFor(s.role, s.globs)?.BSC_SCOPE_GLOBS);

    expect(scoped.length, "no role produced real globs — the fixture would not exercise the first branch").toBeGreaterThan(0);
    expect(sentinel.length, "no role produced the deny-all sentinel — #1916 Step 3.5 would be untested").toBeGreaterThan(0);
    expect(unset.length, "no case left the scope UNSET — the ungated branch would be untested").toBeGreaterThan(0);
  });

  it("an ungated pane is never scoped — the branch that must stay allow-all", () => {
    const env = envFor(undefined, undefined);
    expect(env?.BSC_SCOPE_GLOBS, "a pane with no role must not be scoped at all").toBeUndefined();
    expect(env?.BSC_SCOPES, "and gets no store scopes either").toBeUndefined();
  });
});

/**
 * @vitest-environment jsdom
 *
 * This file lives under `lib/`, which vitest's `node` project covers, but it genuinely needs a DOM.
 * A per-file docblock beats the project's environment, so the requirement is stated where a reader
 * meets it. See the `projects` split in vitest.config.ts for why the default is `node` here.
 */
// shapePreview render verification (#3439) — the shape-tier data must render in the REAL target
// components without crashing and produce NON-EMPTY output (the acceptance's "previews with real data,
// never a broken preview"). jsdom has no layout, but it renders the DOM tree and throws on a bad access —
// which is exactly the risk (feeding generated objects into a component that hard-reads a field). The
// visual polish is confirmed in-app; this pins the crash-safety + non-emptiness headlessly.
import { describe, it, expect } from "vitest";
import { render } from "@testing-library/react";
// Barrel-free import of the real dataset source — see shapePreview.test.ts for why the barrel is avoided.
// eslint-disable-next-line no-restricted-imports -- barrel-free path avoids the module-init cycle (#3439)
import { datasetForStructure } from "@/features/algorithms/viz/previewDataset";
import { ActivityFeed } from "@/shared/ui/data/ActivityFeed";
import { CollectionPage } from "@/shared/ui/pages/CollectionPage";
import { NetworkPage } from "@/shared/ui/pages/NetworkPage";
import { Tree, type TreeNodeData } from "@/shared/ui/layouts/Tree";
import { shapePreviewData } from "@/features/designs/lib/shapePreview";
import type { ComponentRecord, DataShape, PropSpec } from "@/features/designs/lib/model";

const prop = (name: string, type: string): PropSpec => ({ name, type, req: false, desc: "" });
const comp = (shapes: DataShape[], props: PropSpec[]): ComponentRecord => ({
  id: "c", name: "C", kitId: "react-ui", role: "composite", version: "1.0.0", used: 0,
  tags: [], variants: [], composes: [], props, whenUse: [], whenNot: [], src: "", srcText: "", shapes,
});

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const listItems = (): any[] => JSON.parse(shapePreviewData(comp(["list"], [prop("items", "T[]")]), datasetForStructure).items);
const graphData = () => {
  const o = shapePreviewData(comp(["graph"], [prop("nodes", "T[]"), prop("edges", "T[]")]), datasetForStructure);
  return { nodes: JSON.parse(o.nodes), edges: JSON.parse(o.edges) };
};
const treeNodes = (): TreeNodeData[] => JSON.parse(shapePreviewData(comp(["tree"], [prop("nodes", "T[]")]), datasetForStructure).nodes);

describe("shape-tier data renders in the real components (#3439)", () => {
  it("ActivityFeed renders the generated items — Avatar(login) + action, no crash", () => {
    const items = listItems();
    expect(items.length).toBeGreaterThan(0);
    const { container } = render(<ActivityFeed items={items} hint="" loading={false} tone={{}} />);
