const store = (s: Snap) =>
  ({ llmModel: "", claudeApiKey: "", openaiKey: "", geminiKey: "", localBaseUrl: "", llmNumCtx: "", paneModels: {}, ...s }) as unknown as AppStore;

/** Subjects: every rule, and the shapes that separate them. */
