// Wait-for deadlock detection, captured from the LIVE TypeScript so the Rust port can be proved equal.
//
// `coord.log` is written by the BACKEND and by the pure-shell `bsc-*` helpers, and
// `crates/logs/src/coord.rs` already parses and reduces it. What did not move is the reasoning ON TOP:
// whether the parked waiters form a wait-for CYCLE.
//
// A deadlock is the one coordination state nothing recovers from. "Satisfied" is monotonic, so the only
// way a parked waiter never wakes is a ring — no producer in it can move, so all of them hang for ever.
//
// TWO DETAILS ARE THE WHOLE CORRECTNESS, and the corpus below exists to pin them:
//   · a LONE node is a cycle only if it waits on ITSELF (otherwise every parked waiter is "deadlocked");
//   · an edge is drawn only to another PARKED waiter (an unsatisfied dep whose producer is still
//     running is not a deadlock — that producer can finish).
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/fleet/deadlock.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { detectDeadlocks, hasDeadlock, defaultProducerOf } from "@/shared/lib/fleet/coordinationDeadlock";
import type { CoordState, CoordRef } from "@/shared/lib/fleet/coordination.types";

const FIXTURE = join(process.cwd(), "src/shared/lib/fleet/deadlock.fixtures.json");

/** A dep token: `id` is a session ref; `contract:name` etc. name another kind. Non-session kinds
 *  exist so the DEFAULT resolver's rule — only `session:` names a producer — has a case that
 *  separates it from a resolver that maps every kind. */
const dep = (token: string): CoordRef =>
  token.startsWith("contract:")
    ? { kind: "contract", name: token.slice("contract:".length) }
    : { kind: "session", id: token };

/** A CoordState carrying only what the detection reads: waiters and the satisfied latches. */
const state = (
  waiters: Array<{ session: string; deps: string[] }>,
  satisfied: string[] = [],
): CoordState =>
  ({
    waiters: waiters.map((w) => ({ session: w.session, deps: w.deps.map(dep), registeredAt: 0 })),
    // The discriminant is `state`, NOT `status` — a latch is
    // `{ state: "satisfied"; source; at } | { state: "failed"; reason; at }`.
    latches: Object.fromEntries(satisfied.map((s) => [`session:${s}`, { state: "satisfied", source: "landed", at: 1 }])),
    waiting: [], asking: [], issues: [], maintaining: [], briefs: [], forks: [], commissions: [], requests: [],
  }) as unknown as CoordState;

type Case = { label: string; waiters: Array<{ session: string; deps: string[] }>; satisfied?: string[] };

const SUBJECTS: Case[] = [
  { label: "no waiters at all", waiters: [] },
  { label: "one waiter, no deps", waiters: [{ session: "a", deps: [] }] },

  // THE SINGLETON RULE: a lone waiter is a cycle only if it waits on itself.
  { label: "a lone waiter waiting on a NON-waiter — not a deadlock", waiters: [{ session: "a", deps: ["ghost"] }] },
  { label: "a SELF-LOOP — a waits on a", waiters: [{ session: "a", deps: ["a"] }] },

  // Rings.
  { label: "a two-ring — a waits on b, b waits on a", waiters: [{ session: "a", deps: ["b"] }, { session: "b", deps: ["a"] }] },
  { label: "a three-ring", waiters: [{ session: "a", deps: ["b"] }, { session: "b", deps: ["c"] }, { session: "c", deps: ["a"] }] },
  { label: "a chain that does NOT close", waiters: [{ session: "a", deps: ["b"] }, { session: "b", deps: ["c"] }, { session: "c", deps: [] }] },
  { label: "two INDEPENDENT rings", waiters: [
    { session: "a", deps: ["b"] }, { session: "b", deps: ["a"] },
    { session: "c", deps: ["d"] }, { session: "d", deps: ["c"] },
  ] },
  { label: "a ring plus an innocent bystander", waiters: [
    { session: "a", deps: ["b"] }, { session: "b", deps: ["a"] }, { session: "z", deps: ["ghost"] },
  ] },

  // THE PARKED-PRODUCER RULE: an edge only counts to another waiter.
  { label: "a waits on b, but b is NOT parked — no edge, no deadlock", waiters: [{ session: "a", deps: ["b"] }] },

  // SATISFIED deps impose no wait.
  { label: "a ring whose edge is SATISFIED — no longer blocking", waiters: [
    { session: "a", deps: ["b"] }, { session: "b", deps: ["a"] },
  ], satisfied: ["a"] },
  { label: "a ring where BOTH deps are satisfied", waiters: [
    { session: "a", deps: ["b"] }, { session: "b", deps: ["a"] },
  ], satisfied: ["a", "b"] },
  { label: "a self-loop whose dep is satisfied", waiters: [{ session: "a", deps: ["a"] }], satisfied: ["a"] },

  // THE DEFAULT RESOLVER'S KIND GATE: only a `session:` dep names a producer. A `contract:` dep
  // resolves to nothing under the default, so it draws NO edge — without a case like this, a resolver
  // that mapped every kind would be indistinguishable from the real one.
  { label: "a CONTRACT dep draws no edge under the default resolver", waiters: [
    { session: "a", deps: ["contract:b"] }, { session: "b", deps: ["a"] },
  ] },
  { label: "a contract dep whose name matches a parked session — still no edge", waiters: [
    { session: "a", deps: ["contract:b"] }, { session: "b", deps: ["contract:a"] },
  ] },

  // Multiple deps, only one of which closes a ring.
  { label: "several deps, one closes a ring", waiters: [
    { session: "a", deps: ["ghost", "b"] }, { session: "b", deps: ["a"] },
  ] },
  { label: "a longer ring with a spur", waiters: [
    { session: "a", deps: ["b"] }, { session: "b", deps: ["c"] }, { session: "c", deps: ["a", "d"] }, { session: "d", deps: [] },
  ] },
];

describe("deadlock fixtures", () => {
  it("captures the detection over every graph shape", () => {
    const cases = SUBJECTS.map((c) => {
      const s = state(c.waiters, c.satisfied);
      return {
        label: c.label,
        waiters: c.waiters,
        satisfied: c.satisfied ?? [],
        deadlocks: detectDeadlocks(s, defaultProducerOf),
        hasDeadlock: hasDeadlock(s, defaultProducerOf),
      };
    });
    const next = { note: "GENERATED from @/shared/lib/fleet/coordinationDeadlock — do not hand-edit; see the .gen.test.ts", cases };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("THE SINGLETON RULE: a lone waiter is a cycle only if it waits on itself", () => {
    expect(detectDeadlocks(state([{ session: "a", deps: ["ghost"] }]), defaultProducerOf)).toEqual([]);
    expect(detectDeadlocks(state([{ session: "a", deps: ["a"] }]), defaultProducerOf)).toHaveLength(1);
  });

  it("THE PARKED-PRODUCER RULE: an edge only counts to another parked waiter", () => {
    // b is not a waiter, so a's dep on it draws no edge — b can still finish.
    expect(hasDeadlock(state([{ session: "a", deps: ["b"] }]), defaultProducerOf)).toBe(false);
    expect(hasDeadlock(state([{ session: "a", deps: ["b"] }, { session: "b", deps: ["a"] }]), defaultProducerOf)).toBe(true);
  });

  it("a SATISFIED dep imposes no wait", () => {
    const ring = [{ session: "a", deps: ["b"] }, { session: "b", deps: ["a"] }];
    expect(hasDeadlock(state(ring), defaultProducerOf)).toBe(true);
    expect(hasDeadlock(state(ring, ["a"]), defaultProducerOf), "the ring is broken").toBe(false);
  });

  it("is non-vacuous: the corpus contains both deadlocked and healthy graphs", () => {
    const v = SUBJECTS.map((c) => hasDeadlock(state(c.waiters, c.satisfied), defaultProducerOf));
    expect(v.filter(Boolean).length, "no deadlock in the corpus").toBeGreaterThan(3);
    expect(v.filter((x) => !x).length, "no healthy graph in the corpus").toBeGreaterThan(3);
  });
});

// The wake prompts, captured from the LIVE TypeScript so the Rust port can be proved equal.
//
// These are what a woken agent READS. `src-tauri/src/fleet/wake.rs` performs the wake and already
// carries one such message of its own; `crates/bsc-fleet/src/cli.rs` states the contract outright —
// "without --prompt the app supplies its standard change-request wake". So the backend wakes the
// session and the sentence telling it what happened was written here.
//
// This session opened on a fleet loop: a director re-sent the ORIGINAL TASK as a --prompt six times,
// because the standard wake it should have fallen back to lived across the boundary.
//
// FOUR PROMPTS, each saying something different on purpose — a woken waiter learns which deps landed
// and HOW; a user-paused session learns the user resumed it; an answered session is told explicitly
// NOT to ask the user; an assigned worker is told to re-read its checkpoint BEFORE beginning.
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/fleet/wakePrompts.fixtures.gen.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  wakePromptFor, waitingWakePrompt, answerWakePrompt, assignWakePrompt, planWakes, coordinationSummary,
  DEFAULT_WAKE_PROMPT,
} from "@/shared/lib/fleet/coordinationWakes";
import { defaultProducerOf } from "@/shared/lib/fleet/coordinationDeadlock";
import type { CoordState, CoordRef, Waiter } from "@/shared/lib/fleet/coordination.types";

const FIXTURE = join(process.cwd(), "src/shared/lib/fleet/wakePrompts.fixtures.json");

const sess = (id: string): CoordRef => ({ kind: "session", id });
const issue = (n: number): CoordRef => ({ kind: "issue", number: n });

/** A CoordState carrying waiters and their latches. `source` is how a dep was satisfied — the part a
 *  fresh session needs in order to trust it. */
const state = (
  waiters: Array<{ session: string; deps: CoordRef[]; checkpoint?: string }>,
  latches: Record<string, { state: "satisfied" | "failed"; source?: string; reason?: string }> = {},
): CoordState =>
  ({
    waiters: waiters.map((w) => ({ ...w, registeredAt: 0 })),
    latches: Object.fromEntries(
      Object.entries(latches).map(([k, v]) =>
        [k, v.state === "satisfied" ? { state: "satisfied", source: v.source ?? "landed", at: 1 } : { state: "failed", reason: v.reason ?? "boom", at: 1 }],
      ),
    ),
    waiting: [], asking: [], issues: [], maintaining: [], briefs: [], forks: [], commissions: [], requests: [],
  }) as unknown as CoordState;

/** `registeredAt` is carried even though no prompt reads it: the fixture is the Rust `Waiter`'s input
 *  too, and that type requires it. A helper that omits a field the CONSUMER needs makes the artifact
 *  lossy in the other direction from the usual — the writer, not the reader. */
const w = (session: string, deps: CoordRef[], checkpoint?: string): Waiter =>
  ({ session, deps, registeredAt: 0, ...(checkpoint ? { checkpoint } : {}) }) as Waiter;

/** Waiter prompts: one dep vs many, with and without a checkpoint, and every satisfaction source. */
const WAITER_CASES: Array<{ label: string; waiter: Waiter; state: CoordState }> = [
  { label: "one dep, landed, no checkpoint", waiter: w("a", [sess("b")]), state: state([], { "session:b": { state: "satisfied", source: "landed" } }) },
  { label: "one dep, with a checkpoint", waiter: w("a", [sess("b")], "cp-17"), state: state([], { "session:b": { state: "satisfied", source: "landed" } }) },
  { label: "TWO deps — the plural must agree", waiter: w("a", [sess("b"), sess("c")], "cp-2"), state: state([], { "session:b": { state: "satisfied", source: "landed" }, "session:c": { state: "satisfied", source: "merged" } }) },
  { label: "a dep satisfied by a different SOURCE", waiter: w("a", [sess("b")]), state: state([], { "session:b": { state: "satisfied", source: "closed" } }) },
  { label: "a dep with NO latch — reported as ready", waiter: w("a", [sess("ghost")]), state: state([]) },
  { label: "an ISSUE dep", waiter: w("a", [issue(4212)], "cp-9"), state: state([], { "#4212": { state: "satisfied", source: "landed" } }) },
  { label: "a mix of kinds", waiter: w("a", [sess("b"), issue(7)]), state: state([], { "session:b": { state: "satisfied", source: "landed" }, "#7": { state: "satisfied", source: "merged" } }) },
];

const WAITING_CASES = [
  { label: "a reason and a checkpoint", waiting: { session: "a", reason: "needs a decision", checkpoint: "cp-3", at: 1 } },
  { label: "a reason, no checkpoint", waiting: { session: "a", reason: "needs a decision", at: 1 } },
  { label: "an EMPTY reason", waiting: { session: "a", reason: "", at: 1 } },
  { label: "a whitespace-only reason", waiting: { session: "a", reason: "   ", checkpoint: "cp-1", at: 1 } },
];

const ANSWER_CASES = [
  { label: "an answer and a checkpoint", answered: { session: "a", answer: "use the second approach", checkpoint: "cp-4" } },
  { label: "an answer, no checkpoint", answered: { session: "a", answer: "use the second approach" } },
  { label: "an EMPTY answer falls back to the notes", answered: { session: "a", answer: "" } },
  { label: "a whitespace-only answer", answered: { session: "a", answer: "  ", checkpoint: "cp-5" } },
];

const ASSIGN_CASES = [
  { label: "title, body and checkpoint", assigned: { session: "a", title: "fix the parser", body: "It drops a trailing comma.", checkpoint: "cp-6" } },
  { label: "no title", assigned: { session: "a", title: "", body: "Do the thing.", checkpoint: "cp-7" } },
  { label: "no body", assigned: { session: "a", title: "fix the parser", body: "" } },
  { label: "neither title nor body", assigned: { session: "a", title: "", body: "" } },
  { label: "a whitespace-only body", assigned: { session: "a", title: "t", body: "   ", checkpoint: "cp-8" } },
];

/** Summary graphs: a healthy wait, a stalled chain, and a deadlocked ring. */
const SUMMARY_CASES = [
  { label: "one waiter, pending", waiters: [{ session: "a", deps: [sess("ghost")] }], latches: {} },
  { label: "a STALLED chain — a dep failed", waiters: [{ session: "a", deps: [sess("b")] }], latches: { "session:b": { state: "failed" as const } } },
  { label: "a DEADLOCKED ring", waiters: [{ session: "a", deps: [sess("b")] }, { session: "b", deps: [sess("a")] }], latches: {} },
  { label: "a satisfied dep is neither stalled nor deadlocked", waiters: [{ session: "a", deps: [sess("b")] }], latches: { "session:b": { state: "satisfied" as const } } },
  { label: "a waiter with a checkpoint", waiters: [{ session: "a", deps: [sess("ghost")], checkpoint: "cp-11" }], latches: {} },
];

describe("wakePrompts fixtures", () => {
  it("captures all four prompts, planWakes and the summary", () => {
    const next = {
      note: "GENERATED from @/shared/lib/fleet/coordinationWakes — do not hand-edit; see the .gen.test.ts",
      waiterPrompts: WAITER_CASES.map((c) => ({ label: c.label, waiter: c.waiter, latches: c.state.latches, prompt: wakePromptFor(c.waiter, c.state) })),
      waitingPrompts: WAITING_CASES.map((c) => ({ label: c.label, waiting: c.waiting, prompt: waitingWakePrompt(c.waiting as never) })),
      answerPrompts: ANSWER_CASES.map((c) => ({ label: c.label, answered: c.answered, prompt: answerWakePrompt(c.answered as never) })),
      assignPrompts: ASSIGN_CASES.map((c) => ({ label: c.label, assigned: c.assigned, prompt: assignWakePrompt(c.assigned as never) })),
      // The STANDARD wake — the fallback for a session that is neither a parked waiter nor paused.
      // Bound here so the Rust twin cannot drift into a different sentence for the same event; that
      // drift is exactly what let a director re-send the original task six times over.
      defaultWakePrompt: DEFAULT_WAKE_PROMPT,
      planned: (() => {
        const s = state([], { "session:b": { state: "satisfied", source: "landed" } });
        return planWakes([w("a", [sess("b")], "cp-1"), w("z", [sess("b")])], s);
      })(),
      // Record the BUILT state, not the shorthand that produced it. The shorthand is a convenience of
      // this generator; the Rust side deserializes real `Waiter` and `LatchStatus` values, so recording
      // the inputs would hand it a shape it cannot read — the artifact lossy on the WRITER side.
      summaries: SUMMARY_CASES.map((c) => {
        const s = state(c.waiters, c.latches as never);
        return {
          label: c.label,
          waiters: s.waiters,
          latches: s.latches,
          view: coordinationSummary(s, defaultProducerOf),
        };
      }),
    };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("a woken waiter is told HOW each dep was satisfied — not merely that it was", () => {
    const s = state([], { "session:b": { state: "satisfied", source: "merged" } });
    expect(wakePromptFor(w("a", [sess("b")]), s), "the source is what lets a fresh session trust it").toContain("(merged)");
  });

  it("the answered wake keeps its explicit 'Do not ask the user'", () => {
    // Without it, a parked session parks again the moment it resumes.
    expect(answerWakePrompt({ session: "a", answer: "go" } as never)).toContain("Do not ask the user");
  });

  it("an assigned worker re-reads its checkpoint BEFORE beginning", () => {
    const p = assignWakePrompt({ session: "a", title: "t", body: "b", checkpoint: "cp" } as never);
    expect(p.indexOf("First re-read"), "the order is the instruction").toBeGreaterThan(p.indexOf("assigned you new work"));
  });

  it("a waiter with no checkpoint gets no checkpoint line at all", () => {
    const s = state([], { "session:b": { state: "satisfied", source: "landed" } });
    expect(wakePromptFor(w("a", [sess("b")]), s)).not.toContain("checkpoint");
  });
});

// The pane-id GRAMMAR, captured from the LIVE TypeScript so Rust can be proved to match it.
//
// ## Why a fixture rather than two hand-written tables
//
// A pane id keys every backend-side map — the pty ledger, the worktree tree, the sandbox Linux user
// and its 700 home, the plan row, the coord.log project scope. The grammar that mints and reads it
// lives in `paneIdentity.ts`, in the renderer, and Rust re-states pieces of it in four places
// (`must_be_gated`, `director_project`, `worker_pane`, `coord_project_of`), none derived from the
// grammar. `epic-frontend-logic-over-backend-resources-belongs-in-rust` moves the derivation.
//
// THE MIRROR HAS ALREADY BROKEN ONCE, AND IT DEADLOCKED. `paneNeedsGate` exists because Rust and the
// frontend disagreed about which panes need a gate file: Rust refused a gated pane whose cwd had no
// gate, and the only writer of that file sat behind a frontend flag that is false for a restored pane,
// so the pane could never write the file that would let it launch — silently. Measured at 30 hubs with
// no gate file and 10 directors refused in one run.
//
// What guards it today is TWO HAND-COPIED TABLES: `paneNeedsGate.test.ts` says in a comment that it
// asserts "THE SAME TABLE" the Rust test does. Two tables that must agree, maintained by hand, are the
// arrangement this fixture replaces — one artifact, read by both sides, regenerated deliberately:
//
//     UPDATE_FIXTURES=1 npx vitest run src/app/console/paneIdentity.fixtures.gen.test.ts
//
// A regeneration that changes the file is a CHANGE OF GRAMMAR. Read the diff before committing it.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  positionalPaneId,
  manualPaneId,
  fleetPaneId,
  directorPaneId,
  triagePaneId,
  isManualPaneId,
  isPlanningPaneId,
  paneNeedsGate,
  parsePaneIdentity,
  sandboxUserIdentity,
  paneCwdRecovery,
  paneIdFor,
  paneBelongsToTab,
} from "@/app/console/lib/paneIdentity";
import {
  aggregateTabState,
  clearTabStatuses,
  paneCountForLayout,
  type PaneStatus,
  type StatusTab,
} from "@/app/console/lib/paneStatus";

const FIXTURE = join(process.cwd(), "src/app/console/paneIdentity.fixtures.json");

/**
 * ONE corpus, run through every classifier — so "Rust agrees about this id" is a single claim rather
 * than four lists that can drift apart. It deliberately includes the shapes the grammar's own doc
 * comment calls out as AMBIGUOUS, because those are what a tidier port would quietly change.
 */
const IDS = [
  // Minted, well-formed.
  "t0p0", "t12p3", "t10p20",
  "man:tab_abc:p2", "man:tab-with-dashes:p0", "man:tab_abc:p007",
  "studio-code:api", "studio-code:director", "studio-code:owner/name:triage",
  "alpha:web", "alpha:repo:triage",
  // The planner's deliberate exception to the <key>:<stream> scheme.
  "planning_studio-code", "planning_alpha",
  // DOCUMENTED AMBIGUITIES. A stream literally named `director`, and a two-part `<key>:triage`,
  // classify as director/worker respectively — real planner stream ids never collide with those
  // reserved tails, but a port must reproduce the collision rather than "fix" it.
  "studio-code:triage", "studio-code:director:extra", "studio-code:a:b:triage",
  // A tabId containing a colon — the manual regex is greedy, so it wins over the worker shape.
  "man:a:b:p3",
  // A `man:` prefix that does NOT match the manual regex falls through to the WORKER shape, with
  // "man" read as a project key. Ugly and real.
  "man:tab:p", "man:", "man:a:p1:p2",
  // `(.+)` needs at least one character, so an EMPTY tab id is not the manual shape either — it
  // falls through to the worker rule with "man" read as a project key.
  "man::p0",
  // Empty segments, in every position.
  "", ":director", "studio-code:", "studio-code::", ":triage", "::triage", ":",
  // An EMPTY repo segment still classifies as triage (repo ""), and the cwd recovery then declines
  // because it needs a repo — two rules reading one id and reaching different answers.
  "studio-code::triage",
  // Not the grammar at all.
  "scratch", "t0p", "tp0", "debug-studio:req-7",
];

/** Minting is the inverse the parser is checked against; both directions are in the fixture. */
const MINTS = {
  positional: [[0, 0], [12, 3], [10, 20]] as [number, number][],
  manual: [["tab_abc", 2], ["tab-with-dashes", 0], ["a:b", 3]] as [string, number][],
  fleet: [["studio-code", "api"], ["alpha", "web"]] as [string, string][],
  director: ["studio-code", "alpha"],
  triage: [["studio-code", "owner/name"], ["alpha", "repo"]] as [string, string][],
};

/** The sandbox-user decision reads the grammar, and BOTH arguments matter. */
const SANDBOX: [string, string | undefined][] = [
  ["studio-code:api", "bsc-agent-sandbox"],
  ["studio-code:director", "bsc-agent-sandbox"],
  ["studio-code:owner/name:triage", "bsc-agent-sandbox"],
  ["man:tab_abc:p2", "bsc-agent-sandbox"],
  ["t0p0", "bsc-agent-sandbox"],
  ["planning_studio-code", "bsc-agent-sandbox"],
  ["scratch", "bsc-agent-sandbox"],
  // No distro ⇒ never a per-agent user, whatever the pane is.
  ["studio-code:api", undefined],
  // An EMPTY distro is falsy in the reducer, exactly like an absent one.
  ["studio-code:api", ""],
  ["studio-code:director", undefined],
];

/**
 * The tab shapes `paneIdFor` dispatches on, in the order its own doc comment lists them: a minted
 * `paneIds[idx]` wins, then a `kind`-bearing (fleet/triage) tab keeps the positional id, then a manual
 * tab with a stable `id` mints a `man:` id, then an id-less legacy tab falls back to positional.
 *
 * Each shape appears with a pane index that IS minted and one that is not, because the minted-wins
 * rule is per-INDEX: a fleet tab with two minted ids still falls through to positional for cell 2.
 */
const TABS: { label: string; tab: StatusTab }[] = [
  { label: "legacy id-less", tab: { layout: "2×1" } },
  { label: "manual with stable id", tab: { id: "tab_abc", layout: "2×2" } },
  { label: "build kind, no mints", tab: { kind: "build", id: "tab_fleet", layout: "2×1" } },
  {
    label: "build kind with mints",
    tab: { kind: "build", id: "tab_f2", layout: "2×2", paneIds: ["studio-code:director", "studio-code:api"] },
  },
  {
    label: "triage kind, sparse mints",
    // A HOLE in paneIds: index 0 is absent, so cell 0 falls through to positional while cell 1 is
    // minted. A port that treats paneIds as all-or-nothing passes every dense case and fails here.
    tab: { kind: "triage", id: "tab_t", layout: "2×1", paneIds: [undefined as unknown as string, "alpha:repo:triage"] },
  },
  {
    // THE SEPARATING TAB. Every other minted tab here also carries a `kind`, and for those the rule
    // after a hole is positional either way — so an all-or-nothing reading of `paneIds` is
    // indistinguishable. Only a tab with mints and NO kind can tell them apart: the hole must fall
    // through to the MANUAL rule (`man:tab_m2:p0`), not to positional. Added after a deliberate
    // all-or-nothing mutation failed to bite, which is the corpus answering rather than the code.
    label: "manual with sparse mints",
    tab: { id: "tab_m2", layout: "2×1", paneIds: [undefined as unknown as string, "studio-code:api"] },
  },
  // SENTINEL: a malformed layout is not a case of any grid — `paneCountForLayout` falls back to 1.
  { label: "malformed layout", tab: { id: "tab_bad", layout: "not-a-layout" } },
  { label: "one-cell layout", tab: { id: "tab_one", layout: "1×1" } },
];

/** Layout strings, including the ones that are NOT grids. */
const LAYOUTS = ["1×1", "2×1", "2×2", "3×2", "4×4", "not-a-layout", "", "2", "×", "0×3", "2×0"];

/**
 * Status maps to roll up. The vocabulary is three values, so the interesting cases are the
 * PRECEDENCE ones (a run beside an idle) and the ones where a pane is excluded rather than counted.
 */
const ROLLUPS: { label: string; tabIdx: number; tab: StatusTab; statuses: Record<string, PaneStatus>; disabled: Record<string, boolean> }[] = [
  { label: "empty map is idle", tabIdx: 0, tab: TABS[0].tab, statuses: {}, disabled: {} },
  { label: "any run dominates", tabIdx: 0, tab: TABS[0].tab, statuses: { t0p0: "idle", t0p1: "run" }, disabled: {} },
  { label: "on without run", tabIdx: 0, tab: TABS[0].tab, statuses: { t0p0: "on", t0p1: "idle" }, disabled: {} },
  // A run in a DISABLED cell must not pull the tab into "run" — the exclusion is the rule.
  { label: "disabled run is excluded", tabIdx: 0, tab: TABS[0].tab, statuses: { t0p0: "run", t0p1: "on" }, disabled: { t0p0: true } },
  { label: "all disabled is idle", tabIdx: 0, tab: TABS[0].tab, statuses: { t0p0: "run", t0p1: "run" }, disabled: { t0p0: true, t0p1: true } },
  // A status keyed by a pane OUTSIDE the current layout is ignored: shrinking the grid drops it.
  { label: "out-of-grid status ignored", tabIdx: 0, tab: TABS[6].tab, statuses: { t0p0: "idle", t0p1: "run", t0p5: "run" }, disabled: {} },
  { label: "manual tab rolls up by man: id", tabIdx: 3, tab: TABS[1].tab, statuses: { "man:tab_abc:p0": "on", "man:tab_abc:p3": "run" }, disabled: {} },
  { label: "minted build ids roll up", tabIdx: 1, tab: TABS[3].tab, statuses: { "studio-code:director": "on", "studio-code:api": "run" }, disabled: {} },
  { label: "minted id disabled", tabIdx: 1, tab: TABS[3].tab, statuses: { "studio-code:api": "run" }, disabled: { "studio-code:api": true } },
  { label: "sparse mints: hole falls through to positional", tabIdx: 2, tab: TABS[4].tab, statuses: { t2p0: "run", "alpha:repo:triage": "idle" }, disabled: {} },
];

/**
 * `clearTabStatuses` gets its OWN corpus, because reusing the rollup one proved nothing.
 *
 * MEASURED while writing this: every rollup case is keyed entirely by ids the tab owns, so the clear
 * emptied the map every time — and a port that ignored membership and returned `{}` would have passed
 * all ten. That is the separating input the method warns about: the interesting case is a map holding
 * BOTH a pane this tab owns and a pane it does not, where the second must survive.
 */
const CLEARS: { label: string; tabIdx: number; tab: StatusTab; statuses: Record<string, PaneStatus> }[] = [
  {
    label: "drops own positional, keeps another tab's",
    tabIdx: 0,
    tab: TABS[0].tab,
    statuses: { t0p0: "run", t0p1: "on", t1p0: "run", t2p3: "on" },
  },
  {
    label: "drops own manual, keeps a different manual tab's",
    tabIdx: 3,
    tab: TABS[1].tab,
    statuses: { "man:tab_abc:p0": "run", "man:tab_other:p0": "on", t3p0: "run" },
  },
  {
    label: "drops minted ids it owns, keeps a minted id it does not",
    tabIdx: 1,
    tab: TABS[3].tab,
    statuses: { "studio-code:director": "run", "studio-code:api": "on", "alpha:web": "run" },
  },
  {
    label: "keeps everything when nothing belongs",
    tabIdx: 5,
    tab: TABS[1].tab,
    statuses: { "man:tab_other:p1": "run", "alpha:web": "on" },
  },
  { label: "empty map stays empty", tabIdx: 0, tab: TABS[0].tab, statuses: {} },
  {
    label: "an unparseable id is never anyone's, so it survives",
    tabIdx: 0,
    tab: TABS[0].tab,
    statuses: { t0p0: "run", scratch: "on", "": "idle" },
  },
];

/** Membership, which is what a stale-status clear is built on. */
const MEMBERSHIP: { paneId: string; tabIdx: number; tabLabel: string }[] = [];
for (const { label } of TABS) {
  for (const paneId of ["t0p0", "t2p1", "man:tab_abc:p2", "studio-code:api", "studio-code:director", "alpha:repo:triage", "planning_alpha", "", "scratch"]) {
    MEMBERSHIP.push({ paneId, tabIdx: 0, tabLabel: label });
    MEMBERSHIP.push({ paneId, tabIdx: 2, tabLabel: label });
  }
}

function build() {
  return {
    note: "GENERATED from the live TypeScript — see paneIdentity.fixtures.gen.test.ts",
    mints: {
      positional: MINTS.positional.map(([t, p]) => ({ tabIdx: t, paneIdx: p, id: positionalPaneId(t, p) })),
      manual: MINTS.manual.map(([t, p]) => ({ tabId: t, paneIdx: p, id: manualPaneId(t, p) })),
      fleet: MINTS.fleet.map(([k, s]) => ({ projectKey: k, streamId: s, id: fleetPaneId(k, s) })),
      director: MINTS.director.map((k) => ({ projectKey: k, id: directorPaneId(k) })),
      triage: MINTS.triage.map(([k, r]) => ({ projectKey: k, repo: r, id: triagePaneId(k, r) })),
    },
    ids: IDS.map((id) => ({
      id,
      isManual: isManualPaneId(id),
      isPlanning: isPlanningPaneId(id),
      needsGate: paneNeedsGate(id),
      parsed: parsePaneIdentity(id),
      cwdRecovery: paneCwdRecovery(id),
    })),
    sandbox: SANDBOX.map(([id, distro]) => ({
      id,
      distro: distro ?? null,
      user: sandboxUserIdentity(id, distro),
    })),
    // ── the rollup half (`the-pane-status-rollup-is-derived-in-rust-at-parity`) ──
    layouts: LAYOUTS.map((layout) => ({ layout, count: paneCountForLayout(layout) })),
    idFor: TABS.flatMap(({ label, tab }) =>
      [0, 1, 2, 3].flatMap((paneIdx) =>
        [0, 2].map((tabIdx) => ({ tabLabel: label, tabIdx, paneIdx, id: paneIdFor(tab, tabIdx, paneIdx) })),
      ),
    ),
    // `paneIdFor` takes an OPTIONAL tab and falls back to positional — its own separate case, since a
    // corpus of real tabs never exercises the undefined arm.
    idForNoTab: [0, 3].flatMap((tabIdx) => [0, 2].map((paneIdx) => ({ tabIdx, paneIdx, id: paneIdFor(undefined, tabIdx, paneIdx) }))),
    membership: MEMBERSHIP.map(({ paneId, tabIdx, tabLabel }) => ({
      paneId,
      tabIdx,
      tabLabel,
      belongs: paneBelongsToTab(paneId, TABS.find((t) => t.label === tabLabel)!.tab, tabIdx),
    })),
    rollups: ROLLUPS.map(({ label, tabIdx, tab, statuses, disabled }) => ({
      label,
      tabIdx,
      layout: tab.layout,
      statuses,
      disabled,
      state: aggregateTabState(tab, tabIdx, statuses, disabled),
    })),
    clears: CLEARS.map(({ label, tabIdx, tab: clearTab, statuses }) => ({
      label,
      tabIdx,
      statuses,
      // WHOLE MAP recorded, not a count — a port that clears too much and one that clears too little
      // both survive a length check (trap 5: a lossy artifact looks exactly like a passing test).
      remaining: clearTabStatuses(statuses, clearTab, tabIdx),
    })),
  };
}

describe("the pane-id grammar is captured for Rust to match", () => {
  it("matches the committed fixture (UPDATE_FIXTURES=1 to regenerate)", () => {
    const built = build();
    const text = JSON.stringify(built, null, 2) + "\n";
    if (process.env.UPDATE_FIXTURES === "1") {
      writeFileSync(FIXTURE, text);
    }
    expect(existsSync(FIXTURE), `${FIXTURE} is missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(readFileSync(FIXTURE, "utf8")).toBe(text);
  });

  it("covers every kind the parser can return, so a new one cannot slip past the port", () => {
    const built = build();
    const kinds = new Set(built.ids.map((c) => c.parsed?.kind).filter(Boolean));
    expect([...kinds].sort()).toEqual(["director", "manual", "positional", "triage", "worker"]);
  });

  it("covers the REJECTIONS, which are the half a port drops", () => {
    const built = build();
    expect(built.ids.filter((c) => c.parsed === null).length).toBeGreaterThanOrEqual(7);
  });

  /** The two must be able to disagree in the fixture, or it cannot prove they are separate rules. */
  it("contains an id that PARSES as a worker yet needs no gate", () => {
    const built = build();
    const odd = built.ids.filter((c) => c.parsed?.kind === "worker" && !c.needsGate);
    expect(odd.map((c) => c.id)).toContain("studio-code::");
  });

  /** All three rollup values must appear, or the port can hardcode one and pass. */
  it("exercises every status the rollup can produce", () => {
    const built = build();
    expect([...new Set(built.rollups.map((r) => r.state))].sort()).toEqual(["idle", "on", "run"]);
  });

  /** The minted-wins rule is per-INDEX. Without a tab whose paneIds have a HOLE, a port that treats
   *  them as all-or-nothing passes every case here. */
  it("has a tab whose minted ids are sparse, so the fallback is per-cell", () => {
    const built = build();
    const sparse = built.idFor.filter((c) => c.tabLabel === "triage kind, sparse mints");
    expect(sparse.some((c) => c.id.startsWith("t"))).toBe(true); // cell 0 fell through
    expect(sparse.some((c) => c.id === "alpha:repo:triage")).toBe(true); // cell 1 was minted
  });

  /** A disabled RUN must be able to change the answer, or the exclusion rule is untested. */
  it("has a rollup where disabling a pane changes the tab state", () => {
    const built = build();
    const c = built.rollups.find((r) => r.label === "disabled run is excluded");
    expect(c?.state).toBe("on"); // "run" if the disabled cell were counted
  });

  /** `clearTabStatuses` must both KEEP and DROP, and do BOTH in a single case.
   *
   *  The last part is the one that matters: a case that only drops is satisfied by returning `{}`, and
   *  a case that only keeps is satisfied by returning the input unchanged. Only a map where some
   *  entries go and others stay can tell a membership test from either constant. */
  it("has a clear that drops some entries and keeps others in the SAME map", () => {
    const built = build();
    const mixed = built.clears.filter(
      (c) => Object.keys(c.remaining).length > 0 && Object.keys(c.remaining).length < Object.keys(c.statuses).length,
    );
    expect(mixed.map((c) => c.label)).toContain("drops own positional, keeps another tab's");
    expect(mixed.length).toBeGreaterThanOrEqual(3);
    // …and the two degenerate ends are present too, so neither is what the mixed cases rest on.
    expect(built.clears.some((c) => Object.keys(c.remaining).length === Object.keys(c.statuses).length && Object.keys(c.statuses).length > 0)).toBe(true);
    expect(built.clears.some((c) => Object.keys(c.remaining).length === 0 && Object.keys(c.statuses).length === 0)).toBe(true);
  });
});

// The `coord.log` ingest, captured from the LIVE TypeScript so Rust can be proved to match it.
//
// ## Why a fixture rather than a hand-written table
//
// `coord.log` is written by the BACKEND (`crates/logs`, the app's pty env-writer) and by the pure-shell
// `bsc-*` emitters — and parsed only here, in `coordinationLog.ts` over the latch/waiter model in
// `coordinationState.ts`. So the fleet's own state (who is parked, who is ready, what was refused for
// crossing a project boundary) is knowable only while a renderer is alive.
// `epic-frontend-logic-over-backend-resources-belongs-in-rust` moves that derivation.
//
// It is ALREADY duplicated, narrowly and unproven: `crates/logs/src/waiting.rs` re-derives the
// blocked-on-a-human projection of this same fold, and says in its own doc comment that "the pairing
// logic cannot be shared with that reducer (it is TypeScript), so each rule is tested here
// independently rather than assumed equivalent." Independent tests of two copies is exactly how the
// `woke` arm drifted: Rust cleared only a `wait` while this reducer also clears `asking`, so a woken
// session's ask was immortal in `bsc logs waiting`.
//
// A port that is subtly different is worse than no port. So this generates the answer from the
// implementation that is live TODAY and a Rust test asserts its own derivation matches case for case.
// Hand-writing the expectations would only prove Rust agrees with whoever typed the table.
//
// Same pattern as `roleGate.fixtures.json` / `tunnelProtocol.fixtures.json` / `streamGate.fixtures.json`:
// one byte-exact artifact read by BOTH sides. Regenerate deliberately:
//
//     UPDATE_FIXTURES=1 npx vitest run src/shared/lib/fleet/coordLog.fixtures.gen.test.ts
//
// A regeneration that changes the file is a CHANGE OF BEHAVIOUR. Read the diff before committing it.
//
// ## The timestamp domain is deliberately narrow
//
// `parseCoordLine` dates a line with `Date.parse`, which accepts far more than the emitters ever write
// (`date -u +%Y-%m-%dT%H:%M:%SZ`, and the app's `epoch_ms_to_iso8601`, which matches it). Two forms are
// therefore kept OUT of this fixture on purpose, because pinning them would pin the wrong thing:
// a timestamp with no zone (`2026-08-31T12:00:00`) is LOCAL time to `Date.parse`, so the fixture would
// encode the generating machine's timezone; and a fractional-second form is accepted by `Date.parse`
// and not by the Rust reader. Neither is emitted. What IS pinned is the emitted grammar and the
// fall-back-to-0 on a string that is not a time at all.
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import {
  parseCoordLine,
  ingestCoordLog,
  coordProjectOf,
  sameCoordProject,
  refusalKey,
} from "@/shared/lib/fleet/coordinationLog";
import { parseRef, refKey } from "@/shared/lib/fleet/coordinationState";
import type { CrossProjectRefusal } from "@/shared/lib/fleet/coordination.types";

const FIXTURE = join(process.cwd(), "src/shared/lib/fleet/coordLog.fixtures.json");

/** The emitted timestamp grammar — `date -u +%Y-%m-%dT%H:%M:%SZ`. */
const T = (s: number) => `2026-08-31T12:00:${String(s).padStart(2, "0")}Z`;

/** One TSV line, joined exactly as the emitters do. */
const L = (ts: string, session: string, ...rest: string[]) => [ts, session, ...rest].join("\t");

/** Every token `parseRef` can be handed, including the ones it must REJECT. */
const REF_TOKENS = [
  "", "   ", "#42", "#1", "#0", "#-1", "#abc", "#4.5", "#", "42", "007", "0",
  // `Number()` is what `#`-refs go through, so its grammar is part of the contract: it TRIMS, it
  // reads exponent notation, and it maps the empty string to 0. Pinned because a Rust `parse::<f64>`
  // agrees on none of those three by default.
  "# 7", "#1e3", "#  ",
  "contract:TunnelState", "contract:", "contract:  ", "file:src/lib/x.ts", "file:",
  "predicate:tests-pass", "predicate:symbol:Foo", "session:studio-code:api", "session:",
